import type { Exercise } from '@repo/shared'

export const EXERCISES: Exercise[] = [{"id": "seal-push-up", "name": "Seal push-up", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Lie prone (on your stomach) on the ground or on a mat and position your hands directly below your shoulders.", "Keeping your legs straight against the floor, exhale as you straighten your elbows to push your torso up and away from the floor.", "Hold for a count of two.", "Inhale as you reverse the motion to return to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/10/Seal-push-up.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seal-push-up/"}, {"id": "reverse-grip-dumbbell-bench-press", "name": "Reverse-grip dumbbell bench press", "name_ko": "벤치 프레스", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Lie supine (on your back) on a flat bench, gripping a dumbbell in each hand using a supinated or reverse (palms up) grip. If full supination is uncomfortable, you may keep your wrists supinated at a 45 degree angle.", "Position the dumbbells at the sides of your chest.", "Keeping your wrists supinated, exhale as you press the dumbbells upward and inward until your elbows are almost fully extended. If you started with your wrists supinated to only 45 degrees, you can supinate your wrists more as you press up the dumbbells.", "Hold for a count of two and squeeze your chest.", "Inhale as you lower the dumbbells back to the starting position.", "Repeat for the desired number of prescriptions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/07/Reverse-grip-dumbbell-bench-press.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/reverse-grip-dumbbell-bench-press/"}, {"id": "iron-cross-plank", "name": "Iron cross plank", "name_ko": "플랭크", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Get into pushup position on the floor.", "Bring your hands out to the sides as much as you can without letting your chest touch the floor. Your body should form a cross or a T.", "Keeping your body rigid and breathing normally, hold this position for the prescribed duration."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/02/Iron-cross-plank.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/iron-cross-plank/"}, {"id": "triceps-dip-using-assisted-pull-up-machine", "name": "Triceps dip using assisted pull-up machine", "name_ko": "풀업", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Stand with your back facing the assisted pull machine.", "Circle your arms back and grip the padded knee rest behind you. Your fingers should be facing front and your elbows bent and facing back.", "Keeping your elbows close to your body, exhale as you straighten your elbows to push the knee rest down towards the floor.", "Hold for a count of two.", "Inhale as you reverse the motion to return to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/01/Triceps-dip-using-assisted-pull-up-machine.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/triceps-dip-using-assisted-pull-up-machine/"}, {"id": "scapula-dip", "name": "Scapula dip", "name_ko": "딥", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Sit on the side of a bench and place your hands on the edge, by your hips.", "Slide your bottom forward, off the bench, so that your body weight is supported by your arms. Your knees should be bent at a 90-degree angle.", "Keeping your torso upright and arms straight, inhale as you allow your torso to move down towards the floor, letting your ears meet your shoulders.", "Inhale as you drive your shoulder blades down to push your torso back up to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/08/Scapula-dip.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/scapula-dip/"}, {"id": "arm-raise-push-up", "name": "Arm-raise push-up", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Get into a push-up position with your hands slightly wider than shoulder-width apart and your feet wider than hip-width apart.", "Keeping your body straight and rigid, inhale as you lower your chest to the floor.", "Exhale as your push your body back up and then raise one arm.", "Lower your hand down on to the floor to return to the starting position.", "Repeat steps one to three, alternating the arm you raise.", "Perform for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/07/Arm-raise-push-up.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/arm-raise-push-up/"}, {"id": "hyght-dumbbell-fly", "name": "Hyght dumbbell fly", "name_ko": "플라이", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Sit on a bench inclined at 45 degrees. Hold a dumbbell in each hand with your forearms supinated (palms facing upward).", "Slightly bend your elbows and hold your arms slightly out to the sides.", "Keeping your elbows slightly bent, exhale as you bring the dumbbells up and in across your body so that the dumbbells meet and form a V shape at the top of the movement.", "Hold for a count of two and squeeze your chest muscles.", "Inhale as you reverse the movement to return to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/05/Hyght-dumbbell-fly.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/hyght-dumbbell-fly/"}, {"id": "double-dumbbell-pullover", "name": "Double dumbbell pullover", "name_ko": "풀오버", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in each hand, lie on a bench.", "Raise the dumbbells over your chest. Your palms should be facing each other.", "Keeping your arms slightly bent, exhale as you lower the dumbbells behind your head in an arc-like motion until your elbows are level with your ears.", "Hold for a count of two.", "Inhale as you reverse the motion to bring the dumbbells back to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/05/Double-dumbbell-pullover.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/double-dumbbell-pullover/"}, {"id": "decline-push-up-against-a-wall", "name": "Decline push-up against a wall", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["With a wall behind you, get on all fours. Walk your feet up against the wall until your hips are higher than your shoulders.", "Keeping your body straight, inhale as you lower your chest to the floor by flexing your elbows.", "Exhale as you push yourself back up to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/03/Decline-push-up-against-a-wall.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/decline-push-up-against-a-wall/"}, {"id": "incline-dumbbell-fly-on-a-stability-ball", "name": "Incline dumbbell fly on a stability ball", "name_ko": "플라이", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Sit on a stability ball with a dumbbell in each hand.", "Roll downwards until your back is on the ball.", "Raise the dumbbells over your chest with your elbows slightly bent and pointing out to the side. Your shoulders should be rotated internally.", "Inhale as you lower the dumbbells out to your sides in an arc-like motion until you feel a slight stretch in your chest or shoulder.", "Exhale as you return to the starting position by reversing the motion.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/02/Incline-dumbbell-fly-on-a-stability-ball.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-dumbbell-fly-on-a-stability-ball/"}, {"id": "close-grip-push-up-on-knees", "name": "Close-grip push-up on knees", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Get on all fours with your hands positioned directly under your shoulders or closer together.", "Shift your weight on to your hands and lift your feet off the floor. Cross your ankles.", "Maintaining a neutral back, inhale and tuck in your elbows as you lower your chest onto your hands.", "Exhale as you push your body back up to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/01/Close-grip-push-up-on-knees.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/close-grip-push-up-on-knees/"}, {"id": "dumbbell-deficit-push-up", "name": "Dumbbell deficit push-up", "name_ko": "푸시업", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Get into a push-up position on the floor with both of your hands gripping the dumbbells.", "Position your hands wider than shoulder width apart and straighten your body.", "Keep your body straight and inhale as you lower your chest to the floor.", "Exhale as you push your body back up to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/12/Deep-push-up.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-deficit-push-up/"}, {"id": "decline-knee-push-up", "name": "Decline knee push-up", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Get into a pushup position with your knees on a bench behind you and your hands on the ground.", "Position your hands wider than shoulder width apart.", "Keep your body straight and inhale as you lower your chest to the ground by flexing your elbows.", "Exhale as you push yourself back up to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/12/Decline-knee-push-up.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/decline-knee-push-up/"}, {"id": "incline-one-arm-dumbbell-fly-on-a-stability-ball", "name": "Incline one-arm dumbbell fly on a stability ball", "name_ko": "플라이", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Sit on a stability ball with a dumbbell in one hand.", "Roll downwards until your back is on the ball.", "Raise the dumbbell over your chest while keeping your elbow slightly flexed and your shoulder rotated internally. Your elbow should point out to the side.", "Keeping your elbow slightly flexed, inhale as your lower the dumbbell to your side in an arc-like motion until you feel a mild stretch in your chest or shoulder.", "Exhale as you reverse the motion to return to the starting position.", "Repeat for the desired number of repetitions.", "Perform using the opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/12/Incline-one-arm-dumbbell-fly-on-a-stability-ball.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-one-arm-dumbbell-fly-on-a-stability-ball/"}, {"id": "incline-one-arm-dumbbell-fly", "name": "Incline one-arm dumbbell fly", "name_ko": "플라이", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Sit on an inclined bench with a dumbbell in one hand.", "Lie backward and raise the dumbbell over your chest while keeping your elbow slightly flexed.", "Rotate your shoulder internally so that your elbow points out to the side.", "Keeping your elbow slightly flexed, inhale as you lower the dumbbell to your side until you feel a mild stretch in your chest or shoulder.", "Exhale as you return the dumbbell back to the starting position.", "Repeat for the prescribed number of repetitions.", "Repeat with the opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/12/Incline-one-arm-dumbbell-fly.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-one-arm-dumbbell-fly/"}, {"id": "incline-one-arm-dumbbell-press-on-stability-ball", "name": "Incline one-arm dumbbell press on stability ball", "name_ko": "Incline one-arm dumbbell press on stability ball", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Sit on a stability ball with a dumbbell in one hand.", "Roll your buttock downwards until your back is resting against the ball, with your torso forming a 45-degree angle with the floor.", "Spread your feet and position the dumbbell to your chest with your elbow bent and slightly tucked into your torso.", "Exhale as you press the dumbbell upward and inward until your arm is almost fully extended.", "Hold for a count of two.", "Inhale as you lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions.", "Repeat with the opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/12/Incline-one-arm-dumbbell-press-on-a-stability-ball.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-one-arm-dumbbell-press-on-stability-ball/"}, {"id": "close-grip-decline-stability-ball-push-up", "name": "Close-grip decline stability ball push-up", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Get into a push-up position with your hands directly under your shoulders and your feet on the stability ball.", "Keep your body straight and elbows slightly tucked in and inhale as you lower your chest to your hands.", "Exhale as you push your body back up to the starting position.", "Repeat for the prescribed amount of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/12/Close-grip-decline-stability-ball-push-up.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/close-grip-decline-stability-ball-push-up/"}, {"id": "incline-one-arm-dumbbell-bench-press", "name": "Incline one-arm dumbbell bench press", "name_ko": "벤치 프레스", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Sit on an inclined bench with a dumbbell in one hand.", "Position the dumbbell to the side of your chest with your elbow bent and slightly tucked into your torso.", "Spread your feet and grasp the bench with your free hand for support.", "Exhale as you press the dumbbell upward and inward until your arm is almost fully extended.", "Hold for a count of two and squeeze your chest.", "Inhale as you lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions.", "Repeat with the opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/11/Incline-one-arm-dumbbell-bench-press.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-one-arm-dumbbell-bench-press/"}, {"id": "floor-l-sit", "name": "Floor L-sit", "name_ko": "Floor L-sit", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Sit on the floor with your legs straight.", "Position your palms flat on the floor, by the sides of your body, slightly ahead of your hips.", "Keeping your torso upright and engaging your core, press down with your palms to lift your buttocks and legs off the floor, maintaining the ‘L’ shape that your torso and legs form.", "Breathe normally as you hold the position for as long as you can or for the prescribed duration. Your arms should be straight and your torso upright.", "Repeat for the desired number of times."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/10/Floor-L-sit-fixed.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/floor-l-sit/"}, {"id": "dumbbell-squeeze-bench-press", "name": "Dumbbell squeeze bench press", "name_ko": "벤치 프레스", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in each hand, sit on a flat bench and rest one dumbbell on each knee.", "Lie back on the bench and squeeze the dumbbells together, holding them above your chest. Your elbows should not be pointing out the sides; rather, they should be close to your body.", "Spread your legs and plant your feet firmly on the ground.", "Keeping the dumbbells squeezed against each other, exhale as you press the dumbbells upward until your arms are almost fully extended.", "Inhale as you slowly lower the dumbbells to the starting position, still squeezing them against each other.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/09/Dumbbell-Squeeze-Bench-Press.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-squeeze-bench-press/"}, {"id": "dumbbell-press-on-a-stability-ball", "name": "Dumbbell press on a stability ball", "name_ko": "Dumbbell press on a stability ball", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Sit on a stability ball with a dumbbell in each hand.", "Walk your feet forward and roll your hips down and out until your torso is parallel with the floor. Your upper back should be resting on the stability ball and your knees should be bent at a 90-degree angle.", "Position the dumbbells to the sides of your chest, with your elbows bent and slightly tucked in to your body.", "Exhale as you push the dumbbells upward until your elbows are almost fully extended.", "Inhale as you lower the dumbbells in a controlled manner back to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/09/Dumbbell-press-on-a-stability-ball.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-press-on-a-stability-ball/"}, {"id": "machine-assisted-chest-dip", "name": "Machine-assisted chest dip", "name_ko": "딥", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Set the pin to your desired weight (the heavier the weight is, the more assistance it will provide).", "Mount the assisted dip machine, holding the dip bars using an oblique grip (the bar should run diagonally across your palms).", "Lean forward.", "Inhale as you bend your arms to lower your body until you feel a mild stretch in your chest or shoulders. As you descend, allow your elbows to flare out slightly.", "Exhale as you push your body back up to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/10/Machine-assisted-chest-dip.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/machine-assisted-chest-dip/"}, {"id": "one-arm-knee-push-up", "name": "One-arm knee push-up", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Get into a push-up position, supporting your body on your hands and knees instead of on your hands and forefeet. Your hands should be a little wider than shoulder width apart.", "Put one hand behind your back so that you are now only supporting your body on one hand and both knees.", "Keeping one hand behind your back and your body as straight as possible, inhale as you lower your chest to the floor. The elbow of your supporting arm should be tucked in slightly.", "Exhale as you push your body back up to the starting position.", "Repeat for the desired number of repetitions.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/10/One-arm-knee-push-up.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/one-arm-knee-push-up/"}, {"id": "chest-dip", "name": "Chest dip", "name_ko": "체스트 딥", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Mount a wide dip bar using an oblique grip (the bar should run diagonally across your palms).", "Straighten your elbows, lean forward, and flex your hips and knees slightly.", "Inhale as you bend your arms and lower your body until you feel a mild stretch in your chest or shoulders. As you descend, allow your elbows to flare out to the sides a little.", "Exhale as you push your body back up to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/09/Chest-dip.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/chest-dip/"}, {"id": "pike-push-up", "name": "Pike push-up", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Position two flat benches side by side, shoulder-width apart from each other.", "Place each hand on one end of each bench and each foot on the other end of each bench.", "Raise your hips by extending your knees.", "Keeping your legs straight, inhale as you lower your head between the two benches.", "Exhale as you push your body back up to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/07/Pike-push-up.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/pike-push-up/"}, {"id": "dumbbell-fly-on-a-stability-ball", "name": "Dumbbell fly on a stability ball", "name_ko": "플라이", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Sit on a stability ball with a dumbbell in each hand.", "Roll down and out until your upper back is on the ball and your torso is parallel with the floor.", "Raise the dumbbells up so that they are over your chest.", "Firmly plant your feet on the floor for balance.", "Bend your elbows a little, and internally rotate your shoulders so that your elbows point out to the sides.", "Keeping a slight bend in your elbows, inhale as you lower the dumbbells out to your sides.", "Exhale as you return the dumbbells to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/06/Dumbbell-fly-on-a-stability-ball.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-fly-on-a-stability-ball/"}, {"id": "wide-reverse-grip-barbell-bench-press", "name": "Wide reverse-grip barbell bench press", "name_ko": "벤치 프레스", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Lie supine (on your back) on a flat bench and plant your feet firmly on the ground.", "Grasp the bar with a wide reverse grip (palms facing you) and unrack the barbell.", "Inhale as you lower the barbell towards your upper abdomen.", "Exhale as you slowly raise the barbell back up to the starting position.", "Repeat for the desired number of repetitions.", "After you’ve finished, return the barbell to the rack."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/04/Wide-reverse-grip-barbell-bench-press.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/wide-reverse-grip-barbell-bench-press/"}, {"id": "incline-dumbbell-press-on-a-stability-ball", "name": "Incline dumbbell press on a stability ball", "name_ko": "Incline dumbbell press on a stability ball", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Sit on a stability ball with a dumbbell in each hand.", "Roll your butt down and out until your torso forms a 45-degree angle with the floor. Your back should be resting against the stability ball.", "Spread your legs and place your feet flat on the floor.", "Position the dumbbells to the sides of your chest, with your elbows bent and tucked in to your body a little.", "Exhale as you press the dumbbells vertically upward until your elbows are almost fully extended.", "Inhale as you slowly lower the dumbbells to the starting position.", "Repeat the press for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/03/V1F-Dumbbell-incline-press-on-stability-ball.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-dumbbell-press-on-a-stability-ball/"}, {"id": "incline-push-up-on-a-box", "name": "Incline push-up on a box", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Place your hands slightly wider than shoulder-width apart on the edge of a box.", "Placing your body weight on your hands, extend your feet backwards and straighten your body.", "Keeping your body straight and elbows slightly tucked in, inhale as you lower your chest to the edge of the box.", "Exhale as you push your body back up to the starting position.", "Repeat until you meet the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/03/Incline-push-up-on-box.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-push-up-on-a-box/"}, {"id": "side-push-up", "name": "Side push-up", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Lie on your left side on the floor, with your hips straight and your knees bent at a ninety-degree angle.", "Wrap your left arm around your waist to keep it out of the way.", "Place your right hand on the floor, in front of your left shoulder.", "Keeping your hips and torso straight, exhale as you push into your right hand to raise your left shoulder off the floor.", "Hold for a count of two and squeeze your chest.", "Inhale as your reverse the movement and lower your left shoulder back to the floor.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise on your right side, using your left arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2020/01/Side-push-up-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/side-push-up/"}, {"id": "incline-push-up", "name": "Incline push-up", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Place your hands on a box, bench or any sturdy elevated surface, with your hands positioned a little wider than shoulder width apart.", "Extend your feet backwards and straighten your body.", "Keeping your body straight and elbows slightly tucked in, inhale as you lower your chest by flexing your elbows.", "Exhale as you reverse the movement and push your body back up to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/11/Incline-push-up-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-push-up/"}, {"id": "smith-machine-jm-press", "name": "Smith machine JM press", "name_ko": "Smith machine JM press", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Place a flat bench under the bar of the Smith machine so that after you lie down the bar will be able to descend to your upper chest/throat/chin region.", "To prevent the bar from being able to injure your person by dropping too low, secure the safety pins of the Smith machine.", "Lie on your back (supine) on the bench and grasp the bar using a pronated (overhand) shoulder-width grip.", "Spread your legs and plant your feet flat on the floor for stability.", "Unlatch the bar from the rail by rotating it.", "Keeping your elbows high and approximately 45 degrees out to your sides, inhale as you carefully lower the bar towards your upper chest/throat/chin, stopping when your forearms make contact with your biceps.", "Exhale as you press the bar back up to the starting position.", "Repeat for the prescribed number of repetitions.", "After you have finished, rotate the bar to latch it back on to the rail."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/05/Smith-machine-JM-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/smith-machine-jm-press/"}, {"id": "decline-push-up", "name": "Decline push-up", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["With a bench behind you, get on your hands and knees.", "Position your hands slightly wider than shoulder width.", "Place your feet on the bench and straighten your body.", "Keeping your body straight, inhale as you lower your chest to the floor by flexing your elbows.", "Exhale as you push yourself back up to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/03/Decline-push-up-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/decline-push-up/"}, {"id": "smith-machine-incline-bench-press", "name": "Smith machine incline bench press", "name_ko": "벤치 프레스", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Place a bench that is inclined at 45 degrees under the bar of the Smith machine.", "Secure the safety pins of the Smith machine to prevent the bar from being able to drop too low and injure you.", "Sit in position and grasp the bar using a pronated (overhand) grip that’s a little wider than shoulder width.", "Plant your feet flat on the floor.", "Unlatch the bar from the rail by rotating it.", "Keeping your elbows tucked in a little and your wrists straight, exhale as you press the bar upward until your arms are almost fully extended.", "Inhale as you lower the bar either back to the starting position or until you feel a mild stretch in your chest.", "Repeat for the prescribed number of repetitions.", "Rotate the bar to latch it back onto the rail after you have finished."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/03/Smith-machine-incline-bench-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/smith-machine-incline-bench-press/"}, {"id": "barbell-jm-press", "name": "Barbell JM press", "name_ko": "Barbell JM press", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Lie supine (on your back) on a flat bench, spread your legs, and plant your feet flat on the floor for stability.", "Dismount the barbell using a shoulder-width grip.", "Keeping your elbows high, inhale as you lower the barbell in a straight line towards your upper chest/throat/chin, stopping when your forearms make contact with your biceps. (To maintain a secure grip on the barbell, you will have to flex your wrists a little as the barbell descends.)", "Exhale as you press the barbell back up to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/11/Barbell-JM-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-jm-press/"}, {"id": "superman-push-up", "name": "Superman push-up", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Lie prone (on your front) on the floor with your arms extended forward and your palms flat on the floor. This is the superman position.", "Keeping your body straight and rigid, exhale as you raise your body off the floor by pushing down on your palms.", "Hold for a count of two.", "Inhale as you slowly lower your body back to the floor.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/09/Superman-push-up-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/superman-push-up/"}, {"id": "one-arm-hammer-grip-dumbbell-bench-press", "name": "One-arm hammer-grip dumbbell bench press", "name_ko": "벤치 프레스", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in one hand, sit on a flat bench and rest the dumbbell on your knee.", "Kick the dumbbell up with your knee as you lie supine (on your back) on the bench.", "Position the dumbbell next to the side of your chest and hold it using a neutral or hammer grip (palm facing inward). Your wrist should be directly under your elbow, and your elbow should be flexed and tucked into your body a little.", "Spread your feet and grasp the bench with your free hand for support.", "Exhale as you press the dumbbell upward and inward in an arcing motion until your arm is fully extended over your chest.", "Inhale as you reverse the movement and lower the dumbbell to the starting position.", "Repeat for the prescribed number of repetitions.", "After you have finished, bring the dumbbell gently down onto your knee and sit up.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/05/One-arm-hammer-grip-dumbbell-bench-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/one-arm-hammer-grip-dumbbell-bench-press/"}, {"id": "incline-dumbbell-fly", "name": "Incline dumbbell fly", "name_ko": "플라이", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in each hand, sit on a bench inclined at 45 degrees and rest each dumbbell on a knee.", "Lie backward, and as you do so, kick the dumbbells up into position over your chest, one at a time.", "Spread your legs and plant your feet flat on the floor.", "Flex your elbows slightly, and internally rotate your shoulders so that your elbows point out to the sides.", "Keeping your elbows locked, inhale as you lower the dumbbells to your sides in an arcing motion until you feel a mild stretch in your chest or shoulders.", "Exhale as you reverse the motion and press the dumbbells back up to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/02/Incline-dumbbell-fly-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-dumbbell-fly/"}, {"id": "spiderman-push-up", "name": "Spiderman push-up", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Get on your hands and knees, with your hands positioned a little wider than shoulder width apart.", "Extend your feet backwards and straighten your body so that your bodyweight is being supported by your hands and toes.", "Keeping your body straight and rigid, inhale as you lower your chest to the floor by flexing your elbows. At the same time, raise one knee out to the side and try to touch it to the corresponding arm.", "Exhale as you reverse the movements and return to the starting position.", "Keep repeating, each time alternating the knee that you raise out to the side."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/12/Spiderman-push-up-resized-3.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/spiderman-push-up/"}, {"id": "bent-knee-bench-dip", "name": "Bent-knee bench dip", "name_ko": "딥", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Sit on the side of a bench and place your hands on the edge of the bench, by your hips.", "Move your feet forward a little and slide your bottom off the bench so that your body weight is supported by your arms and your knees are bent at 90-degree angles.", "Keeping your torso upright and your elbows close to your body, inhale as you lower your body by flexing your elbows.", "Exhale as you raise your body by extending your elbows.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/09/bent-knee-bench-dip-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/bent-knee-bench-dip/"}, {"id": "lying-cable-fly", "name": "Lying cable fly", "name_ko": "플라이", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Place a flat bench between two low cable pulleys.", "Grasp the stirrup (handle) of each pulley and lie supine (on your back) between the two pulleys, with your arms extended out to your sides.", "Flex your elbows slightly, and internally rotate your shoulders so that your elbows point out to the sides.", "Arch your back and stick out your chest.", "Keeping your elbows slightly flexed, exhale as you pull the stirrups upward and inward in a hugging motion until they touch over your chest.", "Hold for a count of two and squeeze your chest muscles.", "Inhale as you reverse the motion and lower the stirrups towards the starting position until you feel a mild stretch in your chest or shoulders.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/09/cable-fly-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lying-cable-fly/"}, {"id": "shoulder-tap-push-up", "name": "Shoulder tap push-up", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Get on your hands and knees, with your hands positioned a little wider than shoulder-width apart.", "Extend your feet backwards and straighten your body.", "Keeping your body straight and rigid, inhale as you lower your chest to the floor.", "Exhale as you push your body back up to the starting position.", "At the top of the movement, quickly tap your shoulder with the hand on the opposite side, before returning your hand to the floor.", "Repeat, making sure to alternate the shoulder that you tap."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/shoulder-tap-push-up-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/shoulder-tap-push-up/"}, {"id": "decline-dumbbell-bench-press", "name": "Decline dumbbell bench press", "name_ko": "벤치 프레스", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["With a dumbbell in each hand, sit on the end of a declined bench and rest the dumbbells on your knees. You can also get a training partner to hand you the dumbbells after you sit down.", "Hook your feet securely under the foot pads.", "Lie supine (on your back) and position the dumbbells to the sides of your chest, with your wrists pronated (facing away from you). Your elbows should be flexed and tucked into your sides a little.", "Exhale as you press the dumbbells upward and inward until your arms are almost fully extended and the dumbbells nearly touch.", "Inhale as you lower the dumbbells towards the starting position until you feel a mild stretch in your shoulders or chest.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/Decline-Dumbbell-Bench-Press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/decline-dumbbell-bench-press/"}, {"id": "incline-cable-bench-press", "name": "Incline cable bench press", "name_ko": "벤치 프레스", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Place a bench inclined at 45 degrees between two low cable pulleys.", "Grasp both stirrups (handles) and lie supine (on your back) on the bench, with your feet flat on the floor.", "Position the stirrups to the sides of your chest, with your elbows flexed and tucked into your body a little.", "Exhale as you press the stirrups upward and inward until they nearly touch at the top of the movement.", "Hold for a count of two and squeeze your chest.", "Inhale as you slowly reverse the movement and lower the stirrups towards the starting position until you feel a mild stretch in your chest or shoulders.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/incline-cable-bench-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-cable-bench-press/"}, {"id": "machine-assisted-triceps-dip", "name": "Machine-assisted triceps dip", "name_ko": "딥", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Kneel onto the knee pad of the assisted triceps dip machine and grasp the shoulder-width bars.", "Keeping your torso upright and your elbows tucked into your body, inhale as you lower yourself until you feel a mild stretch in your shoulders.", "Exhale as you push yourself back up to the starting position until your elbows are almost fully locked.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/assisted-triceps-dip-resized-1.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/machine-assisted-triceps-dip/"}, {"id": "decline-barbell-pullover", "name": "Decline barbell pullover", "name_ko": "풀오버", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Position a loaded barbell on the floor, at the head end of a decline bench.", "Lie supine (on your back) on the decline bench and hook your feet under the foot pads.", "Pick the barbell up from by your head using a narrow pronated (overhand) grip and press it up over your chest.", "Keeping your elbows very slightly flexed, inhale as you slowly lower the barbell backward and downward in a semicircular motion until you feel a mild stretch under your arms.", "Exhale as you slowly reverse the motion and return the barbell to the starting position, over your chest.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/decline-barbell-pullover-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/decline-barbell-pullover/"}, {"id": "one-leg-push-up", "name": "One-leg push-up", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Get on your hands and knees, with your arms positioned a little wider than shoulder width.", "Extend your feet backward and straighten your body.", "Raise one foot off the floor.", "Keeping your body straight and rigid, inhale as you lower your chest to the floor by flexing your elbows.", "Exhale as you extend your elbows and push your body back up to the starting position.", "Repeat for more repetitions.", "Repeat the repetitions with your opposite foot raised off the floor."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/one-leg-push-up-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/one-leg-push-up/"}, {"id": "decline-dumbbell-fly", "name": "Decline dumbbell fly", "name_ko": "플라이", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["With a dumbbell in each hand, sit on a decline bench, rest the dumbbells on your knees, and hook your feet under the foot pads. (Or have a spotter hand you the dumbbells after you sit down and hook your feet.)", "Lie back on the bench and, as you do so, raise the dumbbells over your upper abdomen.", "Flex your elbows a little, and internally rotate your shoulders so that your elbows point out to the sides.", "Inhale as you slowly lower the dumbbells in a semicircular motion to your sides until you feel a slight stretch in your chest.", "Exhale as you reverse the motion and bring the dumbbells back up over your chest in a hugging movement.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/Decline-dumbbell-fly-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/decline-dumbbell-fly/"}, {"id": "decline-cable-fly", "name": "Decline cable fly", "name_ko": "플라이", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Place a decline bench between two low cable pulleys.", "Grasp the stirrups (handles) of each pulley, lie supine (on your back) on the decline bench, and hook your feet under the pads.", "Position the stirrups out to each side.", "Flex your elbows slightly, and internally rotate your shoulders so that your elbows point out to the sides.", "Keeping your elbows slightly flexed, exhale as you press the stirrups upward and inward in a hugging motion until they nearly touch over your chest.", "Hold for a count of two and squeeze your chest.", "Inhale as you reverse the motion and return the stirrups towards the starting position until you feel a mild stretch in your chest or shoulders.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/07/decline-cable-fly-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/decline-cable-fly/"}, {"id": "close-grip-barbell-bench-press", "name": "Close-grip barbell bench press", "name_ko": "벤치 프레스", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Lie supine (on your back) on a flat bench, spread your legs, and plant your feet flat on the floor.", "Dismount the barbell using a shoulder-width grip.", "Straighten your wrists.", "Keeping your elbows close to your body, inhale as you lower the barbell to your chest.", "Exhale as you press the barbell back up to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/07/close-grip-barbell-bench-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/close-grip-barbell-bench-press/"}, {"id": "diamond-push-up", "name": "Diamond push-up", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Get on your hands and knees, with your hands close together and your thumbs and index fingers forming a diamond shape.", "Extend your feet backward and straighten your body so that your bodyweight is being supported by your hands and forefeet.", "Keeping your elbows tucked in to your body and your body straight and rigid, inhale as you lower your chest to the floor.", "Exhale as you extend your elbows and push your body back up to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/07/diamond-push-up-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/diamond-push-up/"}, {"id": "incline-reverse-grip-dumbbell-bench-press", "name": "Incline reverse-grip dumbbell bench press", "name_ko": "벤치 프레스", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["With a dumbbell in each hand, sit on a bench inclined at 45 degrees and rest one dumbbell on each knee.", "As you lie back on the bench, kick the dumbbells up over your body with your knees, one at a time.", "Position the dumbbells to the sides of your chest, with your elbows 45 degrees away from your torso and your palms facing up.", "Spread your legs and place your feet flat on the floor.", "Keeping your palms facing up (supinated), exhale as you press the dumbbells upward and inward until your arms are almost fully extended and the dumbbells nearly touch.", "Hold for a count of two and squeeze your chest.", "Inhale as you lower the dumbbells back to the starting position or until you feel a mild stretch in your chest or shoulders.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/07/Incline-reverse-grip-dumbbell-bench-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-reverse-grip-dumbbell-bench-press/"}, {"id": "knee-push-up", "name": "Knee push-up", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Get into a push-up position, supporting your body on your hands and knees instead of on your hands and forefeet. Your hands should be a little wider than shoulder width apart.", "Keeping your body straight and your elbows slightly tucked in, inhale as you lower your chest to the floor.", "Exhale as you extend your elbows and push your body back up to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/06/push-up-on-knees-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/knee-push-up/"}, {"id": "hammer-grip-dumbbell-bench-press", "name": "Hammer-grip dumbbell bench press", "name_ko": "벤치 프레스", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Holding a pair of dumbbells, sit on the end of a flat bench and rest the dumbbells on your knees.", "Kick the dumbbells up into the air with your knees as you lie supine (on your back) on the bench.", "Position the dumbbells next to the sides of your chest and hold them using a hammer grip (palms facing inward). Your elbows should be bent and tucked in to your body at a 45-degree angle.", "Exhale as you press the dumbbells upward and inward in an arcing motion until your arms are fully extended over your chest.", "Inhale as you reverse the motion and lower the dumbbells to the starting position or until you feel a mild stretch in your chest or shoulders.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/06/Dumbbell-Hammer-Grip-Bench-Press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/hammer-grip-dumbbell-bench-press/"}, {"id": "diamond-push-up-on-knees", "name": "Diamond push-up on knees", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Get into a push-up position, supporting your body on your hands and knees instead of on your hands and forefeet. Your hands should be positioned in such a way as to form a diamond shape with your thumbs and index fingers.", "Keeping your body straight and rigid and your elbows close to your body, inhale as you lower your chest to the floor.", "Exhale as you extend your elbows and push your body back up to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/06/diamond-push-up-on-knees-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/diamond-push-up-on-knees/"}, {"id": "weighted-push-up", "name": "Weighted push-up", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Get into a push-up position. You should be supporting your body on your hands and forefeet. Your body should be straight and rigid, and your hands should be wider than shoulder width apart.", "Get a training partner to place a weight plate on your back, where he or she must hold it securely throughout the exercise.", "Keeping your body straight and rigid, inhale as you lower your chest to the floor by flexing your elbows.", "Exhale as you push your body back up to the starting position until your elbows are fully extended.", "Repeat for the prescribed number of repetitions.", "Once finished, get your training partner to remove the weight plate from your back. Do not try to rotate your torso and throw the plate off, like in the video."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/06/weighted-push-up-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/weighted-push-up/"}, {"id": "standing-cable-chest-press", "name": "Standing cable chest press", "name_ko": "Standing cable chest press", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Stand between two shoulder-height pulleys, facing away.", "Grasp a stirrup (handle) in each hand, step forward, and stand with a staggered stance.", "Position the stirrups to the sides of your chest.", "Raise your elbows so that they are out to the sides (though not so high as to be horizontal).", "Keeping your body upright and arms horizontal, exhale as you press the stirrups forward and inward until your arms are straight and shoulders are stretched forward.", "Hold for a count of two and squeeze your chest.", "Inhale as you reverse the motion until you feel a mild stretch in your chest.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/05/cable-standing-chest-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/standing-cable-chest-press/"}, {"id": "cable-straight-arm-pull-down", "name": "Cable straight-arm pull-down", "name_ko": "Cable straight-arm pull-down", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Attach a straight bar to a high cable pulley.", "Stand under the pulley and grasp the bar using a pronated (overhand) grip.", "Flex your hips and lean forward until your arms are positioned by your ears.", "Keeping your arms slightly flexed, exhale as you pull the bar downward and backward in a semicircular motion toward your thighs.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you slowly reverse the motion and return the bar to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/04/Cable-Straight-Arm-Pull-down-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-straight-arm-pull-down/"}, {"id": "bodyweight-fly", "name": "Bodyweight fly", "name_ko": "플라이", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Place two short barbells or EZ-curl bars close to, and parallel to, each other. Ensure that the barbells can roll.", "Assume a push-up position over the barbells, holding each one in the center or a little above the center.", "Keeping your body straight and rigid, inhale as you slowly roll the barbells away from each other and lower your body until you feel a mild stretch in your chest.", "Exhale as you pull the barbells back together and return to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/03/bodyweight-barbell-floor-fly-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/bodyweight-fly/"}, {"id": "decline-bent-arm-barbell-pullover", "name": "Decline bent-arm barbell pullover", "name_ko": "풀오버", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Lie supine (on your back) on a declined bench and lock your feet securely under the foot pads.", "Get a partner to hand you a loaded barbell, or pick the barbell up from behind you, on the floor.", "Hold the barbell using a narrow pronated (overhand) grip and press it up over your chest.", "Flex your elbows to an angle that is approximately 90 degrees.", "Keeping your elbows flexed at 90 degrees, inhale as you slowly lower the bar backward, behind your head, until you feel a mild stretch under your arms.", "Exhale as you slowly reverse the movement and return the bar to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/02/barbell-bent-arm-pull-over-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/decline-bent-arm-barbell-pullover/"}, {"id": "isometric-wiper", "name": "Isometric wiper", "name_ko": "Isometric wiper", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Get on your hands and knees, with your hands positioned wider than shoulder width apart.", "Extend your feet backward, and straighten your body so that you are supporting your bodyweight on your hands and toes.", "Keeping your body straight and rigid, lower your chest as far toward one side as possible.", "Keeping your chest close to the floor, shift your body as far as you can to the opposite side.", "Keep alternating the side to which you shift your body while keeping your chest close to the floor.", "Breathe naturally."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/02/isometric-wiper-2-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/isometric-wiper/"}, {"id": "stability-ball-push-up", "name": "Stability ball push-up", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Kneel on the floor with a stability ball in front of you.", "Lie forward with your chest on top of the ball and your hands placed under your chest, on the surface of the ball.", "Extend your feet, and straighten your legs and torso.", "Keeping your core tight, exhale as you carefully push your body up until your arms are almost fully extended.", "Balance in the extended position for a count of two.", "Inhale as you lower yourself to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/02/push-up-on-stability-ball-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/stability-ball-push-up/"}, {"id": "decline-hammer-grip-dumbbell-bench-press", "name": "Decline hammer-grip dumbbell bench press", "name_ko": "벤치 프레스", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Holding a pair of dumbbells, sit on the end of a declined bench and rest the dumbbells on your thighs.", "Hook your feet securely under the foot pads.", "Lie supine (on your back) and position the dumbbells next to the sides of your chest using a hammer or neutral grip (palms facing inward). Your elbows should be bent and tucked in to your sides at a 45-degree angle.", "Exhale as you press the dumbbells upward and inward until your arms are extended over your chest.", "Inhale as you lower the dumbbells to the starting position or until you feel a mild stretch in your chest or shoulders.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/01/Decline-Hammer-Grip-Dumbbell-Bench-Press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/decline-hammer-grip-dumbbell-bench-press/"}, {"id": "stability-ball-decline-push-up", "name": "Stability ball decline push-up", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Get down on your hands and knees, with a stability ball behind you. Your hands should be positioned slightly wider than shoulder width.", "Extend your feet backward, place them on the stability ball, and straighten your body.", "Keeping your body straight and your elbows tucked in a little, inhale as you lower your chest to the floor by flexing your elbows.", "Exhale as you push yourself back up to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/12/decline-push-up-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/stability-ball-decline-push-up/"}, {"id": "tate-press", "name": "Tate press", "name_ko": "Tate press", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Sit on a flat bench with a dumbbell in each hand and rest one dumbbell on each knee.", "As you lie back on the bench, kick the dumbbells up into position over your chest, one at a time. Your forearms should be pronated (palms facing forward), and the sides of the dumbbells should be close together or touching.", "Spread your legs and plant your feet flat on the floor.", "Inhale as you flex your elbows and slowly lower the dumbbells down toward your chest.", "Hold the dumbbells over your chest for a count of two. Do not allow the dumbbells to rest on your chest.", "Exhale as you flex your elbows and press the dumbbells back up to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/12/Dumbbell-Tate-Press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/tate-press/"}, {"id": "svend-press", "name": "Svend press", "name_ko": "Svend press", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Squeeze a weight plate between your palms.", "Raise it to your chest, with your fingers pointing forward.", "Pull your shoulders back and stick out your chest.", "Raise your elbows so that your arms are parallel with the floor.", "Exhale as you slowly extend your elbows and push the plate out in front of you.", "Hold for a count of two and squeeze your chest muscles.", "Inhale as you slowly pull the plate back in to your chest.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/12/Svend-Press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/svend-press/"}, {"id": "machine-chest-press", "name": "Machine chest press", "name_ko": "Machine chest press", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Adjust the seat so that the handles are approximately chest height.", "Sit in the chest press machine with your back pressed firmly against the back rest.", "Grasp the handles with a pronated (overhand) grip.", "Plant your feet firmly on the ground.", "Exhale as you press the handles out until your arms are fully extended.", "Inhale as you reverse the motion until you feel a mild stretch in your chest.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/12/machine-chest-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/machine-chest-press/"}, {"id": "machine-fly", "name": "Machine fly", "name_ko": "플라이", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Sit on the fly machine with your back pressed firmly against the back support.", "Grasp the levers at shoulder height.", "Internally rotate your shoulders so that your wrists, elbows, and shoulders are level.", "Keeping your elbows slightly bent, exhale as you push the levers together.", "Inhale as you reverse the motion until you feel a mild stretch in your chest or shoulders.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/12/Machine-Fly-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/machine-fly/"}, {"id": "close-grip-push-up", "name": "Close-grip push-up", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Get on all fours with your hands positioned either directly under your shoulders or closer together.", "Extend your feet backward and straighten your body.", "Keeping your body straight and your elbows tucked in, inhale as you lower your chest onto your hands.", "Exhale as you push your body back up to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/close-grip-push-up-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/close-grip-push-up/"}, {"id": "dumbbell-fly", "name": "Dumbbell fly", "name_ko": "덤벨 플라이", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Holding a pair of dumbbells, sit on a flat bench and rest the dumbbells on your knees.", "Lie back on the bench and, as you do so, kick the dumbbells up into position over your chest, one at a time.", "Spread your legs and plant your feet flat on the floor.", "Bend your elbows a little, and internally rotate your shoulders so that your elbows point out to the sides.", "Arch your back and stick out your chest.", "Inhale as you lower the dumbbells in an arcing motion to your sides until you feel a mild stretch in your chest.", "Exhale as you reverse the motion until the dumbbells are nearly vertical.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/dumbbell-fly-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-fly/"}, {"id": "incline-dumbbell-bench-press", "name": "Incline dumbbell bench press", "name_ko": "벤치 프레스", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in each hand, sit on a bench inclined at 45 degrees and rest one dumbbell on each knee.", "As you lie back on the bench, kick the dumbbells up, one at a time, into place.", "Position the dumbbells to the sides of your chest, with your elbows bent and tucked in to your torso a little.", "Straighten your wrists.", "Spread your legs and place your feet flat on the floor.", "Exhale as you press the dumbbells upward and inward until your arms are almost fully extended and the dumbbells nearly touch.", "Hold for a count of two and squeeze your chest.", "Inhale as you lower the dumbbells back to the starting position, or until you feel a mild stretch in your chest.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/incline-dumbbell-bench-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-dumbbell-bench-press/"}, {"id": "incline-straight-arm-pull-down", "name": "Incline straight-arm pull-down", "name_ko": "Incline straight-arm pull-down", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Lie on an inclined bench positioned under, and facing away from, a high cable pulley.", "Grasp the straight bar using a shoulder-width pronated (overhand) grip.", "Keeping your elbows slightly bent, exhale as you pull the bar forward and downward to your thighs in a wide arcing motion.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you reverse the motion and return the bar to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/Cable-Incline-Straight-Arm-Pull-Down-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-straight-arm-pull-down/"}, {"id": "cable-bench-press", "name": "Cable bench press", "name_ko": "벤치 프레스", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Place a flat bench between two low cable pulleys.", "Grasp both stirrups and lie supine (on your back) on the bench, feet flat on the floor.", "Position the stirrups to the sides of your chest, with your elbows bent and tucked in to your torso at a 45-degree angle.", "Exhale as you press the stirrups upward and inward until they touch at the top of the movement.", "Hold for a count of two.", "Inhale as you slowly reverse the motion and return the stirrups to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/cable-bench-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-bench-press/"}, {"id": "incline-barbell-bench-press", "name": "Incline barbell bench press", "name_ko": "벤치 프레스", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Lie supine (on your back) on a bench inclined at 45 degrees.", "Spread your legs, bring your feet back, and place them firmly on the ground.", "Arch your back.", "Dismount the barbell using a wider-than-shoulder-width grip.", "Retract (push together) your shoulder blades and straighten your wrists.", "Inhale as you lower the barbell to your chest, keeping your elbows tucked in.", "Exhale as you press the barbell back up to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/incline-barbell-bench-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-barbell-bench-press/"}, {"id": "decline-barbell-bench-press", "name": "Decline barbell bench press", "name_ko": "벤치 프레스", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Lock your feet under the leg brace of a declined bench and lie on your back.", "Using a grip that is a little wider than shoulder width, dismount the barbell from the rack.", "While holding the barbell, retract your shoulder blades (push them together) and straighten your wrists.", "Keeping your elbows tucked in a little, inhale as you lower the barbell to your chest.", "Exhale as you press the barbell back up to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Decline-Barbell-Bench-Press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/decline-barbell-bench-press/"}, {"id": "high-cable-cross-over", "name": "Cable cross-over", "name_ko": "Cable cross-over", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Stand between two high pulleys.", "Grasp the stirrup of the left pulley with your left hand and the stirrup of the right pulley with your right hand using an overhand grip.", "Bend forward a little by flexing your hips and knees.", "Internally rotate your shoulders so that your elbows are shoulder height.", "Keeping your elbows slightly bent, exhale as you slowly pull the stirrups together in a downward hugging motion.", "Hold for a count of two and squeeze your chest.", "Inhale as you slowly reverse the motion until you feel a slight stretch in your chest.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/cable-standing-fly-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/high-cable-cross-over/"}, {"id": "incline-reverse-grip-barbell-bench-press", "name": "Incline reverse-grip barbell bench press", "name_ko": "벤치 프레스", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Lie supine (on your back) on a bench inclined at 45 degrees.", "Grasp the barbell using a reverse grip (palms facing you), with your hands placed wider than shoulder width.", "Unrack the barbell.", "Inhale as you lower the barbell to your upper abdomen.", "Exhale as you press the barbell back up to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Incline-Reverse-Grip-Barbell-Bench-Press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-reverse-grip-barbell-bench-press/"}, {"id": "incline-cable-fly", "name": "Incline cable fly", "name_ko": "플라이", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Place a bench inclined at 45 degrees between two low cable pulleys.", "Lie supine (on your back) on the bench, holding one stirrup (handle) in each hand.", "Position the stirrups out to each side.", "Bend your elbows slightly, and internally rotate your shoulders so that your elbows point out to the sides.", "Keeping your elbows fixed, exhale as you press the stirrups upward and inward in an arc motion until they touch over your chest.", "Inhale as you reverse the motion and return the stirrups to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Cable-Incline-Fly-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-cable-fly/"}, {"id": "push-up", "name": "Push-up", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Get on your hands and knees, with your arms positioned a little wider than shoulder width.", "Extend your feet backward and straighten your body.", "Keeping your body straight and elbows slightly tucked in, inhale as you lower your chest to the floor by bending your elbows.", "Exhale as you reverse the motion and push your body back up to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/push-up-tall-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/push-up/"}, {"id": "dumbbell-pullover", "name": "Dumbbell pullover", "name_ko": "풀오버", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Lie perpendicular on a bench with only your upper back and shoulders being supported by the surface. Your head and lower body should be extending off the bench, with your lower body acting as a counterbalance.", "Hold a dumbbell with both hands directly above your chest, with your arms almost fully extended and your palms facing each other.", "Exhale as you slowly lower the dumbbell in a backward arc behind your head until your elbows are level with your ears.", "Hold for a count of two.", "Inhale as you slowly raise the dumbbell back over your head to the starting position using the same arcing motion.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/06/Dumbbell-Pullover-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-pullover/"}, {"id": "low-cable-cross-over", "name": "Standing incline cable fly", "name_ko": "플라이", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Stand midway between two low pulleys, holding one handle in each hand.", "Position one foot in front of the other for stability.", "Extend your arms a little out to your sides, keeping them slightly bent at the elbows. Your palms should be facing forwards.", "Exhale as you slowly bring the handles upward and toward the midline of your body. Your hands should come together in front of your chest, with your palms facing up and your elbows slightly bent.", "Hold for a count of two and squeeze your chest.", "Inhale as you slowly return the handles to the starting position.", "Repeat for the recommended number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/05/low-cable-cross-over-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/low-cable-cross-over/"}, {"id": "cable-cross-over", "name": "Standing cable fly", "name_ko": "플라이", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Stand midway between two pulleys, holding one stirrup (handle) in each hand.", "Place one foot in front of the other for stability.", "Bend forwards slightly at the hips, keeping your back straight.", "Extend your arms out to your sides, keeping them slightly bent at the elbows. Your palms should be facing forward.", "Exhale as you slowly draw the stirrups together in an arcing motion, until they are positioned in front of your abdomen.", "Hold for a count of two and squeeze your chest.", "Inhale as you slowly return the stirrups either to the starting position or until you feel a mild stretch in your chest.", "Repeat for the recommended number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/05/cable-cross-over-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-cross-over/"}, {"id": "dumbbell-bench-press", "name": "Dumbbell bench press", "name_ko": "덤벨 벤치 프레스", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in each hand, sit on a flat bench and rest one dumbbell on each knee.", "As you lie back on the bench, kick each dumbbell up into position, one at a time.", "Position the dumbbells to the sides of your chest, with your arms bent at a 90-degree angle. Your elbows should not be pointing straight out to the sides; rather, tuck them in a little to approximately a 45-degree angle.", "Spread your legs, bring your feet back, and place them firmly on the ground. Either your toes or your heels should be planted firmly on the floor.", "Arch your back and straighten your wrists.", "Exhale as you slowly press the dumbbells upward and inward until your arms are almost fully extended and the dumbbells nearly touch.", "Inhale as you slowly lower the dumbbells back to the starting position, or until you feel a slight stretch in your chest.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/05/Dumbbell-Bench-Press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-bench-press/"}, {"id": "bench-press", "name": "Barbell bench press", "name_ko": "바벨 벤치 프레스", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Lie supine (on your back) on a flat bench.", "Spread your legs, bring your feet back, and place them firmly on the ground. Either your toes or your heels should be planted on the floor.", "Arch your back.", "Dismount the barbell using a grip that is a little over shoulder-width apart.", "While holding the barbell, retract (push together) your shoulder blades and straighten your wrists.", "Inhale as you lower the barbell to your chest, keeping your elbows tucked in at a 45-degree angle.", "Exhale as you press the barbell back up to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/05/Barbell-Bench-Press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/bench-press/"}, {"id": "triceps-dip", "name": "Triceps dip", "name_ko": "딥", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["chest"], "secondary_muscles": [], "instructions": ["Mount the should-width dip bars and straighten your arms so that your legs are suspended off the ground.", "Keeping your elbows tucked in and your body upright, slowly lower your body until your elbows form a 90-degree angle or you feel a slight stretch in your shoulders. Don’t forget to inhale.", "Exhale as you push your body back up to the starting position.", "Repeat for the recommended number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/05/Triceps-Dip-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/triceps-dip/"}, {"id": "straight-back-seated-cable-row-with-straight-bar", "name": "Straight-back seated cable row with straight bar", "name_ko": "로우", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Gripping the straight bar with an overhand grip (palms down), sit on the cable row machine with your feet on the foot rests and knees almost straight.", "Your back should be vertical, the cable should be pulled taut, and your arms and shoulders should be stretching forward.", "Keeping your back straight and elbows close to your torso, exhale as you slowly pull the straight bar to your abdomen.", "Hold for a count of two. Squeeze your back muscles.", "Inhale as you slowly return to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/09/Straight-back-seated-cable-row-with-straight-bar.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/straight-back-seated-cable-row-with-straight-bar/"}, {"id": "chest-supported-underhand-grip-t-bar-row", "name": "Chest-supported underhand-grip T-bar row", "name_ko": "로우", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Position your chest and abdomen against the angled pad.", "Grasp the handles with an underhand grip (palms up).", "Keeping your elbows close to your body, exhale as you pull the bar up to your chest.", "Hold for a count of two.", "Inhale as you reverse the motion to slowly lower the bar back to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/08/Chest-supported-underhand-grip-t-bar-row.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/chest-supported-underhand-grip-t-bar-row/"}, {"id": "weighted-back-extension-on-stability-ball", "name": "Weighted back extension on stability ball", "name_ko": "Weighted back extension on stability ball", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Lie prone (on your front) on a stability ball with the soles of your feet against a wall.", "Hold the weight plate behind your head or by crossing your arms close to your chest.", "Keeping your neck neutral, exhale as you lift your upper body off the ball.", "Hold for a count of two.", "Inhale as you slowly lower your upper body back to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/08/Weighted-Back-Extension-on-stability-ball.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/weighted-back-extension-on-stability-ball/"}, {"id": "weighted-inverted-rear-delt-row", "name": "Weighted inverted rear delt row", "name_ko": "로우", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Position a bench in front of the bar. This is to elevate your feet for the exercise.", "Lie below the bar and position a weight plate on your abdomen.", "Grasp the bar with a wide overhand (pronated) grip and place your feet on the bench.", "Raise your hips so that you are hanging off the bar.", "Keeping your back neutral and your elbows out to the sides, exhale as you pull your chest toward the bar.", "Hold for a count of two.", "Inhale as you lower your body or until your arms are fully extended.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/08/Weighted-inverted-rear-delt-row.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/weighted-inverted-rear-delt-row/"}, {"id": "floor-t-raise", "name": "Floor T-raise", "name_ko": "Floor T-raise", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Lie on your belly with your arms stretched out to the sides, so that you are forming a “T” with your body.", "Keeping your legs and arms straight, exhale as you simultaneously lift your feet and arms off the floor.", "Hold for a count of two.", "Inhale as you slowly lower your feet and arms to return to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/12/Floor-t-raise.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/floor-t-raise/"}, {"id": "inverted-rear-delt-row", "name": "Inverted rear delt row", "name_ko": "로우", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Set the bar to waist height.", "Grasping the bar with a wide overhand grip, walk forward under the bar until your arms are perpendicular to your torso.", "Straighten your legs so that you are hanging off the bar at an angle.", "Keeping your back neutral and your legs extended, exhale as you pull your chest toward the bar with your elbows out to the sides.", "Hold for a count of two.", "Inhale as you return to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/09/Inverted-rear-delt-row.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/inverted-rear-delt-row/"}, {"id": "dumbbell-external-shoulder-rotation", "name": "Dumbbell external shoulder rotation", "name_ko": "Dumbbell external shoulder rotation", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Stand behind an inclined bench that is slightly lower than shoulder height.", "Hold a dumbbell in one hand with an overhand (pronated) grip.", "Bend your elbow at a 90-degree angle and place your elbow on the bench so that you are holding the dumbbell in front of you (with one end of the dumbbell facing you and the other facing front).", "Keeping your elbow bent at a 90-degree angle, lower the dumbbell by rotating your shoulder internally. Your forearm should be parallel to the floor.", "Maintaining the angle of your elbow, exhale as you externally rotate your shoulder to raise the dumbbell until your forearm is upright.", "Hold for a count of two.", "Inhale as you reverse the motion to return to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/08/Dumbbell-External-Shoulder-Rotation.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-external-shoulder-rotation/"}, {"id": "cable-shrug-using-pull-down-bar", "name": "Cable shrug using pull-down bar", "name_ko": "슈러그", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Attach a pull-down bar to a low cable pulley.", "Face the pulley with your feet hip-width apart and grasp the bar using an overhand grip. Keep your hands shoulder-width apart and in front of your thighs.", "Keeping your elbows slightly bent, exhale as you elevate your shoulders straight up as high as possible.", "Hold for a count of two and squeeze your trapezius.", "Inhale as you lower your shoulders back to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/07/Cable-shrug-using-pull-down-bar.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-shrug-using-pull-down-bar/"}, {"id": "zercher-carry", "name": "Zercher carry", "name_ko": "Zercher carry", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Place a barbell on a waist-high rack and load it.", "Scoop the barbell up into the crooks of your elbows and keep your elbows tucked into your sides. You may cross your wrists to help keep the barbell in place.", "Pull your hips in so that they are underneath the bar and stand up. You should be standing tall, carrying the barbell in the crook of your elbows.", "Keeping your body upright and breathing normally, walk in a straight line for the prescribed distance.", "At the end of the walk, lower the barbell on to another rack or platform.", "Turn, scoop the barbell up into the crooks of your elbows and walk back to the starting rack.", "Repeat until you have completed the total prescribed distance."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/06/Zercher-carry.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/zercher-carry/"}, {"id": "weighted-close-neutral-grip-pull-up", "name": "Weighted close neutral-grip pull-up", "name_ko": "풀업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Wrap a loaded dip belt around your waist securely. The weight plate should be hanging between your legs.", "Grasp the double pull up bars with your palms facing each other and hang with your arms fully extended.", "Exhale as you pull your body up to raise your chin above the bar.", "Hold for a count of two.", "Inhale as you lower your body to return to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/05/Weighted-close-neutral-grip-pull-up.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/weighted-close-neutral-grip-pull-up/"}, {"id": "flat-bench-frog-reverse-hyperextension", "name": "Flat bench frog reverse hyperextension", "name_ko": "하이퍼익스텐션", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["On a flat bench, lie on your stomach with your hips at end of the bench and your legs hanging off the edge.", "Hug the bench with your arms and flare your knees out to your sides so that you can put the soles of your feet together.", "Keeping the soles of your feet together, exhale as you lift your feet as high as you can.", "Hold for a count of two.", "Inhale as you slowly lower your feet back to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/05/Flat-bench-frog-reverse-hyperextension.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/flat-bench-frog-reverse-hyperextension/"}, {"id": "decline-bench-reverse-hyperextension", "name": "Decline bench reverse hyperextension", "name_ko": "하이퍼익스텐션", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Lie on your stomach on an inclined bench, with your hips at the end of the higher edge. Allow your legs to hang off the edge.", "Hug the bench with your arms and lift your feet a few inches off the ground.", "Keeping your legs straight, exhale as you lift your feet as high as you can.", "Hold for a count of two and squeeze your glutes.", "Inhale as you slowly lower your feet back to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/03/Decline-bench-reverse-hyperextension-1.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/decline-bench-reverse-hyperextension/"}, {"id": "kettlebell-deadlift", "name": "Kettlebell deadlift", "name_ko": "데드리프트", "category": "strength", "equipment": "kettlebell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Stand with the kettlebell between your feet.", "With your arms straight and your back neutral, hinge at the hips and then slightly bend at the knees to grasp the handle of the kettlebell with your hands.", "Keeping your arms straight and back neutral, exhale as you squeeze your glutes to stand up and lift the kettlebell.", "Inhale as you hinge at the hips, push your glutes backward and then slightly bend at the knees to lower the kettlebell back to its original position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/01/Kettlebell-deadlift-1.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/kettlebell-deadlift/"}, {"id": "bent-knee-inverted-shrug-on-parallel-bars", "name": "Bent-knee inverted shrug on parallel bars", "name_ko": "슈러그", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Squat between the parallel bars and grasp the bars with your palms facing each other.", "Lean your torso back as you walk your feet up against the back rest of the parallel bar machine until your torso is inverted. If your parallel bars have no back rest, kick your legs up to invert your body.", "Bend your knees, and if possible, keep your feet positioned against the back rest of the parallel bars.", "Keeping your torso and thighs aligned, exhale as you raise your body up by pulling your shoulders towards your ears.", "Hold for a count of two.", "Inhale as you slowly lower your body back to the starting position.", "Repeat for the desired number of repetitions.", "To get out of the inverted position, slowly walk your feet down from the back rest to raise your torso."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/01/Bent-knee-inverted-shrug-on-parallel-bars.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/bent-knee-inverted-shrug-on-parallel-bars/"}, {"id": "flat-bench-reverse-hyperextension", "name": "Flat bench reverse hyperextension", "name_ko": "하이퍼익스텐션", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Lie on your stomach on a flat bench with your legs hanging off the edge. Your hips should be at the end of the bench.", "Hug the bench with your arms and lift your feet a few inches off the ground, keeping your knees straight.", "Keeping your legs straight, exhale as you lift your feet as high as you can.", "Hold for a count of two.", "Inhale as you lower your feet back to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/01/Flat-bench-reverse-hyperextension-1.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/flat-bench-reverse-hyperextension/"}, {"id": "self-assisted-pull-up", "name": "Self-assisted pull-up", "name_ko": "풀업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Place a bench under a bar.", "Hang from the bar, with your feet resting lightly on the bench.", "Exhale as you pull your body up until your chin rises above the bar, pushing with your legs as little as possible and only when you can no longer pull with your arms.", "Hold for a count of two and squeeze your back and biceps muscles.", "Inhale as you lower your body back to the starting position using only your arms.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/11/Self-assisted-pull-up.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/self-assisted-pull-up/"}, {"id": "l-sit-pull-up", "name": "L-sit pull-up", "name_ko": "풀업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Hang from a pull-up bar using an overhand (pronated) grip, with your arms a little wider than shoulder-width apart.", "Keeping your legs straight, flex your hips 90 degrees so that your torso and legs create the shape of the letter ‘L’.", "Maintaining the L-shape, exhale as you pull your body up until your chin rises above the bar.", "Hold for a count of two and squeeze your back and biceps.", "Inhale as you slowly lower your body back to the starting position.", "Repeat the L-sit pull-up for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/10/L-Sit-Pull-up.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/l-sit-pull-up/"}, {"id": "mixed-grip-pull-up", "name": "Mixed-grip pull-up", "name_ko": "풀업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Hang from a bar, holding it using a supinated (underhand) grip with one hand and a pronated (overhand) grip with the other.", "Exhale as you pull your body up until your chin is raised above the bar.", "Hold for a count of two and squeeze your back muscles and biceps.", "Inhale as you lower your body back to the starting position.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise after switching grips (i.e. the hand using the overhand grip will switch to an underhand grip, and vice versa)."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/10/Mixed-grip-pull-up.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/mixed-grip-pull-up/"}, {"id": "gorilla-chin-crunch", "name": "Gorilla chin crunch", "name_ko": "크런치", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["With your hands shoulder-width apart, hang from a bar using an underhand grip (palms facing you). Your elbows should be fully extended.", "Bend your knees so that your shins are parallel with the floor. Your hips should remain straight.", "Exhale as you simultaneously and slowly pull yourself up towards the bar and crunch your knees up into your chest. At the height of the movement, your chin should be above the bar and your knees should be close to or against your chest.", "Hold for a count of two.", "Inhale as you slowly reverse the motion and return to the starting position.", "Perform for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/10/Gorilla-chin-crunch-2.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/gorilla-chin-crunch/"}, {"id": "seated-barbell-bent-knee-good-morning", "name": "Seated barbell bent-knee good morning", "name_ko": "굿모닝", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Stand holding a barbell at the back of your shoulders, grasping the barbell at each side.", "Straddle and sit on a bench, with your knees bent. Your feet should be in front of your knees.", "Keeping your back and neck neutral, inhale as you flex your hips to lower your chest towards the bench.", "Hold for a count of two.", "Exhale as you extend your hips to return to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/09/Seated-Barbell-Good-morning.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-barbell-bent-knee-good-morning/"}, {"id": "dumbbell-straight-leg-deadlift", "name": "Dumbbell straight-leg deadlift", "name_ko": "데드리프트", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Holding a pair of dumbbells, stand with your feet shoulder-width or narrower apart.", "Position the dumbbells in front of your hips, holding them side by side, with an overhand (pronated) grip.", "Keeping your arms and knees straight (though not locked), inhale as you flex your hips and waist to lower the dumbbells until you feel a mild stretch in your hamstrings.", "Exhale as you extend your hips and waist to return the dumbbells to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/10/Dumbbell-Straight-Leg-Deadlift.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-straight-leg-deadlift/"}, {"id": "dumbbell-suitcase-carry", "name": "Dumbbell suitcase carry", "name_ko": "Dumbbell suitcase carry", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Stand holding a heavy dumbbell in your non-dominant hand.", "Engage your core so that you can stand straight. Do not lean towards one side.", "Keeping your body straight and back neutral, breathe normally as you walk in a straight line for the prescribed distance.", "At the end of the walk, squat down to lower the dumbbell to the floor. Switch and stand on the other side of the dumbbell.", "Squat, pick the dumbbell up with your dominant hand, and walk back to the starting mark.", "Repeat until you meet the desired distance."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/10/Dumbbell-suitcase-carry-2.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-suitcase-carry/"}, {"id": "chin-up", "name": "Chin-up", "name_ko": "친업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Grasp a pull-up bar using an underhand grip, with your hands shoulder-width apart.", "Hang from the bar.", "Exhale as you pull your body up until your chin is raised above the bar.", "Hold for a count of two and squeeze your biceps and back muscles.", "Inhale as you slowly lower your body back to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/09/Chin-up.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/chin-up/"}, {"id": "barbell-overhead-shrug", "name": "Barbell overhead shrug", "name_ko": "슈러그", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["With your feet shoulder-width apart, perform a barbell shoulder press to position the barbell directly over your head.", "Keeping your elbows straight and your back neutral, exhale as you shrug your shoulders up as high as possible.", "Hold for a count of two and squeeze your upper trapezius muscles.", "Inhale as you slowly lower your shoulders.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/08/Barbell-overhead-shrug.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-overhead-shrug/"}, {"id": "back-extension-on-stability-ball", "name": "Back extension on stability ball", "name_ko": "Back extension on stability ball", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Lie prone (on your front) on a stability ball.", "Place your hands behind your head.", "For stability, spread your feet out. You can also place the soles of your feet against a wall.", "Keeping your neck neutral, exhale as you slowly hyperextend your spine to raise your torso off the ball.", "Hold for a count of two.", "Inhale as you lower your torso to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/08/Back-Extension-on-stability-ball-1.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/back-extension-on-stability-ball/"}, {"id": "underhand-grip-inverted-row", "name": "Underhand-grip inverted row", "name_ko": "로우", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Position the Smith machine bar so that it’s slightly higher than arm’s length from the floor.", "Lie under the bar with your legs and body straight.", "Grasp the bar with a shoulder-width underhand grip (palms facing up).", "Keeping your body straight and elbows close to your body, exhale as you pull your chest up to the bar.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you slowly extend your arms to lower your body back down to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/07/Underhand-Grip-Inverted-Row.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/underhand-grip-inverted-row/"}, {"id": "dumbbell-renegade-row", "name": "Dumbbell renegade row", "name_ko": "로우", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in each hand, assume a high plank position (i.e. get on all fours and then straightening your legs and body). The dumbbells should be shoulder-width apart.", "Keeping your hips and shoulders square, exhale as you pull one dumbbell up to the side of your waist.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you return to the starting position by slowly lowering the dumbbell to the floor.", "Repeat the lift with your opposite arm.", "Alternating your arms, perform the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/06/Dumbbell-Renegade-Row.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-renegade-row/"}, {"id": "bent-knee-inverted-rear-delt-row", "name": "Bent-knee inverted rear delt row", "name_ko": "로우", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Set the Smith machine bar to waist height or place a barbell on a rack at waist height.", "Lie under the bar with your knees bent. Grab onto the bar with an overhand grip, slightly wider than shoulder-width apart.", "Lift your torso off the floor so that you’re hanging off the bar. Your elbows should be extended and your torso should be horizontal.", "Keeping your back neutral and your elbows perpendicular to your torso, exhale as you pull your chest up toward the bar.", "Hold for a count of two.", "Inhale as you lower your torso to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/06/Bent-knee-Inverted-rear-delt-Row.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/bent-knee-inverted-rear-delt-row/"}, {"id": "barbell-underhand-grip-bent-over-row", "name": "Barbell underhand-grip bent-over row", "name_ko": "로우", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Stand with a barbell in front of you, on the floor.", "With your knees slightly flexed, bend over at the hips and grasp the barbell with an underhand grip (palms facing upward). Your torso should be parallel with the floor.", "Keeping your back and neck neutral, exhale as you pull the barbell up to your lower abdomen.", "Hold for a count of two.", "Inhale as you reverse the motion and lower the barbell until it almost touches the floor.", "Repeat for the prescribed number or repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/06/Barbell-underhand-Grip-Bent-Over-Row.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-underhand-grip-bent-over-row/"}, {"id": "dumbbell-farmers-walk", "name": "Dumbbell farmer’s walk", "name_ko": "Dumbbell farmer’s walk", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Deadlift a pair of dumbbells from the floor.", "Keeping your shoulders back and the dumbbells by your sides, breathe normally as you walk in a straight line for the prescribed distance.", "At the end of the walk, lower the dumbbells to the floor by flexing your hips and knees, keeping your torso upright.", "Turn, deadlift the dumbbells back up from the floor, and walk back to the starting mark.", "Repeat the exercise until you meet the prescribed distance."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/04/Dumbbell-farmers-walk-2.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-farmers-walk/"}, {"id": "barbell-sumo-romanian-deadlift", "name": "Barbell sumo Romanian deadlift", "name_ko": "데드리프트", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Stand holding a barbell using a shoulder-width overhand grip, with your feet wide apart and pointing diagonally out to the sides. Your arms should be extended and the barbell should be resting against your thighs.", "Keeping your back neutral, inhale as you lower the barbell down your legs by pushing your butt back and flexing your knees after the barbell drops below knee level. Keep lowering the barbell until it is close to the floor.", "Exhale as you pull the barbell back up to the starting position by driving through your feet, extending your knees and then extending your hips after the barbell passes knee level.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/03/Barbell-sumo-Romanian-deadlift.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-sumo-romanian-deadlift/"}, {"id": "weighted-pull-up", "name": "Weighted pull-up", "name_ko": "풀업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Wrap a loaded dip belt around your waist securely. The weight plate should be hanging between your legs when you stand.", "Grasp the bar with an overhand (pronated) grip that is a little wider than shoulder width.", "Hang from the bar, with your arms and shoulders fully extended.", "Exhale as you pull your body up until your chin is above the bar.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you lower yourself back to the starting position, with your shoulders and arms fully extended.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/03/Weighted-pull-up-back.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/weighted-pull-up/"}, {"id": "barbell-bent-knee-good-morning", "name": "Barbell bent-knee good morning", "name_ko": "굿모닝", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["With your feet hip-width apart, stand holding a barbell on the back of your shoulders, grasping the barbell at each side.", "Keeping your back neutral, inhale as you flex your hips and, slightly, your knees to lower your torso until it is close to, or fully, parallel with the floor.", "Exhale as you raise your torso back to starting position by extending your hips and knees.", "Repeat until you meet the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/03/Barbell-bent-knee-good-morning.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-bent-knee-good-morning/"}, {"id": "barbell-good-morning", "name": "Barbell good morning", "name_ko": "굿모닝", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Stand holding a barbell on the back of your shoulders, grasping the barbell at each side.", "Keeping your knees slightly flexed and your back and neck neutral, inhale as you flex your hips to lower your torso until it is close to, or fully, horizontal.", "Exhale as you raise your torso back up to the starting position by extending your hips.", "Repeat until you meet the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/03/Barbell-good-morning.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-good-morning/"}, {"id": "trap-bar-farmers-walk", "name": "Trap bar farmer’s walk", "name_ko": "Trap bar farmer’s walk", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Stand inside a loaded trap bar with your feet shoulder-width apart.", "Squat and grasp the handles of the trap bar.", "Take a deep breath.", "Keeping your torso upright and your arms and back straight, exhale as you lift the trap bar into a standing position.", "Breathing normally and keeping your arms straight, walk in a straight direction for the desired distance while holding the trap bar.", "At the end of the walk, stop, bring your feet level, and set the trap bar down carefully by first pushing your hips back and then flexing your knees.", "Turn and repeat steps 1 and 2 to return to the starting mark.", "Repeat the exercise until you meet the prescribed distance."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/11/Trap-bar-farmers-walk-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/trap-bar-farmers-walk/"}, {"id": "smith-machine-shrug", "name": "Smith machine shrug", "name_ko": "슈러그", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Set the height of the bar of the Smith machine so that it’s just above knee height.", "Set the safety pins to prevent the bar from being able to drop and potentially damage your legs.", "Stand in front of the bar and grasp it using a shoulder-width pronated grip (palms facing your body).", "Unlatch the bar from the rail by rotating it, and stand up straight.", "Keeping your elbows slightly flexed, exhale as you elevate your shoulders as high as possible.", "Hold for a count of two and squeeze your trapezius.", "Inhale as you lower the bar back to the starting position.", "Repeat for the prescribed number of repetitions.", "After you have finished, latch the bar back onto the rail by rotating it."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/10/Smith-machine-shrug-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/smith-machine-shrug/"}, {"id": "smith-machine-yates-row", "name": "Smith machine Yates row", "name_ko": "로우", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Adjust the height of the Smith machine bar so that it is set at the height of your lower thighs.", "Grasp the bar with a shoulder-width pronated (overhand) grip.", "Lean forward at a 45-degree angle by flexing your hips and knees.", "Unlatch the bar from the rail by rotating it.", "Keeping your back neutral, exhale as you pull the bar up to your waist.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you lower the bar to the starting position.", "Repeat for more repetitions.", "When you have finished, rotate the bar to latch it back onto the rail."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/03/Smith-machine-Yates-row-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/smith-machine-yates-row/"}, {"id": "machine-front-pull-down", "name": "Machine front pull-down", "name_ko": "Machine front pull-down", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Sit on the lat front pull-down machine and secure your thighs under the supports.", "Grasp the lever handles. Your arms and shoulders should be fully extended upward.", "Exhale as you pull the handles down to your upper chest.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you return the handles to the starting position, with your arms and shoulders fully extended.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/03/Machine-front-pull-down-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/machine-front-pull-down/"}, {"id": "side-lying-dumbbell-rear-delt-raise", "name": "Side-lying reverse dumbbell fly", "name_ko": "플라이", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Lie on the floor, on your right side, with a dumbbell in front of you and with your head being supported by your right hand.", "Grasp the dumbbell with your left hand using a neutral grip (palm facing downward). Your elbow should be either straight or slightly flexed.", "Keeping your elbow fixed and your body still, exhale as you raise the dumbbell from floor until it is almost vertical.", "Hold for a count of two.", "Inhale as you reverse the movement and lower the dumbbell towards the starting position, stopping before the dumbbell touches the floor.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise on your opposite side, with your right arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/12/Side-lying-dumbbell-rear-delt-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/side-lying-dumbbell-rear-delt-raise/"}, {"id": "one-arm-dumbbell-bent-over-lateral-raise", "name": "One-arm reverse dumbbell fly", "name_ko": "플라이", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in one hand, flex your hips and knees until your torso is parallel to the floor.", "For stability, grasp something stable with your free hand. Your back should be straight and the arm with the dumbbell should be hanging straight down in front of you, with your palm facing inward (neutral grip).", "Keeping your elbow slightly flexed, exhale as you raise the dumbbell directly out to the side until it is level with the height of your shoulder.", "Hold for a count of two.", "Inhale as you lower the dumbbell to the starting position in a controlled manner.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/12/One-arm-dumbbell-bent-over-lateral-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/one-arm-dumbbell-bent-over-lateral-raise/"}, {"id": "standing-cable-row", "name": "Standing cable row", "name_ko": "로우", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Attach a double-row bar (or two stirrups/handles) to a cable pulley that is a little lower than waist high.", "Grasp the double-row bar with both hands and step back until the cable is pulled taut and your arms and shoulders are stretched forward.", "Flex your hips and knees so that you are almost in a seated position.", "Keeping your elbows close to your body, exhale as you pull the double-row bar to your lower abdomen.", "Hold for a count of two, stick out your chest, and squeeze your back muscles.", "Inhale as you return the double-row bar to the starting position, with your arms and shoulders stretching forward.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/11/Standing-cable-row-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/standing-cable-row/"}, {"id": "rope-lat-pull-down", "name": "Rope lat pull-down", "name_ko": "Rope lat pull-down", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Sit on the cable machine.", "Secure your legs under the thigh pad.", "Grasp the rope with a neutral grip (palms facing each other). Your arms and shoulders should be fully extended upward.", "Keeping your elbows close to your body, exhale as you pull the rope down until your elbows move behind you.", "Stick out your chest, squeeze your back muscles, and hold for a count of two.", "Inhale as you return the rope to the starting position, with your arms and shoulders fully extended upward.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/07/Lat-pull-down-with-rope-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/rope-lat-pull-down/"}, {"id": "prone-incline-wide-grip-upright-row", "name": "Prone incline wide-grip upright row", "name_ko": "로우", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Holding a loaded barbell with a shoulder-width, pronated (overhand) grip, lie prone (on your front) on a bench inclined at 45 or more degrees and allow the barbell to hang straight down.", "Exhale as you pull the barbell up to your lower chest.", "Hold for a count of two.", "Inhale as you lower the barbell to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/06/prone-incline-upright-row-resized-1.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/prone-incline-wide-grip-upright-row/"}, {"id": "lying-dumbbell-rear-lateral-raise", "name": "Lying reverse dumbbell fly", "name_ko": "플라이", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Place two dumbbells on the floor, one on each side of a flat bench.", "Lie prone (on your front) on the bench and grasp a dumbbell in each hand.", "Spread your legs on the floor for support.", "Keeping your elbows slightly bent, exhale as you raise the dumbbells out to the sides.", "Hold for a count of two.", "Inhale as you lower the dumbbells to the starting position in a controlled manner.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/05/Lying-dumbbell-rear-lateral-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lying-dumbbell-rear-lateral-raise/"}, {"id": "elbow-lift", "name": "Elbow lift", "name_ko": "Elbow lift", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Place two low chairs side by side, with a gap between them.", "Sit between the chairs, on the floor, with your legs straight.", "Place the backs of your upper arms onto the chairs and raise your butt off the floor so that your body is straight and rigid.", "Keeping your body rigid, exhale as you lift your body by pressing the backs of your upper arms down onto the chairs.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you lower your body to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/01/elbow-lift-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/elbow-lift/"}, {"id": "one-arm-towel-row", "name": "One-arm towel row", "name_ko": "로우", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Place your feet on either side of an open door.", "Wrap a towel around one of the door handles and hold the towel with one hand.", "Carefully lean backward with your hips and knees a little bent and your arm and shoulder stretching forward.", "Keeping your elbow close to your torso, exhale as you pull yourself toward the door.", "At the top of the movement, hold for a count of two and squeeze your back muscles.", "Inhale as you lower yourself to the starting position, with your arm and shoulder stretching forward.", "Repeat for the prescribed number of repetitions.", "Repeat with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/12/Towel-row-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/one-arm-towel-row/"}, {"id": "standing-twisting-cable-row", "name": "Standing twisting cable row", "name_ko": "로우", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Attach a stirrup (handle) to an elbow-high cable pulley.", "Grasp the stirrup with your right hand and step backward until the cable is pulled taut, your arm and shoulder are stretched forward, and your waist is rotated towards the pulley.", "Position your right foot in front of your left foot for stability. Your knees should be slightly bent, your right foot should be flat, and your left heel should be raised off the floor.", "Place your free hand on your hip.", "Keeping your elbow close to your body, exhale as you pull the stirrup to the side of your waist and rotate your body to the same side as your loaded arm.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you reverse the movement and return the stirrup to the starting position, with your arm and shoulder stretching forward and your waist rotated towards the pulley.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise with your left arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/12/standing-twisting-cable-row-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/standing-twisting-cable-row/"}, {"id": "standing-cable-rear-delt-row-with-rope", "name": "Standing cable rear delt row with rope", "name_ko": "로우", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Attach a rope to the cable pulley and adjust the pulley so that it is shoulder height.", "Grasp one end of the rope in each hand and step backward until the rope is pulled taut and your arms and shoulders are stretched forward.", "Stagger your feet for stability (put one foot in front of the other).", "Keeping your elbows out to the sides, exhale as you pull the rope towards your shoulders until your elbows travel passed your back.", "Hold for a count of two.", "Inhale as you reverse the motion and return the rope to the starting position, with your shoulders stretching forward.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/12/Cable-standing-rear-delt-row-with-rope-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/standing-cable-rear-delt-row-with-rope/"}, {"id": "standing-twisting-cable-high-row", "name": "Standing twisting cable high row", "name_ko": "로우", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Grasp the stirrup (handle) of a high cable pulley with your right hand and step backward until the cable is pulled taut.", "Stagger your feet so that your right foot is positioned in front of your left foot, with your knees slightly bent, your right foot flat, and your left heel raised off the floor. Your arm should be fully extended, your shoulder should be stretched upward, and your waist should be rotated towards the pulley.", "Place your free hand on your hip.", "Keeping your elbow close to your body, exhale as you pull the stirrup to the side of your waist, rotate your body to the side of your loaded arm, and pull your shoulder back.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you reverse the motion and return the stirrup to the starting position, with your arm fully extended, your shoulder stretched upward, and your waist rotated towards the pulley.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise with your left arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/09/standing-twisting-cable-high-row-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/standing-twisting-cable-high-row/"}, {"id": "double-cable-neutral-grip-lat-pull-down", "name": "Double cable neutral-grip lat pull-down", "name_ko": "Double cable neutral-grip lat pull-down", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Attach a stirrup (handle) to two high cable pulleys.", "Position a bench or chair midway between the two pulleys.", "Grasp a stirrup in each hand and sit directly under the pulleys, holding the stirrups using a neutral (aka parallel) grip (palms facing each other). The cables should be pulled taut, your arms should be fully extended, and your shoulders should be stretched upward.", "Exhale as you pull the stirrups downward until your elbows are by your sides.", "Hold for a count of two, stick out your chest, and squeeze your back muscles.", "Inhale as you return the stirrups to the starting position, with your arms fully extended and shoulders stretched upward.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/double-cable-neutral-grip-lat-pull-down-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/double-cable-neutral-grip-lat-pull-down/"}, {"id": "machine-assisted-close-neutral-grip-pull-up", "name": "Machine-assisted close neutral-grip pull-up", "name_ko": "풀업", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Kneel onto the padded platform of the assisted pull-up machine and grasp the close parallel bars.", "Allow your body to descend until your arms are fully extended and your shoulders are stretched upward.", "Exhale as you pull your body upward until your elbows are by the sides of your body.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you lower your body in a controlled manner until your arms are fully extended and your shoulders are stretched upward.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/machine-assisted-neutral-grip-pull-up-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/machine-assisted-close-neutral-grip-pull-up/"}, {"id": "smith-machine-underhand-yates-row", "name": "Smith machine underhand Yates row", "name_ko": "로우", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Lower the Smith machine bar to the height of your lower thighs.", "Grasp the bar with a shoulder-width supinated (underhand) grip.", "Flex your hips and knees and lean forward at a 45-degree angle.", "Rotate the bar to unlatch it from the rail.", "Keeping your back and neck neutral, exhale as you pull the bar up to your waist.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you slowly lower the bar to the starting position.", "Repeat for more repetitions.", "When you have finished, rotate the bar to latch it back onto the rail."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/07/Smith-machine-underhand-Yates-row-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/smith-machine-underhand-yates-row/"}, {"id": "head-supported-bent-over-dumbbell-lateral-raise", "name": "Head-supported reverse dumbbell fly", "name_ko": "플라이", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Raise a bench to hip height.", "Grasp a dumbbell in each hand and stand behind the bench.", "Flex your hips and rest your forehead on the edge of the bench. Your back should be straight, your torso should be horizontal, and your arms should be hanging straight down in front of you, with your palms facing inward (neutral or hammer grip).", "Keeping your elbows slightly flexed, exhale as you raise both arms out to the sides until your elbows are level with your shoulders. At the top of the movement, your pinky finger should be higher than your other fingers.", "Hold for a count of two.", "Inhale as you slowly lower the dumbbells to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/07/dumbbell-bent-over-lateral-raise-head-supported-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/head-supported-bent-over-dumbbell-lateral-raise/"}, {"id": "straight-back-seated-underhand-cable-row", "name": "Straight-back seated underhand cable row", "name_ko": "로우", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Sit on the cable machine and grasp the straight bar using a shoulder-width supinated (underhand) grip.", "Slide your buttocks backward and straighten your back. The cable should be pulled taut, and your arms and shoulders should be stretching forward.", "Keeping your elbows close to your body, exhale as you pull the bar to your abdomen.", "Hold for a count of two, stick out your chest, and squeeze your back muscles.", "Inhale as you return the bar to the starting position, with your arms and shoulders stretching forward.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/07/underhand-cable-row-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/straight-back-seated-underhand-cable-row/"}, {"id": "landmine-row", "name": "Landmine row", "name_ko": "로우", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Stand with a loaded landmine between your legs.", "Bend at the hips and a little at the knees and grasp the landmine bar just under the plates with both hands. You can either interlink your fingers or place one hand over the other. Instead of grasping the landmine bar, you can also hook a double-row bar around it. Your back should be straight and close to horizontal.", "Keeping your elbows close to your body, exhale as you pull the landmine up to your chest.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you lower the landmine in a controlled manner until your shoulders stretch downward. Don’t allow the landmine to touch the floor.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/07/landmine-row-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/landmine-row/"}, {"id": "seated-twisting-cable-row", "name": "Seated twisting cable row", "name_ko": "로우", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Attach a stirrup to a cable row machine.", "Sit on the machine, place your feet on the foot rests, and grasp the stirrup with one hand.", "Slide your buttocks backward until your knees are almost straight, your arm and shoulder are stretched forward, and the cable is pulled taut.", "Exhale as you slowly pull the stirrup to the side of your abdomen and then twist your torso.", "Hold for a count of two.", "Inhale as you slowly reverse the motion and return the stirrup to the starting position, with your arm and shoulder stretching forward.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/07/seated-twisting-one-arm-cable-row-resized-1.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-twisting-cable-row/"}, {"id": "one-arm-lat-pull-down", "name": "One-arm lat pull-down", "name_ko": "One-arm lat pull-down", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Sit on the lat pull-down machine.", "Bring the thigh pad down onto your thighs so that you are secured into place.", "Grasp the stirrup (handle) with one hand. Your arm and shoulder should be fully stretched upward.", "Exhale as you slowly pull the stirrup down until your elbow is by the side of your body.", "Hold for a count of two.", "Inhale as you slowly return the stirrup to the starting position, with your arm and shoulder fully stretched upward.", "Repeat for more repetitions.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/07/One-arm-lat-pulldown-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/one-arm-lat-pull-down/"}, {"id": "weighted-inverted-row", "name": "Weighted inverted row", "name_ko": "로우", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Lock the bar of the Smith machine so that if you were to sit under it, it would be approximately head height.", "Place a bench or a box in front of the Smith machine, at a distance that you can reach with your feet when you sit under the bar.", "Sit under the bar and place a weight plate on your abdomen.", "Grasp the bar with a wide pronated (overhand) grip.", "Place the back of your heels on the bench or box.", "Lift your hips off the floor and straighten your body.", "Keeping your body straight and rigid and your elbows close to your body, exhale as you pull your chest up to the bar.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you lower your body until your arms and shoulders are fully extended.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/06/Weighted-inverted-row.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/weighted-inverted-row/"}, {"id": "one-leg-hyperextension", "name": "One-leg hyperextension", "name_ko": "하이퍼익스텐션", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Stand in the hyperextension bench with one leg. Make sure that your leg is hooked securely under the foot brace and that the front padding rests below your hips to allow your hips room to move.", "Cross your arms over your chest.", "Inhale as you lower your body until your hips and your back are fully flexed.", "Exhale as you raise your body until your hips and your back are fully extended.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/05/one-leg-hyperextension-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/one-leg-hyperextension/"}, {"id": "bent-over-one-arm-cable-pull", "name": "Bent-over one-arm cable pull", "name_ko": "Bent-over one-arm cable pull", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Set up a waist-high cable pulley.", "Grasp the stirrup (handle) with one hand.", "Stand back with a wide, staggered stance.", "Flex your hips and knees until your torso is horizontal. Your arm and shoulder should be stretching forward.", "Keeping your elbow close to your body, exhale as you pull the stirrup to the side of your chest.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you reverse the motion and return the stirrup to the starting position, with your arm and shoulder stretching forward.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/03/bent-over-one-arm-cable-pull-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/bent-over-one-arm-cable-pull/"}, {"id": "underhand-yates-row", "name": "Underhand Yates row", "name_ko": "로우", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Holding a barbell using a shoulder-width supinated (underhand) grip, stand with your feet hip-width apart.", "Flex your hips and knees to lean forward at a 45-degree angle. Your arms should be almost fully extended and the barbell should be resting on your thighs.", "Keeping your head up and your back straight, exhale as you pull the barbell up to your waist.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you lower the barbell to the starting position in a controlled manner.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/02/underhand-yates-row-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/underhand-yates-row/"}, {"id": "straight-back-seated-cable-row", "name": "Straight-back seated cable row", "name_ko": "로우", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Sit on the cable row machine and place your feet on the foot rests.", "Grasp the double-row bar and slide your buttocks backward until your knees are almost straight.", "Lean backward until your torso is vertical. Your back should be straight, the cable should be pulled taut, and your arms and shoulders should be stretching forward.", "Keeping your torso vertical, back straight, and elbows close to your body, exhale as you slowly pull the double-row bar to your abdomen.", "Hold for a count of two, stick out your chest, and squeeze your back muscles.", "Inhale as you slowly return the double-row bar to the starting position, with your arms and shoulders stretching forward.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/02/straight-back-seated-cable-row-resized-1.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/straight-back-seated-cable-row/"}, {"id": "barbell-sumo-deadlift", "name": "Barbell sumo deadlift", "name_ko": "데드리프트", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Stand with a wide stance next to the barbell, with your feet and knees pointing out to the sides in the same direction.", "Flex your hips and grasp the bar with a shoulder-width pronated (overhand) grip.", "Flex your knees to lower your hips, and bring your hips forward, close to the bar. Your torso should be upright, you back and arms should be straight, and your head should be facing forward.", "Exhale as you drive through your legs and pull the bar up the front of your body until you are fully standing. Keep the bar close to your body.", "Hold for a count of two and push your chest out.", "Inhale as you flex your knees and lower the bar to the floor in a controlled manner, keeping your back straight, torso upright, and head up.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/02/Barbell-sumo-deadlift-1.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-sumo-deadlift/"}, {"id": "medium-grip-lat-pull-down", "name": "Medium-grip lat pull-down", "name_ko": "Medium-grip lat pull-down", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Sit on the lat pull-down machine.", "Bring the thigh pad down onto your thighs so that you are secured in place.", "Grasp the bar with a pronated (overhand) grip, with your hands a little wider than shoulder width apart (medium grip). Your arms and shoulders should be fully stretched upward.", "Keeping your head back and chest out, exhale as you slowly pull the bar down to the upper part of your chest.", "Hold for a count of two and squeeze your shoulder blades together.", "Inhale as you slowly return the bar to the starting position, with your arms and shoulders fully stretched.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/01/Lat-pull-down-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/medium-grip-lat-pull-down/"}, {"id": "assisted-pull-up", "name": "Machine-assisted pull-up", "name_ko": "풀업", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Grasp the handles with a wider-than-shoulder-width pronated (overhand) grip.", "Kneel onto the knee pad and allow your bodyweight to weigh down the knee pad so that you hang with your arms and shoulders stretched.", "Exhale as you pull your body up until your chin rises over the bar.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you lower your body until your arms and shoulders are fully stretched.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/01/assisted-pull-up-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/assisted-pull-up/"}, {"id": "bent-over-two-arm-dumbbell-row", "name": "Bent-over two-arm dumbbell row", "name_ko": "로우", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in each hand using a neutral (hammer) grip, stand with your feet shoulder-width apart.", "Keeping a natural curvature of your spine, flex your hips and knees until your torso is horizontal or close to horizontal.", "Allow the dumbbells to hang down by your sides, with your shoulders stretching downward.", "Keeping your elbows close to your body, exhale as you pull the dumbbells up to the sides of your waist.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you lower the dumbbells to the starting position, with your shoulders stretching downward.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/01/bent-over-two-arm-dumbbell-row-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/bent-over-two-arm-dumbbell-row/"}, {"id": "lying-dumbbell-one-arm-rear-lateral-raise", "name": "Lying one-arm reverse dumbbell fly", "name_ko": "플라이", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in one hand, lie prone (on your front) on a flat bench. Ideally, the bench should be elevated to allow the dumbbell to hang straight down without touching the floor.", "Spread your legs and plant your feet firmly on the floor.", "Grasp the bench with your free hand for stability.", "Keeping your elbow slightly bent, exhale as you raise the dumbbell out to the side.", "Hold for a count of two.", "Inhale as you lower the dumbbell to the starting position in a controlled manner.", "Repeat for the desired number of repetitions.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/01/lying-dumbbell-one-arm-lateral-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lying-dumbbell-one-arm-rear-lateral-raise/"}, {"id": "machine-back-extension", "name": "Machine back extension", "name_ko": "Machine back extension", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Sit in the back extension machine, with your back resting against the lever and your feet on one of the foot pads (foot placement is incorrect in illustration; awaiting correction).", "Adjust the lever so that it pushes your torso down and allows you to get a full range of motion when you perform the exercise. The angle of your hips should be approximately 90 degrees.", "Press your lower back against the lumbar support pad by pushing against the foot pad. As explained in the Comments and tips, this is important to keep your hips from extending as you extend your back.", "Keeping your hips fixed, exhale as you slowly extend your back until it is slightly hyperextended.", "Hold for a count of two.", "Inhale as you slowly return to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/01/Machine-Back-Extension-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/machine-back-extension/"}, {"id": "machine-one-arm-row", "name": "Machine one-arm row", "name_ko": "로우", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Adjust the machine’s seat and chest pad for optimal comfort and range of motion.", "Sit on the machine.", "Position your chest against the front pad.", "Plant your feet firmly on the floor.", "Grasp the handles. Your arms and shoulders should be stretched forward.", "Keeping your back straight, exhale as you pull one of the handles to the side of your waist.", "Hold for a count of two, stick out your chest, and squeeze your back muscles.", "Inhale as you slowly return the handle to the starting position.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/01/Machine-one-arm-row-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/machine-one-arm-row/"}, {"id": "gripless-shrug", "name": "Gripless shrug", "name_ko": "슈러그", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Stand inside the standing calf raise machine with your shoulders under the pads.", "Grasp the handles for stability, although this isn’t necessary.", "Exhale as you slowly elevate your shoulders as high as you can.", "Hold for a count of two.", "Inhale as you slowly lower your shoulders to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/12/Machine-Gripless-Shrug-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/gripless-shrug/"}, {"id": "barbell-rack-pull", "name": "Barbell rack pull", "name_ko": "Barbell rack pull", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Place a barbell on the safety pins of a power rack. The barbell should be just under knee height.", "Load the barbell.", "Stand with your legs almost touching the barbell, with your feet shoulder-width apart and pointing slightly outward.", "Grasp the barbell with a pronated (overhand) grip, with your hands shoulder-width apart.", "Straighten your back, lower your hips and raise your head.", "Keeping your head up and your back and arms straight, exhale as you stand, push your hips forward and drag the barbell up the front of your legs until you are fully standing.", "At the top of the lift, squeeze your glutes and pull your shoulders back.", "Inhale as you push your bottom backward and lower the barbell down the front of your legs to the safety pins in a controlled manner.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/12/rack-pull-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-rack-pull/"}, {"id": "machine-high-row", "name": "Machine high row", "name_ko": "로우", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Adjust the high row machine’s seat and chest pad for optimal comfort and range of motion.", "Sit in the machine, with your legs secured under the leg pads and your chest braced against the chest pad.", "Grasp the handles using a pronated (overhand) grip. Your arms should be fully extended and your shoulders should be stretched forward.", "Exhale as you pull the handles backward until your elbows are behind you and your shoulders are pulled backward.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you allow the handles to return to the starting position, with your shoulders stretched forward.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/12/machine-high-row-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/machine-high-row/"}, {"id": "seated-bent-over-lateral-raise", "name": "Seated reverse dumbbell fly", "name_ko": "플라이", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Holding a pair of dumbbells, sit on the end of a bench.", "Lean forward until your torso is as close to horizontal as possible and allow your arms to hang down by your feet. Your palms should be facing each other (neutral grip).", "Keeping your arms slightly bent and your elbows perpendicular to your torso, exhale as you raise your arms out to the sides until your elbows are shoulder height.", "Hold for a count of two.", "Inhale as you lower your arms to the starting position in a controlled manner.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/12/seated-bent-over-lateral-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-bent-over-lateral-raise/"}, {"id": "supine-cable-reverse-fly", "name": "Supine cable reverse fly", "name_ko": "플라이", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Position a flat bench between two high pulleys.", "Lie supine (on your back) holding the pulleys’ stirrups (handles). The stirrup from the right pulley should be in your left hand and the stirrup from the left pulley should be in your right hand. The cables should be crossed and pulled taut.", "Keeping your arms perpendicular to your torso and your elbows slightly bent, exhale as you pull your arms open and out to the sides.", "Hold for a count of two.", "Inhale as you return your arms to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/Supine-Cable-Reverse-Fly-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/supine-cable-reverse-fly/"}, {"id": "machine-reverse-hyperextension", "name": "Machine reverse hyperextension", "name_ko": "하이퍼익스텐션", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Mount the reverse hyperextension machine and secure your legs between the foot pads. Your upper body should be lying face down on the machine’s surface, your hips should be positioned off the edge of the surface, and your legs should be hanging straight down.", "Hold the handles for stability.", "Keeping your knees slightly bent, exhale as you slowly raise the lever as high as you can by extending your hips and your lower back.", "Try to hold the contracted position for a count of two.", "Inhale as you slowly reverse the motion and lower the lever to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/Lever-Reverse-Hyperextension-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/machine-reverse-hyperextension/"}, {"id": "behind-the-neck-lat-pull-down", "name": "Behind-the-neck lat pull-down", "name_ko": "Behind-the-neck lat pull-down", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["N/A. See Comments and tips."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/Cable-Rear-Pulldown-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/behind-the-neck-lat-pull-down/"}, {"id": "inverted-row", "name": "Inverted row", "name_ko": "로우", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Adjust the height of the Smith machine bar so that it’s a little higher than arm’s length from the floor.", "Lie under the bar with your legs and body straight.", "Grasp the bar with an overhand grip that’s a little wider than shoulder width.", "Keeping your legs and body straight and your elbows close to your body, exhale as you pull your chest up to the bar.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you lower your body until your arms and shoulders are fully extended.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/Inverted-row.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/inverted-row/"}, {"id": "superman-exercise", "name": "Superman", "name_ko": "Superman", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Lie prone (face down) on a mat with your legs straight and your arms extended straight in front of you.", "Gently raise your arms, upper torso, and legs off the mat.", "Hold for a count of two.", "Gently return them to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/superman-exercise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/superman-exercise/"}, {"id": "close-neutral-grip-pull-up", "name": "Close neutral-grip pull-up", "name_ko": "풀업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Grasp the double pull-up bars and hang with your arms and shoulders fully extended.", "You can cross your feet, keep your legs straight, or bend your knees.", "Exhale as you pull your body up until your chin rises above the bars.", "Hold for a count of two.", "Inhale as you lower your body until your arms and shoulders are fully extended.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/close-neutral-grip-pull-up-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/close-neutral-grip-pull-up/"}, {"id": "cable-rear-delt-row", "name": "Cable rear delt row", "name_ko": "로우", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Sit in front of the cable machine and grasp the long bar with a pronated (overhand) elbow-width grip.", "Slide your buttocks backward and lean back so that your torso is upright, your back is straight, and your arms and shoulders are extended in front of you.", "Exhale as you pull the bar toward your upper chest, keeping your elbows at shoulder height and your body still.", "Hold for a count of two.", "Inhale as you slowly return the bar to the starting position, with your shoulders and arms extended in front of you.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/Cable-Rear-Delt-Row.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-rear-delt-row/"}, {"id": "dumbbell-cuban-rotation", "name": "Dumbbell Cuban rotation", "name_ko": "Dumbbell Cuban rotation", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Stand holding a dumbbell in one hand.", "Lean forward a little by flexing your hips and knees (not illustrated in image).", "Raise your elbow to shoulder height and allow the dumbbell to hang straight down with your elbow bent at a 90-degree angle.", "Keeping your elbow in the same position, exhale as you raise the dumbbell until it is level with your head by externally rotating your shoulder .", "Inhale as you slowly lower the dumbbell to the starting position.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/dumbbell-cuban-rotation-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-cuban-rotation/"}, {"id": "seated-one-arm-cable-row", "name": "Seated one-arm cable row", "name_ko": "로우", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Sit on the cable row machine, place your feet on the foot rests, and grasp the stirrup.", "Slide backward until your knees are almost straight.", "Straighten your back so that your arm and shoulder are stretched forward and the cable is pulled taut.", "Keeping your elbow close to your body, exhale as you slowly pull the stirrup to the side of your abdomen and stick out your chest.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you slowly return the stirrup to the starting position.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/cable-seated-one-arm-row-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-one-arm-cable-row/"}, {"id": "dumbbell-deadlift", "name": "Dumbbell deadlift", "name_ko": "데드리프트", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Position a pair of dumbbells horizontally in front of your feet.", "Squat and grasp the dumbbells using a pronated (overhand) grip.", "Raise your hips a little, straighten your back, and lean backward so that your torso is upright.", "Exhale as you stand up and pull the dumbbells up across the front of your body.", "Inhale as you push your butt backward, flex your hips and knees, and lower the dumbbells down the front of your body to the floor.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Dumbbell-Deadlift-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-deadlift/"}, {"id": "dumbbell-lying-external-shoulder-rotation", "name": "Dumbbell lying external shoulder rotation", "name_ko": "Dumbbell lying external shoulder rotation", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Lie on your side, either supporting your upper body on your elbow and forearm, resting your head in your hand, or even resting your head on a pillow.", "Grasp a dumbbell with your free hand, bend your elbow to a 90-degree angle, rest your elbow against your side, and lower your forearm across your belly.", "Keeping your elbow against your side, exhale as you raise the dumbbell as high as possible by externally rotating your shoulder.", "Hold for a count of two.", "Inhale as you slowly lower the dumbbell across your belly.", "Repeat.", "Repeat with your other arm while lying on your opposite side."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/dumbbell-lying-external-shoulder-rotation-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-lying-external-shoulder-rotation/"}, {"id": "cable-face-pull", "name": "Cable face pull", "name_ko": "페이스 풀", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Stand in front of a pulley set at approximately head height.", "Grasp one end of the rope attachment in each hand using a supinated (underhand) grip.", "Step backward so that the rope is taut and your arms are stretched out in front of you.", "Assume a staggered stance (place one foot in front of the other) and lean backward to help you balance.", "Exhale as you pull the rope toward your forehead.", "As the rope nears your face, externally rotate your shoulders so that you end up making a double biceps pose.", "Hold for a count of two.", "Inhale as you reverse the motion and return the rope to the starting position in a controlled manner.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Face-pull-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-face-pull/"}, {"id": "romanian-deadlift", "name": "Barbell Romanian deadlift", "name_ko": "데드리프트", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Using a shoulder-width pronated (overhand) grip, deadlift a barbell from the floor. You should be standing with your arms extended, the bar resting against the front of your thighs, your knees slightly bent, and your feet approximately shoulder-width apart.", "Inhale as you push your butt back, hinge forward at your hips, and lower the barbell down your thighs until you feel a slight stretch in your hamstrings.", "Exhale as you extend your hips and pull the barbell back up your legs to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Barbell-Romanian-Deadlift.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/romanian-deadlift/"}, {"id": "bent-over-barbell-row", "name": "Bent-over barbell row", "name_ko": "로우", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Stand over a loaded barbell, with the bar lining up with your toes.", "Bend at the hips and a little at the knees and grasp the barbell with hands a little wider than shoulder width apart. Your back should be straight and close to horizontal.", "Exhale as you pull the barbell up to your waist.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you lower the barbell in a controlled manner until it nearly touches the floor.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Bent-over-barbell-row.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/bent-over-barbell-row/"}, {"id": "pull-up", "name": "Pull-up", "name_ko": "풀업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Grasp the bar with a wider-than-shoulder-width pronated (overhand) grip.", "Hang with your arms and shoulders fully stretched.", "Exhale as you pull your body up until your chin rises above the bar.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you lower your body until your arms and shoulders are fully stretched.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/pull-up-2-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/pull-up/"}, {"id": "reverse-grip-lat-pull-down", "name": "Reverse-grip lat pull-down", "name_ko": "Reverse-grip lat pull-down", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Sit on the lat pull-down machine, adjusting it so that your thighs fit snugly under the supports.", "Grasp the bar using a shoulder-width supinated (reverse or underhand) grip (palms facing you).", "Exhale as you pull the bar down until it touches your upper chest.", "Squeeze your back muscles and hold for a count of two.", "Inhale as you return the bar to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/reverse-grip-lat-pull-down-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/reverse-grip-lat-pull-down/"}, {"id": "cable-external-shoulder-rotation", "name": "Cable external shoulder rotation", "name_ko": "Cable external shoulder rotation", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Stand with your side to an elbow-height pulley, holding the stirrup with your far arm.", "Lock your elbow by your side and position your forearm across your belly. Your arm should be bent at a 90-degree angle.", "Keeping your elbow locked to your side, exhale as you pull the cable away from your body by externally rotating your shoulder.", "Hold for a count of two.", "Inhale as you return your forearm to the starting position.", "Repeat for the desired number of repetitions.", "Repeat with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Cable-Standing-Shoulder-External-Rotation-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-external-shoulder-rotation/"}, {"id": "close-neutral-grip-lat-pull-down", "name": "Close neutral-grip lat pull-down", "name_ko": "Close neutral-grip lat pull-down", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Sit on the lat pull-down machine with your thighs positioned snugly under the supports.", "Grasp the double-row V handle. Your arms and shoulders should be fully extended upward.", "Exhale as you pull the handle down until it touches your upper chest.", "Squeeze your back muscles and hold for a count of two.", "Inhale as you return the handle to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Cable-close-grip-pull-down-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/close-neutral-grip-lat-pull-down/"}, {"id": "dumbbell-shrug", "name": "Dumbbell shrug", "name_ko": "슈러그", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Stand with your feet hip-width apart and your arms by your sides, holding a dumbbell in each hand.", "Exhale as you elevate your shoulders straight up as high as possible.", "Hold for a count of two and squeeze your trapezius.", "Inhale as you lower your shoulders to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/dumbbell-shrug-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-shrug/"}, {"id": "wide-grip-cable-row", "name": "Wide-grip cable row", "name_ko": "로우", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Sit facing the cable row machine and place your feet on the foot rests.", "Grasp the long bar with a wider-than-shoulder-width grip and slide your bottom backward until your knees are almost straight. You torso should be leaning forward and your arms should be fully extended.", "Exhale as you slowly lean backward, straighten your back, and pull the bar to your abdomen. Pull your shoulders back and stick out your chest at the top of the movement.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you slowly lean forward and return the bar to the starting position, with your arms fully extended and your lower back bent forward.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Cable-Seated-Wide-grip-Row-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/wide-grip-cable-row/"}, {"id": "hyperextension", "name": "Hyperextension", "name_ko": "하이퍼익스텐션", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Lie prone (face down) on a hyperextension bench with your legs tucked firmly under the foot pads.", "If necessary, adjust the upper pad so that it lies below your hips, giving your hips room to fully flex.", "Put your hands lightly behind your head or cross them on your chest.", "Inhale as you lower your torso by flexing your hips and waist.", "Exhale as you raise your torso by extending your hips and back.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/45-degree-hyperextension.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/hyperextension/"}, {"id": "bent-over-dumbbell-row", "name": "Bent-over dumbbell row", "name_ko": "로우", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in your left hand, kneel on a bench with your right knee and support your body with your right arm. The dumbbell should be hanging straight down, with your left arm almost fully extended.", "Exhale as you pull the dumbbell up to the side of your waist.", "Hold for a count of two.", "Inhale as you lower the dumbbell to the starting position.", "Repeat for the desired number of reps.", "Repeat with your right arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/bent-over-one-arm-dumbbell-row-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/bent-over-dumbbell-row/"}, {"id": "t-bar-row", "name": "T-bar row", "name_ko": "로우", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Stand over a t-bar with a wide stance and knees slightly bent.", "Keeping your torso upright and back straight, bend down, grasp the handles with either a wide or a shoulder-width grip, and pull the bar off the floor a little. Your back should be straight and almost horizontal, and your arms should be almost fully extended.", "Exhale as you pull the t-bar up to your abdomen.", "Hold for a count of two.", "Inhale as you return the t-bar to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/lever-t-bar-row-plate-loaded-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/t-bar-row/"}, {"id": "seated-cable-row", "name": "Seated cable row", "name_ko": "로우", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Sit facing the cable row machine and place your feet on the foot rests.", "Grasp the double-row bar and slide your bottom backward until your knees are almost straight. You torso should be leaning forward and your arms and shoulders should be stretching forward.", "Exhale as you slowly lean backward, straighten your back, and pull the v-bar to your abdomen, keeping your elbows close to your body. Pull your shoulders back and stick out your chest at the top of the movement.", "Hold for a count of two and squeeze your back muscles.", "Inhale as you slowly lean forward and return the double-row bar to the starting position, with your arms and shoulders stretching forward and your lower back bent forward.", "Repeat for the recommended number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/05/Seated-cable-row-new-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-cable-row/"}, {"id": "wide-grip-lat-pull-down", "name": "Wide-grip lat pull-down", "name_ko": "Wide-grip lat pull-down", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Choose your weight and sit on the lat pull-down machine, adjusting it so that your thighs fit under the supports.", "Grasp the bar with a pronated (overhand) grip, with your hands more than shoulder-width apart.", "Exhale as you slowly pull the bar down until it touches the upper part of your chest.", "Squeeze your shoulder blades together and hold for a count of two.", "Inhale as you slowly return the bar to the starting position.", "Repeat for the recommended number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/05/wide-grip-lat-pull-down-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/wide-grip-lat-pull-down/"}, {"id": "barbell-shrug", "name": "Barbell shrug", "name_ko": "슈러그", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Stand holding a barbell using a shoulder-width pronated grip (palms facing your body).", "Exhale as you elevate your shoulders as high as possible.", "Hold for a count of two and squeeze your trapezius.", "Inhale as you lower the barbell back to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/05/Barbell-Shrug-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-shrug/"}, {"id": "bent-over-lateral-raise", "name": "Reverse dumbbell fly", "name_ko": "플라이", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in each hand, bend at the hips and knees until your torso is parallel to the floor. Your back should be straight and your arms should be hanging in front of you, with your palms facing inwards (neutral grip).", "Keeping your elbows slightly bent, raise both arms out to the sides until the dumbbells are level with the height of your shoulders. Don’t forget to exhale.", "Hold for a count of two.", "Inhale as you lower the dumbbells to the starting position in a controlled manner.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/05/Dumbbell-Rear-Lateral-Raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/bent-over-lateral-raise/"}, {"id": "barbell-deadlift", "name": "Barbell deadlift", "name_ko": "바벨 데드리프트", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["lats"], "secondary_muscles": [], "instructions": ["Stand with your feet under the barbell, hip-width apart. When you look down, the barbell should run halfway over your feet.", "Bend down and grasp the barbell with a shoulder-width grip.", "Take a deep breath.", "Keeping your torso upright and your back and arms straight, stand and pull the bar up the front of your legs, driving with your legs.", "At the top of the movement, squeeze your glutes, pull your shoulders back, and exhale.", "To return the bar to the floor, push your butt backward and lower the bar down the front of your legs, keeping your back straight.", "Once the bar passes your knees, bend your knees and lower the bar to the floor."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/05/Barbell-Deadlift-1.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-deadlift/"}, {"id": "incline-dumbbell-shoulder-raise", "name": "Incline dumbbell shoulder raise", "name_ko": "Incline dumbbell shoulder raise", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in each hand with an overhand (pronated) grip, lie on your back on an inclined bench.", "Press the dumbbells directly upward.", "Keeping your elbows straight, exhale as you lift your shoulders off the bench as high as possible.", "Hold for a count of two.", "Inhale as you lower your shoulders back to the bench.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/05/Incline-dumbbell-shoulder-raise.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-dumbbell-shoulder-raise/"}, {"id": "prone-incline-dumbbell-front-raise", "name": "Prone incline dumbbell front raise", "name_ko": "프론트 레이즈", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Grip a dumbbell in each hand using an overhand grip.", "Lie prone (face down) on an inclined bench. Allow the dumbbells to hang downward.", "Keeping your elbows slightly flexed, exhale as you raise the dumbbells forward and upward until the dumbbells are level with your head.", "Hold for a count of two.", "Inhale as you slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/04/Prone-incline-dumbbell-front-raise.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/prone-incline-dumbbell-front-raise/"}, {"id": "band-shoulder-press", "name": "Band shoulder press", "name_ko": "숄더 프레스", "category": "strength", "equipment": "resistance_band", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Stand with the middle of the resistance band underneath your feet and grip the handles with an underhand (supinated) grip.", "Bend your elbows to bring your hands to the sides of your shoulders. Allow the cables to stretch behind your shoulders.", "Your neck and back should be in neutral position, your elbows out to the sides, and your palms facing front.", "Keeping your back neutral and elbows out to the sides, exhale as you straighten your elbows, pressing upward against the band.", "Hold for a count of two.", "Inhale as you slowly return to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/01/Band-shoulder-press.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/band-shoulder-press/"}, {"id": "ez-bar-wide-grip-upright-row", "name": "EZ bar wide-grip upright row", "name_ko": "로우", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Stand tall holding an EZ bar in front of your thighs using a shoulder-width, overhand grip.", "Exhale as you pull the bar up until it is level with your lower or middle chest. Do not pull the bar any higher.", "Hold for a count of two.", "Inhale as you slowly lower the bar back to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/11/EZ-bar-wide-grip-upright-row.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/ez-bar-wide-grip-upright-row/"}, {"id": "kettlebell-lateral-raise", "name": "Kettlebell lateral raise", "name_ko": "레터럴 레이즈", "category": "strength", "equipment": "kettlebell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Stand tall, holding a kettlebell in each hand with an overhand grip. Allow your arms to hang by your sides.", "Keeping your elbows slightly bent, exhale as you raise both arms out to the sides until your elbows are level with your shoulders.", "Hold for a count of two.", "Inhale as you lower the dumbbells back to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/11/Kettlebell-lateral-raise.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/kettlebell-lateral-raise/"}, {"id": "dumbbell-spell-caster", "name": "Dumbbell spell caster", "name_ko": "Dumbbell spell caster", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Stand with your legs hip-width apart and hold a dumbbell in each hand using an overhand grip.", "Keeping your arms straight, inhale as you bend your knees and twist your torso to the right so that both dumbbells are outside your right knee.", "Exhale as you straighten your knees while twisting your torso to the left, bringing both dumbbells across your body in an upward and diagonal movement.", "Inhale as you lower the dumbbells to the outside of your left knee while simultaneously bending your knees.", "Exhale as you straighten your knees and twist your torso to the right, bringing both dumbbells across your body in an upward and diagonal movement.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/12/Dumbbell-spell-caster.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-spell-caster/"}, {"id": "handstand-press", "name": "Handstand press", "name_ko": "Handstand press", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Position two benches shoulder-width apart, against the wall perpendicularly.", "Assume a handstand position with one hand on each bench and heels against the wall. Your back should be neutral and positioned parallel to the wall.", "Keeping your back neutral and heels against the wall, inhale as you lower your head between the benches.", "Exhale as you straighten your arms and push your body back up to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/08/Handstand-press.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/handstand-press/"}, {"id": "band-front-raise", "name": "Band front raise", "name_ko": "프론트 레이즈", "category": "strength", "equipment": "resistance_band", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Stand with the middle of the band underneath your feet and your hands gripping the handles using an overhand grip.", "Keeping your elbows slightly bent, exhale as you raise the handles forward and upward until they are slightly above shoulder height.", "Hold for a count of two.", "Inhale as you reverse the motion and return to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/08/Band-front-raise.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/band-front-raise/"}, {"id": "barbell-front-squat-to-overhead-press", "name": "Barbell front squat to overhead press", "name_ko": "스쿼트", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Hold a barbell in front rack position with your elbows pointing forward. Keep your feet shoulder-width apart and pointing slightly outward.", "Keeping your torso upright, inhale as you squat down until your knees are bent at a 90-degree angle.", "Exhale as you drive through your heels to stand back up.", "As soon as you stand up, push the barbell straight upward.", "Inhale as you lower the barbell back to front rack position. Squat as soon as the barbell is back in front rack position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/07/Barbell-front-squat-to-overhead-press.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-front-squat-to-overhead-press/"}, {"id": "standing-wide-grip-barbell-overhead-press", "name": "Standing wide-grip barbell overhead press", "name_ko": "오버헤드 프레스", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Unrack the bar, holding the barbell at chest height using an overhand grip. Position your hands wider than shoulder-width apart.", "Exhale as you push the barbell straight upward.", "Shrug your shoulders at the top of the movement to raise the barbell even higher.", "Inhale as you reverse the motion to return to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/04/Standing-wide-grip-barbell-overhead-press.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/standing-wide-grip-barbell-overhead-press/"}, {"id": "dumbbell-one-arm-upright-row", "name": "Dumbbell one-arm upright row", "name_ko": "로우", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Stand upright, gripping a dumbbell in one hand using an overhand grip.", "Exhale as you pull the dumbbell upwards until it reaches your lower or middle chest.", "Hold for a count of two.", "Inhale as you lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions.", "Repeat on the opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/03/Dumbbell-one-arm-upright-row.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-one-arm-upright-row/"}, {"id": "seated-dumbbell-one-arm-shoulder-press", "name": "Seated dumbbell one-arm shoulder press", "name_ko": "숄더 프레스", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in one hand, sit on a bench or chair, with your torso upright.", "Hold on to your waist with your free hand or place it on your lap.", "Raise the dumbbell to the side of your shoulder. Your elbow should be directly out to your side, pointing downward, and your palm should be facing forward.", "Keeping your torso upright, exhale as you press the dumbbell straight upward.", "Shrug your shoulder at the top of the movement in order to raise the dumbbell even higher.", "Inhale as you lower the dumbbell to the starting position.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/09/Seated-dumbbell-one-arm-shoulder-press.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-dumbbell-one-arm-shoulder-press/"}, {"id": "elevated-pike-press", "name": "Elevated pike press", "name_ko": "Elevated pike press", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Position two inclined benches side by side, shoulder-width apart from each other.", "Place each hand on the low end of each bench and each foot on the inclined end of each bench.", "Raise your hips high by extending your knees. Your torso should be almost upside-down.", "Keeping your legs straight, inhale as you lower your head between the two benches. At the bottom of the movement, your torso should be upside-down.", "Exhale as you push your body back up to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/07/Elevated-pike-press.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/elevated-pike-press/"}, {"id": "pike-press", "name": "Pike press", "name_ko": "Pike press", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Position two flat benches side by side, shoulder-width apart from each other.", "Place each hand on one end of each bench and each foot on the other end of each bench.", "Raise your hips by extending your knees.", "Walk your feet towards your hands until your hips rise up high into the air and your torso almost becomes upside-down.", "Keeping your legs straight, inhale as you lower your head between the benches. At the bottom of the movement, your torso should be upside-down.", "Exhale as you push your body back up to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/07/Pike-press.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/pike-press/"}, {"id": "barbell-front-raise", "name": "Barbell front raise", "name_ko": "프론트 레이즈", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Stand grasping a barbell with an overhand grip, with your hands shoulder-width apart and your elbows extended.", "Keeping your arms straight and your back neutral, exhale as you lift the barbell forward and upward until your arms are a little above horizontal.", "Hold for a count of two.", "Inhale as you lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/06/Barbell-Front-Raise.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-front-raise/"}, {"id": "cable-y-raise", "name": "Cable Y-raise", "name_ko": "Cable Y-raise", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Stand facing between two low cable pulleys, with each hand holding the handle of the cable of the opposite pulley.", "Step back so that the cables are pulled taut. The cables should be crossed in front of your hips.", "Keeping your elbows moderately flexed, exhale as you raise your arms upwards and outwards, forming the letter ‘Y’ with your whole body.", "Inhale as you reverse the motion and lower the cables to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/06/Cable-Y-raise.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-y-raise/"}, {"id": "smith-machine-upright-row", "name": "Smith machine wide-grip upright row", "name_ko": "로우", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Set the Smith machine bar to mid-thigh height.", "Set the safety pins to prevent the bar from dropping below your thighs.", "Stand behind the bar and grasp it with a shoulder-width or wider overhand (pronated) grip.", "Unlatch the bar by rotating it backwards.", "Exhale as you pull the bar up to your lower or middle chest. Do not pull the bar up any higher.", "Hold for a count of two.", "Inhale as you slowly lower the bar back to the starting position.", "Repeat for the prescribed number of repetitions.", "Rotate the bar forward to latch it back on to the rail."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/03/Smith-machine-upright-row.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/smith-machine-upright-row/"}, {"id": "barbell-rear-delt-row", "name": "Barbell rear delt row", "name_ko": "로우", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Stand holding a barbell with a wide overhand (pronated) grip.", "Flex your hips and knees until your torso is horizontal, and allow the barbell to hang straight down.", "Keeping your elbows perpendicular to your torso, exhale as you pull the barbell up toward your chest.", "Hold for a count of two.", "Inhale as you lower the barbell back to starting position in a controlled manner.", "Repeat the barbell rear delt row for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/03/Barbell-rear-delt-row.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-rear-delt-row/"}, {"id": "seated-smith-machine-behind-the-neck-shoulder-press", "name": "Seated Smith machine behind-the-neck shoulder press", "name_ko": "숄더 프레스", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Place a bench under the Smith machine.", "Set the Smith machine bar to the height of your shoulders when you are seated on the bench.", "Set the safety pins to prevent the bar from dropping past your shoulders.", "Sit on the bench with the bar behind your shoulders.", "Grasp the bar with a wide overhand grip and unlatch it by rotating your wrists backward.", "Exhale as you extend your elbows to press the bar upward, keeping your forearms perpendicular to the ground.", "Inhale as you lower the bar behind your neck, stopping when you reach shoulder height.", "Repeat for the prescribed number of repetitions.", "Rotate the bar forward to latch it back on to the rail."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/02/Seated-Smith-machine-behind-the-neck-shoulder-press.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-smith-machine-behind-the-neck-shoulder-press/"}, {"id": "dumbbell-wide-grip-upright-row", "name": "Dumbbell wide-grip upright row", "name_ko": "로우", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Grasp a dumbbell in each hand and stand upright.", "Pronate your wrists so that your palms face your thighs. The dumbbells should be being held at either shoulder width or wider.", "Pull your shoulders back and stick out your chest.", "Exhale as you pull the dumbbells up the front of your body until they reach your lower or middle chest. Do not pull the dumbbells up any higher.", "Hold for a count of two.", "Inhale as you lower the dumbbells to the starting position.", "Repeat for more repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/03/Dumbbell-wide-grip-upright-row-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-wide-grip-upright-row/"}, {"id": "dumbbell-one-arm-lateral-raise", "name": "Dumbbell one-arm lateral raise", "name_ko": "레터럴 레이즈", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Stand holding a dumbbell in one hand.", "Lean forward a little by flexing your hip.", "Externally rotate your shoulder so that your palm faces forward instead of your thigh.", "Keeping your elbow slightly flexed and your shoulder externally rotated, exhale as you raise the dumbbell out to your side until your elbow is shoulder height.", "Hold for a count of two.", "Inhale as you slowly lower the dumbbell to the starting position.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/03/Dumbbell-One-Arm-Lateral-Raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-one-arm-lateral-raise/"}, {"id": "leaning-dumbbell-lateral-raise", "name": "Leaning dumbbell lateral raise", "name_ko": "레터럴 레이즈", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in one hand, grasp a pole, cable machine, or anything stable with your free hand.", "Position both feet under the hand with which you are grasping the pole and lean out to the side holding the dumbbell, allowing the dumbbell to hang straight down.", "Flex your hips slightly so that you are leaning a little forward.", "Keeping your body still and elbow slightly flexed, exhale as you raise the dumbbell out to the side.", "Hold for a count of two.", "Inhale as you lower the dumbbell to the starting position in a controlled manner.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/10/Leaning-dumbbell-lateral-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/leaning-dumbbell-lateral-raise/"}, {"id": "dumbbell-scott-press", "name": "Dumbbell Scott press", "name_ko": "Dumbbell Scott press", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Stand with a dumbbell in each hand.", "Raise the dumbbells to the height of your chin, with your elbows pointing diagonally out to the sides and your pinkie fingers raised higher than your thumbs.", "Exhale as you swing your elbows backward and a little upward as you move your head and torso forward. At the top of the movement, the pinkie sides of your fists should be facing almost directly upward.", "Inhale as you reverse the movement and return to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/09/Dumbbel-Scott-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-scott-press/"}, {"id": "smith-machine-shoulder-press", "name": "Smith machine shoulder press", "name_ko": "숄더 프레스", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Set the Smith machine bar to upper-chest height.", "Secure the Smith machine’s safety pins so that the bar can’t drop and injure you.", "Stand under the bar and grasp it using a pronated (overhand) grip that is a little wider than shoulder width.", "Unlatch the bar from the rail by rotating it.", "Exhale as you press the bar upward until your arms are almost fully extended.", "Inhale as you reverse the motion and lower the bar to your upper chest.", "Repeat for the prescribed number of repetitions.", "Rotate the bar to latch it back onto the rail."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/09/Smith-machine-standing-overhead-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/smith-machine-shoulder-press/"}, {"id": "dumbbell-w-press", "name": "Dumbbell w-press", "name_ko": "Dumbbell w-press", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["With a dumbbell in each hand, stand with your arms in a ‘W’ position.", "Keeping your elbows fixed, exhale as you raise the dumbbells in a circular motion until they nearly touch each other over your head.", "Inhale as you return the dumbbells to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/08/Dumbbell-w-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-w-press/"}, {"id": "seated-elbows-in-alternating-dumbbell-overhead-press", "name": "Seated elbows-in alternating dumbbell overhead press", "name_ko": "오버헤드 프레스", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Sit on a chair or bench and place one dumbbell on each knee.", "Kick the dumbbells up with your knees, one at a time, and position them in front of your shoulders, with your elbows tucked into your body. Your elbows should be directly below your wrists and your palms should be facing each other (i.e. parallel or neutral grip).", "Keeping your body still, exhale as you press one dumbbell upward, over your head, until your arm is almost fully extended.", "Inhale as you lower the dumbbell to the starting position.", "Repeat with your opposite arm.", "Keep alternating the arm that you press overhead."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/04/Seated-elbows-in-alternating-dumbbell-overhead-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-elbows-in-alternating-dumbbell-overhead-press/"}, {"id": "double-cable-front-raise", "name": "Double cable front raise", "name_ko": "프론트 레이즈", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Attach stirrups (handles) to two low cable pulleys.", "Grasp one stirrup in each hand and stand midway between the two pulleys.", "Step forward until the cables are pulled taut and your arms are left a little behind you.", "Keeping your elbows very slightly flexed, exhale as you raise the stirrups forward and upward in a semicircular motion until your arms are a little above horizontal.", "Hold for a count of two.", "Inhale as you lower the stirrups to the starting position in a controlled manner.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/double-cable-front-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/double-cable-front-raise/"}, {"id": "seated-dumbbell-front-raise", "name": "Seated dumbbell front raise", "name_ko": "프론트 레이즈", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in each hand, sit on a chair or bench and allow the dumbbells to hang straight down by your sides.", "Keeping your elbows very slightly flexed, exhale as you raise the dumbbells forward and upward in a semicircular motion until your arms rise a little above horizontal.", "Hold for a count of two.", "Inhale as you lower the dumbbells in a controlled manner to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/Seated-Dumbbell-Front-Raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-dumbbell-front-raise/"}, {"id": "behind-the-neck-barbell-overhead-press", "name": "Seated behind-the-neck barbell shoulder press", "name_ko": "숄더 프레스", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["N/A. The behind-the-neck barbell overhead press is not recommended. Please see Comments and tips."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/behind-the-neck-barbell-overhead-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/behind-the-neck-barbell-overhead-press/"}, {"id": "seated-neutral-grip-dumbbell-overhead-press", "name": "Seated elbows-in dumbbell overhead press", "name_ko": "오버헤드 프레스", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in each hand, sit on a bench or chair and place the dumbbells on your knees.", "Kick the dumbbells up with your knees, one at a time, and position them in front of your shoulders, with your elbows tucked into your body. Your elbows should be directly below your wrists and your palms should be facing each other (i.e. neutral or parallel grip).", "Exhale as you press the dumbbells upward, over your head, until your arms are almost fully extended.", "Inhale as you lower the dumbbells to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/seated-neutral-grip-dumbbell-overhead-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-neutral-grip-dumbbell-overhead-press/"}, {"id": "bent-over-barbell-reverse-raise", "name": "Bent-over barbell reverse raise", "name_ko": "Bent-over barbell reverse raise", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Stand with a loaded barbell behind your feet, on the floor.", "Squat and pick up the barbell so that you are holding it behind your back.", "Flex your hips and knees until either your torso is horizontal or you feel a mild stretch in your hamstrings. The barbell should be resting on your calves.", "Keeping your back and neck neutral and your arms straight, exhale as you raise the barbell upward as far as you can.", "Hold for a count of two.", "Inhale as you slowly lower the barbell toward the starting position, stopping before the barbell touches your calves.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/bent-over-barbell-reverse-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/bent-over-barbell-reverse-raise/"}, {"id": "smith-machine-seated-overhead-press", "name": "Smith machine seated overhead press", "name_ko": "오버헤드 프레스", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Place a chair in the Smith machine, under the bar.", "Set the Smith machine bar at the same height that your head will be after you sit into position.", "Secure the safety pins of the Smith machine so that the bar cannot drop low and hurt you.", "Sit in position, plant your feet flat on the floor, and grasp the bar with a pronated (overhand) grip that is a little wider than shoulder width.", "Rotate the bar to unlatch it from the rail.", "Exhale as you press the bar upward until your arms are almost fully extended.", "Inhale as you lower the bar to your upper chest.", "Repeat for more repetitions.", "Once you have finished, rotate the bar to latch it back onto the rail."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/07/Smith-machine-seated-overhead-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/smith-machine-seated-overhead-press/"}, {"id": "twisting-cable-overhead-press", "name": "Twisting cable overhead press", "name_ko": "오버헤드 프레스", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Attach a stirrup (handle) to a low or waist-high pulley.", "Grasp the stirrup with one hand.", "Spread your legs and squat a little, keeping your torso upright.", "Position the stirrup to the side of your body, with your elbow flexed and tucked in to your side.", "Exhale as you straighten your legs, twist your body, and press the stirrup diagonally upward and away from the pulley.", "Hold for a count of two.", "Inhale as you reverse the motion and return your body and the stirrup to the starting position.", "Repeat for more repetitions.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/07/Cable-twisting-overhead-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/twisting-cable-overhead-press/"}, {"id": "cable-rear-drive", "name": "Cable rear drive", "name_ko": "Cable rear drive", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Attach a single-ended rope to a shoulder-height cable pulley. If you don’t have a single-ended rope, you can just use the end of the cable.", "Grasp the rope and stand perpendicular to the pulley, with your loaded arm away from the pulley.", "Step away from the pulley until the cable is pulled taut and your arm is stretched across your chest.", "Exhale as you pull your elbow out to the side until it points away from the pulley and then extend your elbow. You can do this in one motion or two.", "Hold for a count of two.", "Inhale as you reverse the motion and return the rope to the starting position.", "Repeat for more repetitions.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/07/Cable-Rear-Drive-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-rear-drive/"}, {"id": "seated-alternating-dumbbell-front-raise", "name": "Seated alternating dumbbell front raise", "name_ko": "프론트 레이즈", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in each hand, sit on the edge of a bench.", "Position the dumbbells by your sides.", "Keeping your elbow slightly bent and your back straight, exhale as you raise one dumbbell forward and upward in a semicircular motion until your arm is a little over horizontal.", "Hold for a count of two.", "Inhale as you reverse the motion and lower your arm to the starting position as you raise your opposite arm forward and upward.", "Keep repeating, alternating the arm that you raise."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/07/seated-alternating-dumbbell-front-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-alternating-dumbbell-front-raise/"}, {"id": "cable-one-arm-front-raise", "name": "Cable one-arm front raise", "name_ko": "프론트 레이즈", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Attach a stirrup (handle) to a low cable pulley.", "Grasp the stirrup with one hand and step forward until the cable is pulled taut and your arm is left by your side and a little behind you.", "For balance, stagger your feet. The foot in front should be the one that is opposite to your working arm.", "Keeping your elbow very slightly flexed, exhale as you raise the stirrup forward and upward in a semicircular motion until your arm is above horizontal.", "Hold for a count of two.", "Inhale as you slowly reverse the motion and lower the stirrup to the starting position.", "Repeat for more repetitions.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/06/cable-one-arm-front-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-one-arm-front-raise/"}, {"id": "cable-wide-grip-upright-row", "name": "Cable wide-grip upright row", "name_ko": "로우", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Attach a straight bar to a low cable pulley.", "Grasp the bar using a shoulder-width or wider overhand grip.", "Stand close to the pulley with your body upright, your shoulders pulled back, and your chest pushed out.", "Exhale as you pull the bar up the front of your body until it reaches the level of your lower or middle chest. Do not pull the bar up any higher.", "Hold for a count of two.", "Inhale as you lower the bar to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/03/Cable-Upright-Row-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-wide-grip-upright-row/"}, {"id": "incline-dumbbell-front-raise", "name": "Incline dumbbell front raise", "name_ko": "프론트 레이즈", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Sit on a bench that is inclined at 45 degrees with a dumbbell in each hand.", "Allow the dumbbells to hang straight down by your sides.", "Keeping your elbows slightly flexed, exhale as you raise the dumbbells forward and upward in a semicircular motion until they are way above the height of your shoulders.", "Hold for a count of two.", "Slowly lower the dumbbells to the starting position in a controlled manner.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/03/Incline0Dumbbell-Front-Raise-resized-1.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-dumbbell-front-raise/"}, {"id": "kettlebell-swing", "name": "Kettlebell swing", "name_ko": "Kettlebell swing", "category": "strength", "equipment": "kettlebell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Stand with your legs a little wider than shoulder width apart, with a kettlebell between your feet.", "Hinge at the hips and a little at the knees, grasp the kettlebell with both hands, and lift it a little off the floor by extending your hips. At this point, your back and arms should be straight, your torso should be almost horizontal, your knees should be slightly flexed, and the kettlebell should be hanging straight down in front of you.", "Inhale as you slowly swing the kettlebell backward and up between your legs.", "As the kettlebell starts to swing forward, forcefully extend your hips and knees to swing the kettlebell up in front of you. At the top of the movement, squeeze your glutes.", "As the kettlebell swings back down, hinge at the hips and a little at the knees and guide the kettlebell between your legs.", "Repeat the forward and backward swings for the prescribed number of times."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/03/Kettlebell-Swing-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/kettlebell-swing/"}, {"id": "cable-front-raise", "name": "Cable front raise", "name_ko": "프론트 레이즈", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Attach a straight bar to a low cable pulley.", "Stand with your back close to the cable machine.", "Grasp the bar from between your legs using an overhand shoulder-width grip and stand up straight. The cable should be pulled taut between your legs.", "Keeping your elbows slightly bent,  exhale as you raise the bar in a semicircular motion in front of you until your arms move a little passed horizontal.", "Hold for a count of two.", "Slowly reverse the motion and lower the bar to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/02/Cable-Front-Raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-front-raise/"}, {"id": "plate-front-raise", "name": "Plate front raise", "name_ko": "프론트 레이즈", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Stand up straight, holding a weight plate in front of your thighs with both hands. Your hands should be at the three and nine o’clock positions.", "Keeping your back straight and your elbows slightly bent, exhale as you raise the plate out in front of you in an arcing motion until your arms are parallel with the floor.", "Hold for a count of two.", "Inhale as you lower the plate in a controlled manner to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/12/Plate-Front-Raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/plate-front-raise/"}, {"id": "seated-dumbbell-lateral-raise", "name": "Seated dumbbell lateral raise", "name_ko": "레터럴 레이즈", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Note: This image does not illustrate the safest and most effective way to perform the seated dumbbell lateral raise. Please follow the instructions and video below instead of the image while I have the image redesigned.", "Holding a dumbbell in each hand, sit on the end of a bench or on a chair.", "Keeping your back straight, lean forward a little.", "Let the dumbbells hang down by your sides, with your elbows slightly bent.", "Externally rotate your shoulders a little so that your palms face a little forward instead of your thighs.", "Keeping your elbows slightly bent, exhale as you raise the dumbbells out to the sides until your elbows are shoulder height or slightly higher.", "Hold for a count of two.", "Inhale as you lower the dumbbells to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/12/Seated-Dumbbell-Lateral-Raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-dumbbell-lateral-raise/"}, {"id": "cable-one-arm-lateral-raise", "name": "Cable one-arm lateral raise", "name_ko": "레터럴 레이즈", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Stand sideways in front of a low cable pulley, holding the stirrup in the hand farthest from the machine.", "Place your free hand on your hip for support.", "Bend forward a little at the hips.", "Keeping your elbow slightly bent, exhale as you raise the stirrup away from the pulley until your elbow is shoulder height.", "Hold for a count of two.", "Inhale as you lower the stirrup to the starting position in a controlled manner.", "Repeat for the desired number of repetitions.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/cable-one-arm-lateral-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-one-arm-lateral-raise/"}, {"id": "alternating-dumbbell-front-raise", "name": "Alternating dumbbell front raise", "name_ko": "프론트 레이즈", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Stand holding a dumbbell in each hand, with your elbows slightly bent and the dumbbells resting on the front of your thighs.", "Keeping your elbow slightly bent, exhale as you raise your right arm in front of you until it is at least parallel to the floor.", "Hold for a count of two.", "Inhale as you lower your right arm to the starting position.", "Repeat with your left arm.", "Keep alternating your arms, raising one after the other one has been fully lowered."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Dumbbell-Standing-Alternate-Front-Raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/alternating-dumbbell-front-raise/"}, {"id": "dumbbell-armpit-row", "name": "Dumbbell armpit row", "name_ko": "로우", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Stand holding a pair of dumbbells by your sides, with your palms facing your thighs.", "Exhale as you pull the dumbbells up the sides of your torso towards your armpits, with your elbows pointing out to the sides.", "Hold for a count of two.", "Inhale as you lower the dumbbells to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Dumbbell-armpit-row-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-armpit-row/"}, {"id": "dumbbell-one-arm-overhead-press", "name": "Dumbbell one-arm shoulder press", "name_ko": "숄더 프레스", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Stand holding a dumbbell in one hand, placing your free hand on your waist for support.", "Raise the dumbbell to the side of your shoulder, keeping your elbow pointing directly downward and your palm facing forward.", "Exhale as you press the dumbbell upward.", "At the top of the movement, shrug your shoulder to raise the dumbbell even higher.", "Inhale as you reverse the motions and lower the dumbbell to the starting position.", "Repeat for the desired number of repetitions.", "Repeat with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Dumbbell-One-Arm-Shoulder-Press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-one-arm-overhead-press/"}, {"id": "seated-barbell-shoulder-press", "name": "Seated barbell shoulder press", "name_ko": "숄더 프레스", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Sit up straight on a bench, holding a barbell at chest height with a pronated (overhand) grip. Your hands should be a little wider than shoulder width apart.", "Exhale as you push the barbell straight upward.", "At the top of the movement, shrug your shoulders to raise the barbell even higher.", "Inhale as you reverse the motions and lower the barbell to the starting position in a controlled manner.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/seated-barbell-overhead-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-barbell-shoulder-press/"}, {"id": "barbell-overhead-press", "name": "Barbell shoulder press", "name_ko": "숄더 프레스", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Stand with your feet shoulder-width apart, holding a barbell with a pronated (overhand) grip at upper-chest height.", "Exhale as you push the barbell straight upward.", "At the top of the movement, shrug your shoulders to raise the barbell even higher.", "Inhale as you reverse the motions and lower the barbell to the starting position in a controlled manner.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/barbell-military-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-overhead-press/"}, {"id": "arnold-press", "name": "Arnold press", "name_ko": "아놀드 프레스", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Sit on a chair or bench, preferably one with a back support, with a dumbbell on each knee.", "Kick the dumbbells up one at a time and position them in front of your shoulders, with your palms facing you and your elbows close to your body.", "Exhale as you press the dumbbells upward and rotate your wrists so that your palms face forward at the top of the movement.", "Inhale as you lower the dumbbells and rotate your palms so that they face you again at the bottom of the movement.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Arnold-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/arnold-press/"}, {"id": "barbell-wide-grip-upright-row", "name": "Barbell wide-grip upright row", "name_ko": "로우", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Stand upright holding a barbell with a shoulder-width, overhand (pronated) grip. The bar should be resting on the front of your thighs.", "Pull your shoulders back and stick your chest out.", "Exhale as you pull the bar up towards your chin, making sure to stop when the bar is level with your lower or middle chest. Do not pull the bar any higher.", "Hold for a count of two.", "Inhale as you lower the bar to the starting position.", "Repeat for the recommended number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/05/Barbell-Wide-Grip-Upright-Row-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-wide-grip-upright-row/"}, {"id": "lateral-raise", "name": "Dumbbell lateral raise", "name_ko": "레터럴 레이즈", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Note: The procedure described below is different from the illustration and adheres to the procedure explained in the video.", "Stand holding a dumbbell in each hand, with the dumbbells hanging down by your sides.", "Bend forward a little at the hips.", "Eternally rotate your shoulders so that your thumbs point out diagonally.", "Keeping your elbows slightly bent, exhale as you raise both upper arms out to the sides until your elbows are level with your shoulders.", "Hold for a count of two.", "Inhale as you lower the dumbbells to the starting position.", "Repeat for the recommended number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/05/dumbbell-lateral-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lateral-raise/"}, {"id": "seated-dumbbell-overhead-press", "name": "Seated dumbbell overhead press", "name_ko": "오버헤드 프레스", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["shoulders"], "secondary_muscles": [], "instructions": ["Holding a pair of dumbbells, sit up straight on a bench or chair, preferably one that supports your back.", "Raise the dumbbells one at a time to each side, and hold them at shoulder height, with your palms facing forward.", "Exhale as you press the dumbbells upward and inward until they almost touch over your head.", "At the top of the movement, shrug your shoulders to raise the dumbbells even higher.", "Inhale as you reverse the motions and lower the dumbbells to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/05/Dumbbell-Shoulder-Press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-dumbbell-overhead-press/"}, {"id": "lying-one-arm-cross-body-dumbbell-triceps-extension", "name": "Lying one-arm cross-body dumbbell triceps extension", "name_ko": "Lying one-arm cross-body dumbbell triceps extension", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Using an overhand grip (palm facing away), hold a dumbbell in one hand and lie supine (on your back) on a flat bench.", "Raise the dumbbell towards the ceiling so that you are holding it above your shoulder.", "You may place your free hand under the elbow of your loaded arm for support.", "Keeping your upper arm still, inhale as you slowly bend your elbow to lower the dumbbell to your opposite shoulder. Your elbow should be pointing out to the side.", "Exhale as you straighten your elbow to lift the dumbbell back up to the starting position.", "Repeat for the desired number of repetitions.", "Repeat on the opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/10/Lying-one-arm-cross-body-dumbbell-triceps-extension.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lying-one-arm-cross-body-dumbbell-triceps-extension/"}, {"id": "cross-arm-push-up", "name": "Cross-arm push-up", "name_ko": "푸시업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Get into a high plank or push-up position.", "Rotate your arms so that your fingers are facing each other.", "Keeping your arms internally rotated, cross your hands, allowing one wrist to be in front of the other.", "Keeping your body straight, inhale as you lower your chest towards the floor.", "Exhale as you push your chest back up to the starting position.", "Repeat for the desired number of prescriptions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/10/Cross-arm-push-up.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cross-arm-push-up/"}, {"id": "seated-olympics-triceps-bar-overhead-triceps-extension", "name": "Seated Olympics triceps bar overhead triceps extension", "name_ko": "Seated Olympics triceps bar overhead triceps extension", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Holding a loaded Olympic triceps bar, sit on a bench or chair, preferably with back support.", "Press the Olympic triceps bar overhead.", "Keeping your elbows close to your head and pointing up towards the ceiling, inhale as you lower the Olympic triceps bar behind your head by bending at the elbows.", "Exhale as your reverse the motion to return to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/09/Seated-Olympic-triceps-bar-overhead-triceps-extension.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-olympics-triceps-bar-overhead-triceps-extension/"}, {"id": "two-arm-supinated-dumbbell-curl", "name": "Two-arm supinated dumbbell curl", "name_ko": "Two-arm supinated dumbbell curl", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand holding a dumbbell in each hand using a supinated grip (palms facing front), hanging by your sides.", "Keeping your hands supinated (palms facing front), exhale as you simultaneously curl both dumbbells up to your shoulders. Your palms should be facing your shoulders at the top of the movement.", "Once you’ve fully flexed your elbows, move your elbows slightly forward so that your forearms are vertical.", "Hold for a count of two.", "Inhale as you slowly return to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/07/Two-arm-supinated-dumbbell-curl.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/two-arm-supinated-dumbbell-curl/"}, {"id": "standing-overhead-barbell-triceps-extension", "name": "Standing overhead barbell triceps extension", "name_ko": "Standing overhead barbell triceps extension", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand tall and perform a barbell shoulder press to position the barbell over your head.", "Keeping your elbows in and pointing directly upwards, inhale as you bend your elbows to lower the barbell behind your head.", "Keeping your upper arms stationary, exhale as you straighten your elbows and lift the barbell up as high as possible.", "Hold for a count of two.", "Inhale as you return the barbell back to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/07/Standing-overhead-barbell-triceps-extension.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/standing-overhead-barbell-triceps-extension/"}, {"id": "standing-dumbbell-overhead-triceps-extension", "name": "Standing dumbbell overhead triceps extension", "name_ko": "Standing dumbbell overhead triceps extension", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand tall, holding one end of the dumbbell with both hands.", "Position the dumbbell so that you are holding the dumbbell behind your head, with your elbows bent, pointed forward and upward.", "Keeping your elbows close to your head and pointing upward, exhale as you straighten your elbows to lift the dumbbell up as high as possible.", "Hold for a count of two.", "Inhale as you slowly lower the dumbbell to return to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/07/Standing-dumbbell-overhead-triceps-extension.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/standing-dumbbell-overhead-triceps-extension/"}, {"id": "dumbbell-overhead-carry", "name": "Dumbbell overhead carry", "name_ko": "Dumbbell overhead carry", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand tall, holding a dumbbell in each hand.", "Press up the dumbbells so that they are above the level of your head. Your elbows should be straight and directly above your shoulders.", "Making sure that your elbows are not locked out, breathe normally as you walk in a straight line for the prescribed distance.", "At the end of the walk, lower the dumbbells down to the ground first before turning and walking back to the starting mark.", "Repeat until you have completed the total prescribed distance."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/06/Dumbbell-overhead-carry.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-overhead-carry/"}, {"id": "lying-alternating-cross-body-dumbbell-triceps-extension", "name": "Lying alternating cross-body dumbbell triceps extension", "name_ko": "Lying alternating cross-body dumbbell triceps extension", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Gripping a dumbbell in each hand with a pronated (overhand) grip, lie on your back on a flat bench.", "Raise the dumbbells directly upward, towards the ceiling.", "Keeping your upper arm still, inhale as you bend the right elbow to lower the dumbbell towards the left shoulder. The head of the dumbbell should be nearly touching your left shoulder and your right elbow should remain pointing up towards the ceiling.", "Exhale as you straighten your right elbow to return to the starting position.", "Repeat steps one to two with your left arm.", "Continue alternating between your right and left arm until you have completed the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/06/Lying-alternating-cross-body-dumbbell-triceps-extension.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lying-alternating-cross-body-dumbbell-triceps-extension/"}, {"id": "olympic-triceps-bar-hammer-curl", "name": "Olympic triceps bar hammer curl", "name_ko": "해머 컬", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Using a neutral grip, stand with your arms straight, allowing the weight to hang down in front of your thighs.", "Keeping a neutral grip and your elbows by your sides, exhale as you curl the dumbbells up to your shoulder.", "Hold for a count of two. Squeeze your biceps.", "Inhale as you slowly lower the weight back to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/02/Olympic-triceps-bar-hammer-curl.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/olympic-triceps-bar-hammer-curl/"}, {"id": "one-arm-dumbbell-reverse-curl", "name": "One-arm dumbbell reverse curl", "name_ko": "리버스 컬", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand holding a dumbbell in one hand using an overhand (pronated) grip. You may place your free hand on your waist.", "Keeping your working elbow by your side, exhale as you curl the dumbbell up towards your shoulder until your forearm is nearly vertical.", "Hold for a count of two.", "Inhale as you slowly lower the dumbbell and return to starting position.", "Repeat for the desired number of repetitions.", "Repeat the exercise using your other arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/01/One-Arm-Dumbbell-Reverse-Curl.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/one-arm-dumbbell-reverse-curl/"}, {"id": "dumbbell-squat-to-dumbbell-curl", "name": "Dumbbell squat to dumbbell curl", "name_ko": "스쿼트", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand with your feet shoulder-width apart, holding a dumbbell in each hand by your sides.", "Inhale as you squat down until your thighs are at least parallel to the floor.", "Exhale as you stand back up.", "Curl the dumbbells up to your shoulders immediately after standing back up.", "Reverse the motion to return to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/11/Dumbbell-squat-to-dumbbell-curl.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-squat-to-dumbbell-curl/"}, {"id": "wrist-roller", "name": "Wrist roller", "name_ko": "Wrist roller", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Use an overhand grip to hold the wrist rope in front of you.", "Raise your arms until they are parallel to the floor.", "Keeping the rest of your body still, breathe normally as you rotate one wrist at a time in an upward motion.", "Once the weight has reached the bar, reverse the motion until the weight returns to its starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/11/Wrist-roller.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/wrist-roller/"}, {"id": "dumbbell-hammer-curl-to-dumbbell-reverse-curl", "name": "Dumbbell hammer curl to dumbbell reverse curl", "name_ko": "해머 컬", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Hold a dumbbell in each hand with palms facing in (hammer or neutral grip).", "Keeping your elbows by your sides, exhale as you curl the dumbbells up to your shoulder.", "Once you’ve reached the top of the motion, slowly pronate your forearms (palms facing the floor).", "Keeping your forearms pronated, inhale as you lower the dumbbells and return to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/08/Dumbbell-hammer-curl-to-dumbbell-reverse-curl.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-hammer-curl-to-dumbbell-reverse-curl/"}, {"id": "standing-one-arm-overhead-dumbbell-triceps-extension", "name": "Standing one-arm overhead dumbbell triceps extension", "name_ko": "Standing one-arm overhead dumbbell triceps extension", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand holding a dumbbell in one hand using a neutral grip.", "Lift the dumbbell up over your head and slightly back, with your elbow bent and pointed up towards the ceiling.", "Exhale while pushing the dumbbell upwards until your arm is extended. Keep your elbow close to your head and the dumbbell behind your head.", "Inhale as you lower the dumbbell back to the starting position.", "Repeat for the prescribed number of repetitions.", "Repeat with the opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/07/Standing-one-arm-overhead-dumbbell-triceps-extension.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/standing-one-arm-overhead-dumbbell-triceps-extension/"}, {"id": "incline-ez-bar-triceps-extension", "name": "Incline EZ bar triceps extension", "name_ko": "Incline EZ bar triceps extension", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Holding a loaded EZ bar using an overhand grip, sit on a bench inclined at 45 to 60 degrees.", "Press the EZ bar overhead.", "Keeping your upper arms fixed, inhale as you lower the EZ bar behind your head by bending your elbows.", "Exhale as you straighten your elbows to return to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/07/Incline-EZ-bar-triceps-extension.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-ez-bar-triceps-extension/"}, {"id": "two-arm-dumbbell-curl", "name": "Two-arm dumbbell curl", "name_ko": "Two-arm dumbbell curl", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand holding a dumbbell in each hand, allowing the dumbbells to hang by your sides, with your palms facing in (neutral grip).", "Keeping your back neutral and torso upright, exhale as you curl the dumbbells up to your shoulders. As the dumbbells rise, slightly rotate your forearms so that your palms face your shoulders by the top of the curl.", "Once your elbows are fully flexed, allow your elbow to slightly move forward until your forearms are vertical.", "Hold for a count of two. Squeeze your biceps.", "Inhale as you slowly lower the dumbbells back to the starting position, rotating your palms back to face inwards.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/06/Two-arm-dumbbell-curl.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/two-arm-dumbbell-curl/"}, {"id": "lying-alternating-dumbbell-triceps-extension", "name": "Lying alternating dumbbell triceps extension", "name_ko": "Lying alternating dumbbell triceps extension", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Using a neutral grip (palms facing each other), hold a dumbbell in each hand and lie on your back on a flat bench.", "Raise the dumbbells vertically above your body, towards the ceiling.", "Keeping your upper arm still, inhale as you bend one elbow to lower the dumbbell to the side of your head.", "Exhale as you straighten your elbow and push the dumbbell back to the starting position.", "Repeat with your opposite arm.", "Repeat for the prescribed number of repetitions, alternating between sides."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/05/Lying-alternating-dumbbell-triceps-extension.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lying-alternating-dumbbell-triceps-extension/"}, {"id": "alternating-band-biceps-curl", "name": "Alternating band biceps curl", "name_ko": "바이셉스 컬", "category": "strength", "equipment": "resistance_band", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand upright with the resistance band underneath your feet, and your hands holding the handles with your palms facing forward.", "Keeping your back neutral and torso upright, exhale as you curl one hand up to your shoulder.", "Hold for a count of two. Squeeze your biceps.", "Inhale as you lower your hand back to the starting position.", "Repeat on the opposite arm. Alternate between arms as you perform the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/04/Alternating-band-biceps-curl.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/alternating-band-biceps-curl/"}, {"id": "standing-barbell-concentration-curl", "name": "Standing barbell concentration curl", "name_ko": "컨센트레이션 컬", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand with your feet shoulder-width apart, gripping a barbell in front of you using an underhand grip.", "Straighten your elbows and allow the barbell to hang down in front of your thighs.", "Slightly bend at the hips and knees until your elbows press against your inner thighs.", "Keeping your back neutral, exhale as you curl the barbell up to your shoulders.", "Hold for a count of two. Squeeze your biceps.", "Inhale as you slowly lower the barbell back to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/04/Standing-barbell-concentration-curl.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/standing-barbell-concentration-curl/"}, {"id": "dumbbell-wrist-curl-over-bench", "name": "Dumbbell wrist curl over bench", "name_ko": "리스트 컬", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Grasping a dumbbell in each hand, kneel beside a flat bench and rest your forearms on the bench, with your palms facing upward.", "Let your wrists hang off the edge of the bench.", "Open your hands a little and allow the dumbbells to roll down into your fingertips.", "Exhale as you close your hands and curl the dumbbells upward as much as you can.", "Hold for a count of two.", "Inhale as you reverse the movement, slowly lowering the dumbbells and allowing them to roll back down into your fingertips.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/04/Dumbbell-wrist-curl-over-bench-1.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-wrist-curl-over-bench/"}, {"id": "dumbbell-reverse-wrist-curl-over-bench", "name": "Dumbbell reverse wrist curl over bench", "name_ko": "리스트 컬", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in each hand using an overhand grip, kneel in front of a flat bench and rest your forearms on its surface. Your wrists should hang off the edge of the flat bench.", "Using only your wrists, exhale as you raise the dumbbells as high as possible. Keep the rest of your body still.", "Hold for a count of two.", "Inhale as you lower the dumbbells back to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/04/Dumbbell-reverse-wrist-curl-over-bench-1.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-reverse-wrist-curl-over-bench/"}, {"id": "dumbbell-concentration-curl-on-a-stability-ball", "name": "Dumbbell concentration curl on a stability ball", "name_ko": "컨센트레이션 컬", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Hold a dumbbell in one hand and sit on a stability ball.", "With your arm extended and palm facing the opposite leg, rest your arm against the inside of your thigh. Your elbow should be lower than the top of your thighs.", "Keeping the rest of your body still, exhale as you curl the dumbbell up towards your shoulder.", "Hold for a count of two and squeeze your biceps.", "Inhale as you lower the dumbbell to return to the starting position.", "Repeat for the prescribed number of repetitions.", "Repeat on the opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/03/Dumbbell-concentration-curl-on-a-stability-ball.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-concentration-curl-on-a-stability-ball/"}, {"id": "lying-one-arm-dumbbell-triceps-extension-on-a-stability-ball", "name": "Lying one-arm dumbbell triceps extension on a stability ball", "name_ko": "Lying one-arm dumbbell triceps extension on a stability ball", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Sit on a stability ball with a dumbbell in one hand.", "Roll down until your back is on the ball and your torso is parallel to the floor.", "Raise the dumbbell vertically above your body and hold it using a neutral grip (palm facing the other side).", "Inhale as you bend your elbow and lower the dumbbell to the side of your head.", "Exhale as you straighten your elbow and push the dumbbell back to its original position.", "Repeat for the prescribed number of repetitions.", "Repeat on the opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/03/Lying-one-arm-dumbbell-triceps-extension-on-a-stability-ball.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lying-one-arm-dumbbell-triceps-extension-on-a-stability-ball/"}, {"id": "incline-dumbbell-inner-biceps-curl", "name": "Incline dumbbell inner-biceps curl", "name_ko": "바이셉스 컬", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Hold a dumbbell in each hand and sit on an inclined bench.", "Let your arms hang straight down by your sides, with your palms facing away from the body.", "Keeping your upper arms still, exhale as you slowly curl the dumbbells up towards your shoulders.", "Hold for a count of two and squeeze your biceps.", "Inhale as you slowly lower the dumbbells and return to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/02/Incline-dumbbell-inner-biceps-curl.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-dumbbell-inner-biceps-curl/"}, {"id": "standing-dumbbell-kickback", "name": "Standing dumbbell kickback", "name_ko": "Standing dumbbell kickback", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Hold a dumbbell in your right hand with a neutral grip.", "Hinge at the hips to bend your torso forward until parallel to the floor.", "Tuck your right elbow into the side of your torso. Keep a 90-degree angle at the elbow so that your upper arm is also horizontal.", "Exhale as you extend your right elbow, bringing the dumbbell behind you.", "Hold for a count of two and squeeze your triceps brachii.", "Inhale as you lower the dumbbell back to the starting position.", "Repeat for the prescribed number of repetitions.", "Repeat with your left arm as the working arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/01/Standing-dumbbell-kickback.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/standing-dumbbell-kickback/"}, {"id": "standing-alternating-dumbbell-kickback", "name": "Standing alternating dumbbell kickback", "name_ko": "Standing alternating dumbbell kickback", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Hold a dumbbell in each hand using a neutral grip.", "Slightly bend your knees and hinge at the hips to bring your torso forward until it is parallel to the floor.", "Tuck your elbows into the sides of your torso at a 90-degree angle, with your upper arms parallel to the floor and your forearms perpendicular to your upper arms.", "Keeping your back neutral and upper arms tucked into the sides of your torso, exhale as you bring one dumbbell behind you by straightening your elbow.", "Hold for a count of two and squeeze your triceps brachii.", "Inhale as you lower the dumbbell back to the starting position.", "Repeat using the opposite arm.", "Continue performing the exercise by alternating between your arms until you have completed the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/12/Standing-alternating-dumbbell-kickback.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/standing-alternating-dumbbell-kickback/"}, {"id": "incline-dumbbell-hammer-curl", "name": "Incline dumbbell hammer curl", "name_ko": "해머 컬", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Holding a pair of dumbbells using a hammer (neutral) grip (palms in), sit on an inclined bench.", "Rest your back on the inclined bench and allow your arms to hang down by the sides of your body.", "Keeping a neutral grip and the rest of your body stationary, exhale as you lift the dumbbells up to the sides of your chest by flexing your elbows.", "Hold for a count of two and squeeze your biceps.", "Inhale as you slowly reverse the motion to return the dumbbells to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/10/Incline-Dumbbell-Hammer-Curl.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-dumbbell-hammer-curl/"}, {"id": "seated-two-arm-overhead-dumbbell-triceps-extension", "name": "Seated two-arm overhead dumbbell triceps extension", "name_ko": "Seated two-arm overhead dumbbell triceps extension", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in each hand using a neutral grip, sit on a flat bench and rest one dumbbell on each knee.", "Kick each dumbbell up with your knee, one at a time, and press it up so that your elbow is fully extended. Both dumbbells should be above and slightly behind your head, with your arms straight.", "Engage your core and plant your feet flat on the ground.", "Keeping your elbows close to your head and pointing up towards the ceiling, inhale as you lower the dumbbells behind your head by flexing your elbows.", "Exhale as you raise the dumbbells by extending your elbows, keeping the rest of your body stationary.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/10/Seated-two-arm-overhead-dumbbell-triceps-extension.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-two-arm-overhead-dumbbell-triceps-extension/"}, {"id": "seated-alternating-dumbbell-curl", "name": "Seated alternating dumbbell curl", "name_ko": "Seated alternating dumbbell curl", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in each hand, sit on a bench or chair.", "Allow the dumbbells to hang down by your sides, palms facing in (neutral grip).", "Keeping your torso upright and upper arms by your sides, exhale as you flex one elbow to raise the dumbbell up towards your shoulder. As you raise the dumbbell, supinate your forearm so that, by the end of the movement (or ‘curl’), your palm is facing your shoulder.", "After fully flexing your elbow, you may move your elbow forward a little until your forearm is vertical.", "Hold for a count of two and squeeze your biceps brachii.", "Inhale as you slowly reverse the motion and return the dumbbell to the starting position.", "Repeat the same movement with your opposite arm.", "Repeat for the desired number of repetitions, alternating the arm that you use."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/09/Seated-Alternating-dumbbell-Curl.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-alternating-dumbbell-curl/"}, {"id": "standing-two-arm-dumbbell-kickback", "name": "Standing two-arm dumbbell kickback", "name_ko": "Standing two-arm dumbbell kickback", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in each hand using a neutral grip (palms facing your body), hinge at the hips to bring your torso forward until it is parallel with the floor. Your knees should be slightly bent and your back and neck should be neutral.", "Tuck your elbows into the sides of your torso. Your upper arms should also be parallel with the floor, while your forearms should perpendicular to your upper arms (i.e. there should be a 90-degree angle at the elbow).", "Keeping your upper arms tucked into the sides of your torso, exhale as you extend your elbows, bringing the weights behind you.", "Hold for a count of two and squeeze your triceps brachii.", "Inhale as you slowly lower the dumbbells back to the starting position by flexing your elbows.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/09/Standing-two-arm-dumbbell-kickback.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/standing-two-arm-dumbbell-kickback/"}, {"id": "barbell-reverse-wrist-curl-over-bench", "name": "Barbell reverse wrist curl over bench", "name_ko": "리스트 컬", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Holding a barbell with an overhand grip, kneel on the floor with your elbows and forearms placed on a flat bench in front of you.", "Let your wrists hang off the edge of the flat bench.", "Keeping your forearms flat against the bench, exhale as you extend your wrists to raise the bar.", "Hold for a count of two.", "Inhale as you slowly lower the bar back to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/08/Barbell-reverse-wrist-curl-over-bench.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-reverse-wrist-curl-over-bench/"}, {"id": "machine-triceps-dip", "name": "Machine triceps dip", "name_ko": "딥", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Sit on the triceps dip machine with your back against the pad.", "If possible, position the levers of the machine as close to your body as possible.", "Grasp the levers.", "Keeping your torso upright and elbows close to your body, exhale as you push the levers down until your elbows are fully extended.", "Hold for a count of two.", "Inhale as you return the levers to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/07/Machine-triceps-dip.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/machine-triceps-dip/"}, {"id": "dumbbell-one-arm-reverse-preacher-curl", "name": "Dumbbell one-arm reverse preacher curl", "name_ko": "프리처 컬", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in one hand, sit on the preacher bench with the back of your upper arm flat on the arm rest and your elbow flexed.", "Rotate your wrist so that your palm faces away from you (pronation).", "Keeping your wrist pronated, inhale as you lower the dumbbell until your elbow is almost fully extended.", "Exhale as you bring the dumbbell back up to the starting position by flexing your elbow.", "Hold for a count of two and squeeze your biceps.", "Repeat steps 1 to 3 for the prescribed number of repetitions.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/04/Dumbbell-one-arm-reverse-preacher-curl.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-one-arm-reverse-preacher-curl/"}, {"id": "one-arm-dead-hang", "name": "One-arm dead hang", "name_ko": "One-arm dead hang", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Using an overhand grip, hang from a pull-up bar until your arms and shoulders are fully extended.", "Release one hand so that you are only hanging with one arm.", "Breathe naturally as you hang for the prescribed duration, or, if you’re just starting out, for as long as you are able.", "Repeat the one-arm dead hang with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/03/V1F-One-Handed-Hang-1.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/one-arm-dead-hang/"}, {"id": "bodyweight-triceps-extension", "name": "Bodyweight triceps extension", "name_ko": "Bodyweight triceps extension", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Get on your hands and knees.", "Rest your elbows and palms on the floor, shoulder-width apart.", "Extend your feet backward and straighten your body so that your bodyweight is being supported by your forearms and the fronts of your feet. Your hands should be approximately level with your face.", "Keeping your elbows tucked in to your body and your body straight and rigid, exhale as you push your body up from the floor by extending your elbows.", "Inhale as you slowly lower your elbows down to the floor by reversing the movement.", "Repeat the bodyweight triceps extension for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/04/Bodyweight-triceps-extension.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/bodyweight-triceps-extension/"}, {"id": "barbell-drag-curl", "name": "Barbell drag curl", "name_ko": "Barbell drag curl", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand holding a barbell using a shoulder-width underhand (supinated) grip. Your elbows should be almost fully extended and the barbell should be resting against your thighs.", "Exhale as you flex your elbows and raise the barbell straight up the front of your body, keeping it close to the contours of your torso. To keep the barbell close to your body, you will have to pull your elbows backward. Keep raising the barbell as high as you can without allowing your elbows to travel forward.", "At the top of the movement, hold for a count of two and squeeze your biceps.", "Reverse the movement and lower the barbell back down the front of your body to the starting position, stopping with your elbows almost fully extended.", "Repeat the barbell drag curl for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/03/Barbell-drag-curl.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-drag-curl/"}, {"id": "cable-reverse-preacher-curl", "name": "Cable reverse preacher curl", "name_ko": "프리처 컬", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Position a preacher bench so that it faces a cable machine.", "Grasp the straight bar of the cable machine with an overhand (pronated) grip and sit on the preacher bench.", "Rest your upper arms on the padded surface, in line with your shoulders.", "Exhale as you slowly curl the straight bar up towards your shoulders.", "Hold for a count of two and squeeze your biceps.", "Inhale as you slowly lower the straight bar until your elbows are almost fully extended.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/02/Cable-Reverse-Preacher-Curl.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-reverse-preacher-curl/"}, {"id": "lying-high-cable-curl", "name": "Lying high cable curl", "name_ko": "Lying high cable curl", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Place a bench under a high cable pulley.", "Lie on the bench so that your face is positioned under the straight bar.", "Grasp the bar using a shoulder-width supinated (underhand) grip. The cable should be taut and your arms should be almost fully extended.", "Keeping your upper arms still and your body flat on the bench, exhale as you curl the bar towards your forehead until your elbows are fully flexed.", "Hold for a count of two and squeeze your biceps.", "Inhale as you reverse the movement and return the bar to the starting position, with your arms almost fully extended.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/12/Lying-high-cable-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lying-high-cable-curl/"}, {"id": "cable-reverse-wrist-curl", "name": "Cable reverse wrist curl", "name_ko": "리스트 컬", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Attach a straight bar to a low cable pulley.", "Place a bench next to the pulley and sit facing it.", "Grasp the straight bar using a shoulder-width pronated grip (palms facing downward).", "Place your forearms flat on your thighs, with your wrists extending off the end. The cable should be pulled taut.", "Exhale as you raise the straight bar by extending your wrists.", "Hold for a count of two.", "Inhale as you slowly lower the straight bar to the starting position by flexing your wrists.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/11/Cable-reverse-wrist-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-reverse-wrist-curl/"}, {"id": "close-grip-ez-bar-curl", "name": "Close-grip EZ bar curl", "name_ko": "Close-grip EZ bar curl", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand holding an EZ-curl bar using a close supinated grip (hands closer than shoulder width apart and palms facing upward). Your elbows should be almost fully extended, and the bar should be resting against your thighs.", "Keeping your elbows fixed to your sides, exhale as you curl the EZ-curl bar up toward your shoulders.", "Hold for a count of two and squeeze your biceps.", "Inhale as you lower the EZ-curl bar to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/11/Close-grip-EZ-bar-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/close-grip-ez-bar-curl/"}, {"id": "lying-dumbbell-supination", "name": "Lying dumbbell supination", "name_ko": "Lying dumbbell supination", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Lie on your right side on a bench or on the floor.", "Using a pronated grip (your palm facing downward), grasp with your left hand a dumbbell that’s loaded unilaterally (loaded only on one side). Your thumb should be closest to the loaded side of the dumbbell.", "Flex your elbow 90 degrees, and rest your forearm on your hip or on the side of your waist.", "Keeping your elbow flexed and your forearm locked against your hip or side, exhale as you raise the loaded end of the dumbbell by supinating your wrist (rotating it so that your thumb turns upward).", "Hold for a count of two.", "Inhale as you reverse the movement and return the loaded end of the dumbbell to the starting position.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise while lying on your left side."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/11/Lying-dumbbell-supination-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lying-dumbbell-supination/"}, {"id": "lying-dumbbell-pronation", "name": "Lying dumbbell pronation", "name_ko": "Lying dumbbell pronation", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Lie on your right side on the floor or on a bench with your head resting in your right hand.", "Using a supinated grip (palm facing upward), grasp a unilaterally loaded dumbbell with your left hand, with your pinkie closest to the loaded side of the dumbbell.", "Rest your upper arm on your side and flex your elbow 90 degrees.", "Keeping your upper arm locked against your side and your elbow flexed at 90 degrees, exhale as you raise the loaded end of the dumbbell by pronating your wrist (rotating it so that your thumb turns downward).", "Hold for a count of two.", "Inhale as you reverse the movement and lower the loaded end of the dumbbell back to the starting position.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise on your left side."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/10/Lying-dumbbell-pronation-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lying-dumbbell-pronation/"}, {"id": "dumbbell-preacher-curl-two-arms", "name": "Dumbbell preacher curl", "name_ko": "프리처 컬", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in each hand, sit on the preacher bench.", "With your elbows flexed, place the backs of your upper arms flat on the arm rest.", "Supinate your wrists (i.e. rotate them so that your palms face you).", "Keeping your wrists supinated, inhale as you lower the dumbbells until your elbows are almost fully extended.", "Exhale as you curl the dumbbells back up toward your shoulders.", "At the top of the movement, hold for a count of two and squeeze your biceps brachii.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/10/Dumbbell-preacher-curl-resized-1.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-preacher-curl-two-arms/"}, {"id": "seated-barbell-wrist-curl", "name": "Seated barbell wrist curl", "name_ko": "리스트 컬", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Holding a barbell with both hands using a supinated (underhand) grip, sit on a bench or chair.", "Rest the backs of your forearms on your thighs, with your wrists extending off your knees.", "Open your hands a little and allow the barbell to roll down into your finger tips.", "Exhale as you slowly close your hands, lifting the barbell into your palms, before curling the barbell upward by flexing your wrists.", "Hold for a count of two.", "Inhale as you reverse the movement by extending your wrists, opening your hands, and allowing the barbell to roll down into your finger tips.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/03/Seated-barbell-wrist-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-barbell-wrist-curl/"}, {"id": "machine-preacher-curl", "name": "Machine preacher curl", "name_ko": "프리처 컬", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Sit on the preacher machine.", "Rest the backs of your upper arms on the padded surface, in line with your shoulders.", "Grasp the handles.", "Exhale as you curl the handles up towards your shoulders.", "Hold for a count of two and squeeze your biceps.", "Inhale as you lower the handles until your elbows are almost fully extended.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/03/Machine-preacher-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/machine-preacher-curl/"}, {"id": "lying-cable-skull-crusher", "name": "Lying cable skull crusher", "name_ko": "Lying cable skull crusher", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Position a bench close to a low cable pulley, with the head of the bench nearest to the pulley.", "Lie on your back (supine) on the bench.", "Grasp the bar with a shoulder-width pronated (overhand) grip.", "Press the bar upward until your arms are fully extended and hold the bar over your forehead so that your arms are slightly slanted backwards.", "Keeping your elbows in, inhale as you flex your elbows and lower the bar to your forehead.", "Exhale as you extend your elbows to raise the bar back to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/01/Lying-cable-triceps-extension-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lying-cable-skull-crusher/"}, {"id": "barbell-skull-crusher", "name": "Barbell skull crusher", "name_ko": "Barbell skull crusher", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Lie on your back (supine) on a flat bench.", "Dismount the barbell using a pronated (overhand), shoulder-width grip and hold the barbell over your forehead so that your arms are slightly slanted backwards.", "Keeping your upper arms still, inhale as you lower the barbell toward your forehead in a smooth, semicircular motion by flexing your elbows.", "Exhale as you reverse the movement and push the barbell back up to the starting position by extending your elbows.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/11/Barbell-skull-crusher-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-skull-crusher/"}, {"id": "machine-triceps-extension", "name": "Machine triceps extension", "name_ko": "Machine triceps extension", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Sit on the triceps extension machine.", "Grasp the handles of the machine and place your uppers arms flat on the arm pad, with your elbows lining up with the axis of rotation of the machine.", "Keeping your upper arms flat on the arm pad, exhale as you push the handles down until your elbows are fully extended.", "Inhale as you reverse the movement in a controlled manner until you feel a mild stretch in your triceps.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/11/Machine-triceps-extension-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/machine-triceps-extension/"}, {"id": "lying-cable-curl", "name": "Lying cable curl", "name_ko": "Lying cable curl", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Place a bench in front of a cable machine, with the pulley positioned just above the height of the bench.", "Sit on the bench so that you’re facing the cable machine and grasp the bar using a supinated (underhand), shoulder-width grip.", "Lie supine (on your back) on the bench and slide up the bench until the cable is pulled taut. Your elbows should be by your sides and your arms should be fully extended.", "Keeping your body flat on the bench, exhale as you curl the bar towards your shoulders until your elbows are fully flexed.", "Once your elbows are fully flexed, allow them to move up a little (shoulder flexion), just until your forearms are horizontal with the floor.", "Hold for a count of two and squeeze your biceps.", "Inhale as you lower the bar to the starting position, with your elbows by your sides and your arms fully extended.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/09/Lying-cable-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lying-cable-curl/"}, {"id": "behind-the-back-cable-wrist-curl", "name": "Behind-the-back cable wrist curl", "name_ko": "리스트 컬", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Attached a straight bar to a low cable pulley.", "Pick the bar up, stand close to but facing away from the pulley, and grasp the bar behind your back using a shoulder-width pronated (overhand) grip. The cable should be pulled taut.", "Open your hands a little and allow the bar to drop from inside your palms to into your fingers.", "Keeping your arms straight and still, exhale as you raise the bar by first clenching your fists so that the bar is raised into your palms and then flexing your wrists.", "Hold for a count of two.", "Inhale as you slowly reverse the movement and return the bar to the starting position, with the bar resting in your fingers.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/09/Behind-the-back-cable-wrist-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/behind-the-back-cable-wrist-curl/"}, {"id": "ez-bar-reverse-preacher-curl", "name": "EZ bar reverse preacher curl", "name_ko": "프리처 컬", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Load an EZ curl bar and place it on the preacher bench.", "Sit on the preacher bench and rest the backs of your upper arms on the padded surface.", "Grasp the EZ curl bar with a shoulder-width pronated (overhand) grip.", "Keeping your elbows in and upper arms flat on the padded surface, exhale as you curl the EZ curl bar up to your shoulders.", "Hold for a count of two and squeeze your biceps.", "Inhale as you lower the EZ curl bar until your elbows are almost fully extended.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/08/EZ-bar-reverse-preacher-curl-2-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/ez-bar-reverse-preacher-curl/"}, {"id": "barbell-preacher-curl", "name": "Barbell preacher curl", "name_ko": "프리처 컬", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Position a loaded barbell on the rest of a preacher bench.", "Sit on the preacher bench and lift the barbell off the rest using a shoulder-width underhand (supinated) grip.", "Rest the backs of your upper arms on the padded surface, with your elbows fully extended.", "Exhale as you curl the barbell upwards, towards your shoulders.", "Hold for a count of two and squeeze your biceps.", "Inhale as you lower the barbell until your elbows are fully extended.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/07/barbell-preacher-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-preacher-curl/"}, {"id": "decline-ez-bar-skull-crusher", "name": "Decline EZ bar skull crusher", "name_ko": "Decline EZ bar skull crusher", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Position a loaded EZ bar by the head of a declined bench.", "Hook your feet firmly under the foot pads of the bench and lie supine (on your back).", "Grasp the EZ bar using a close pronated grip (palms facing away from you) and press it up over your chest until your arms are straight.", "Allow your arms to tilt backwards a little. (Note: This is not expressed in the illustration, in which the arms are kept vertical.)", "Keeping your upper arms fixed, inhale as you flex your elbows and carefully lower the EZ bar toward your face in a circular motion.", "Exhale as you extend your elbows and return the EZ bar to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/06/decline-ez-bar-skull-crusher-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/decline-ez-bar-skull-crusher/"}, {"id": "supine-dumbbell-curl", "name": "Supine dumbbell curl", "name_ko": "Supine dumbbell curl", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Grasp a dumbbell in each hand using a neutral grip (palms facing inward).", "Lie supine (on your back) on a flat bench and allow your arms to hang down behind you until you feel a mild stretch in your shoulders.", "Exhale as you raise the dumbbells and simultaneously supinate your wrists until your elbows are by your sides, your forearms are vertical and your palms are facing upward.", "Hold for a count of two and squeeze your biceps brachii.", "Inhale as you reverse the movement and return the dumbbells to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/05/Supine-dumbbell-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/supine-dumbbell-curl/"}, {"id": "standing-overhead-one-arm-cable-triceps-extension", "name": "Standing overhead one-arm cable triceps extension", "name_ko": "Standing overhead one-arm cable triceps extension", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Attach a stirrup (handle) to a cable pulley that is a little lower than chest high.", "Grasp the stirrup with one hand and press it up, over your head.", "Turn away from the pulley, lean a little forward, stagger your feet for balance, and lower your hand behind your back.", "Your elbow should be raised high, the cable should be pulled taut, and you should be feeling a stretch in your triceps brachii.", "Keeping your elbow close to your head, exhale as you raise the stirrup over your head by extending your elbow.", "Inhale as you flex your elbow to lower the stirrup towards the starting position until you feel a mild stretch in your triceps brachii.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/04/Standing-overhead-one-arm-cable-triceps-extension-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/standing-overhead-one-arm-cable-triceps-extension/"}, {"id": "incline-dumbbell-triceps-extension", "name": "Incline dumbbell triceps extension", "name_ko": "Incline dumbbell triceps extension", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in each hand, sit on a bench inclined at 45 to 60 degrees.", "Raise the dumbbells vertically and hold them using a neutral grip (palms facing each other).", "Keeping your upper arms fixed, inhale as you lower the dumbbells behind your head by flexing your elbows.", "Exhale as you push the dumbbells back up to the starting position by extending your elbows.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/02/Incline-dumbbell-triceps-extension-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-dumbbell-triceps-extension/"}, {"id": "side-lying-biceps-bodyweight-curl", "name": "Side-lying biceps bodyweight curl", "name_ko": "Side-lying biceps bodyweight curl", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Lie on your left side with your hips and knees flexed, and with a cushion under your elbow.", "With your left hand, grasp your left thigh under the knee.", "Place your right hand behind your head.", "Exhale as you raise your torso by flexing both your elbow and your waist.", "Hold for a count of two and squeeze your biceps brachii.", "Inhale as you lower your torso to the starting position.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise with your right arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/01/side-lying-biceps-bodyweight-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/side-lying-biceps-bodyweight-curl/"}, {"id": "kneeling-bodyweight-triceps-extension", "name": "Kneeling bodyweight triceps extension", "name_ko": "Kneeling bodyweight triceps extension", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Get on your hands and knees, with hands shoulder-width apart.", "Lower your elbows to the floor, shoulder-width apart.", "Lean forward so that your bodyweight is supported by your elbows.", "Exhale as you push your body off the floor by extending your elbows.", "Inhale as you lower your elbows to the starting position by flexing your elbows.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/01/kneeling-bodyweight-triceps-extension-resized-2.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/kneeling-bodyweight-triceps-extension/"}, {"id": "biceps-leg-curl", "name": "Biceps leg curl", "name_ko": "레그 컬", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Sit on the edge of a chair so that only your buttocks rest on the seat. Your knees should be bent.", "With your right hand, grasp your left leg from under the knee.", "Keeping your left leg completely relaxed, exhale as you lift it off the floor with your arm by flexing your elbow.", "Hold for a count of two and squeeze your biceps.", "Inhale as you lower your leg to the starting position.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise with your left arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/12/Biceps-leg-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/biceps-leg-curl/"}, {"id": "dumbbell-one-arm-reverse-wrist-curl", "name": "Dumbbell one-arm reverse wrist curl", "name_ko": "리스트 컬", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in one hand, kneel by the side of a flat bench.", "Turn your palm downward (pronate your wrist) and place your forearm flat on the bench, with your wrist and the dumbbell extending off the edge.", "Exhale as you raise the dumbbell by extending your wrist.", "Hold for a count of two.", "Inhale as you slowly lower the dumbbell to the starting position by flexing your wrist.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/12/Dumbbell-one-arm-reverse-wrist-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-one-arm-reverse-wrist-curl/"}, {"id": "ez-bar-reverse-curl", "name": "EZ bar reverse curl", "name_ko": "리버스 컬", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand holding an EZ curl bar using a shoulder-width pronated (overhand) grip. Your knees should be slightly flexed, your arms should be almost fully extended, and the bar should be resting against your thighs.", "Keeping your elbows against your sides, exhale as you flex your elbows and raise the EZ curl bar towards your shoulders until your forearms are vertical.", "Hold for a count of two and squeeze your biceps.", "Inhale as you lower the EZ curl bar to the starting position in a controlled manner.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/09/EZ-bar-reverse-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/ez-bar-reverse-curl/"}, {"id": "cable-curl", "name": "Cable curl", "name_ko": "Cable curl", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Attach a bar to a low cable pulley.", "Grasp the bar using a shoulder-width supinated (underhand) grip.", "Stand approximately one foot away from the pulley and lean backward a little. Your elbows should be by your sides, your arms should be almost fully extended, and the cable should be pulled taut.", "Keeping your body still, exhale as you curl the bar towards your shoulders until your elbows are fully flexed.", "Once your elbows are fully flexed, allow them to move forward a little (shoulder flexion), just until your forearms are vertical.", "Hold for a count of two and squeeze your biceps.", "Inhale as you lower the bar to the starting position, with your elbows by your sides and arms almost fully extended.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/Cable-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-curl/"}, {"id": "lying-barbell-triceps-extension", "name": "Lying barbell triceps extension", "name_ko": "Lying barbell triceps extension", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Grasp a loaded barbell using a shoulder-width, pronated (overhand) grip.", "Lie supine (on your back) on a flat bench.", "Press the barbell upward until your arms are fully extended and hold it over your forehead.", "Inhale as you flex your elbows and shoulders to lower the barbell behind your head.", "Exhale as you extend your elbows and shoulders to raise the barbell back to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/lying-barbell-triceps-extension-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lying-barbell-triceps-extension/"}, {"id": "behind-the-back-smith-machine-wrist-curl", "name": "Behind-the-back Smith machine wrist curl", "name_ko": "리스트 컬", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Position the Smith machine bar so that it rests at approximately knee or thigh height.", "With your back to the bar, bend down and grasp the bar using a shoulder-width pronated (overhand) grip.", "Unlatch the bar from the rail by rotating it and stand up straight.", "Open your hands a little and allow the bar to drop from inside your palms to into your fingers.", "Exhale as you raise the bar by first clenching your fists so that the bar is raised into your palms and then flexing your wrists.", "Hold for a count of two.", "Inhale as you slowly reverse the motion and return the bar to the starting position, with the bar resting in your fingers.", "Repeat for the prescribed number of repetitions.", "When you have finished, latch the bar back onto the rail by rotating it."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/smith-machine-behind-the-back-wrist-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/behind-the-back-smith-machine-wrist-curl/"}, {"id": "cable-preacher-curl", "name": "Cable preacher curl", "name_ko": "프리처 컬", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Position a preacher bench in front of low cable pulley.", "Attach a wavy or straight bar to the pulley.", "Grasp the bar using a shoulder-width supinated (underhand) grip.", "Sit on the preacher bench and rest your arms on the padded surface. Your arms should be fully extended and the cable should be pulled taut.", "Keeping the backs of your upper arms flat on the padded surface, exhale as you curl the bar towards your shoulders.", "Hold for a count of two and squeeze your biceps.", "Inhale as you lower the bar until your arms are fully extended.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/Cable-Preacher-Curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-preacher-curl/"}, {"id": "dumbbell-reverse-curl", "name": "Dumbbell reverse curl", "name_ko": "리버스 컬", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand with a dumbbell in each hand.", "Pronate your wrists into a shoulder-width reverse (overhand) grip.", "Keeping your elbows by your sides, exhale as you curl the dumbbells toward your shoulders until your forearms are nearly vertical.", "Hold for a count of two and squeeze your biceps.", "Inhale as you return the dumbbells to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/reverse-grip-dumbbell-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-reverse-curl/"}, {"id": "seated-dumbbell-overhead-triceps-extension", "name": "Seated dumbbell overhead triceps extension", "name_ko": "Seated dumbbell overhead triceps extension", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Holding a dumbbell, sit on a flat bench or chair and rest the dumbbell on its side on one knee.", "Grasp the base of the bar of the dumbbell with both hands, one hand over the other.", "Kick the dumbbell up with your knee and rest the other end of the dumbbell on your shoulder.", "Adjust your grip so that your hands make a heart shape under the plate.", "Lift the dumbbell around your shoulder and hold it behind your back, with your upper arms vertical and elbows flexed.", "Keeping your elbows close to your head and your upper arms vertical, exhale as you raise the dumbbell by extending your elbows.", "Inhale as you lower the dumbbell to the starting position by flexing your elbows.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/seated-dumbbell-overhead-triceps-extension-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-dumbbell-overhead-triceps-extension/"}, {"id": "standing-dumbbell-preacher-curl", "name": "Standing dumbbell preacher curl", "name_ko": "프리처 컬", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["With a dumbbell in one hand, stand behind a steeply inclined bench.", "Supinate your loaded arm (rotate your palm so that it faces upward) and rest your arm on the surface of the bench, with your elbow almost fully extended.", "Keeping your arm supinated, exhale as you curl the dumbbell to your shoulder.", "Hold for a count of two and squeeze your biceps.", "Inhale as you lower the dumbbell until your arm is almost fully extended.", "Repeat for the desired number of repetitions.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/07/standing-dumbbell-preacher-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/standing-dumbbell-preacher-curl/"}, {"id": "incline-cable-triceps-extension", "name": "Incline cable triceps extension", "name_ko": "Incline cable triceps extension", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Place an inclined bench in front of a low cable pulley. The bench should be inclined at 45 to 60 degrees.", "Sit on the bench and grasp the cable bar from behind you. Hold it behind your head using a narrow pronated (overhand) grip. Your elbows should be raised high.", "Keeping your upper arms fixed and your elbows close to your head, exhale as you extend your elbows and raise the bar over your head in a semicircular motion.", "Inhale as you reverse the motion and lower the bar back behind your head.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/07/incline-overhead-cable-triceps-extension-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-cable-triceps-extension/"}, {"id": "one-arm-overhead-cable-curl", "name": "One-arm overhead cable curl", "name_ko": "One-arm overhead cable curl", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Attach a stirrup (handle) to a shoulder-high cable pulley.", "Grasp the stirrup with one hand and step backward until the cable is pulled taut.", "Stand with your loaded side to the pulley, with your arm horizontal, and your palm facing upward (supinated).", "Keeping your upper arm horizontal, exhale as you flex your elbow and curl the stirrup toward your shoulder.", "Hold for a count of two and squeeze your biceps brachii.", "Inhale as you extend your elbow and return the stirrup to the starting position.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/07/overhead-cable-biceps-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/one-arm-overhead-cable-curl/"}, {"id": "seated-dumbbell-wrist-curl", "name": "Seated dumbbell wrist curl", "name_ko": "리스트 컬", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in each hand, sit on a bench or chair.", "Rest the backs of your forearms on your thighs, with your wrists extending off your knees. Your palms should be facing upward.", "Open your hands a little and allow the dumbbells to roll toward your fingers.", "Exhale as you slowly close your hands and curl the dumbbells upward by flexing your wrists.", "Hold for a count of two.", "Inhale as you lower the dumbbells to the starting position and open your hands a little to allow the dumbbells to once again roll towards your fingers.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/06/seated-dumbbell-wrist-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-dumbbell-wrist-curl/"}, {"id": "cable-triceps-kickback", "name": "Cable triceps kickback", "name_ko": "Cable triceps kickback", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Set up a hip-high cable pulley.", "Remove the stirrup/handle or bar so that there is no attachment.", "Grasp the clip at the end of the cable and step back until the cable is pulled taut.", "Lean forward a little and raise your upper arm so that it is parallel with the floor.", "Keeping your upper arm fixed, exhale as you extend your elbow until it is fully extended.", "Hold for a count of two.", "Inhale as you flex your elbow and return the cable to the starting position.", "Repeat for more repetitions.", "Repeat the repetitions with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/06/Cable-triceps-kickback-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-triceps-kickback/"}, {"id": "overhead-ez-bar-triceps-extension", "name": "Seated overhead EZ bar triceps extension", "name_ko": "Seated overhead EZ bar triceps extension", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Holding a loaded EZ bar using a narrow pronated (overhand) grip, sit on a bench or a chair that supports your back.", "Press the EZ bar over your head.", "Keeping your upper arms fixed and your elbows close to your head, inhale as you flex your elbows and lower the EZ bar behind your head in a semicircular motion.", "Exhale as you reverse the motion and push the EZ bar back over your head.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/06/ez-bar-overhead-triceps-extension.jpg", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/overhead-ez-bar-triceps-extension/"}, {"id": "decline-dumbbell-triceps-extension", "name": "Decline dumbbell triceps extension", "name_ko": "Decline dumbbell triceps extension", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in each hand, lie on your back (supine) on a decline bench.", "Hook your feet under the foot pads.", "Raise the dumbbells vertically and hold them using a neutral grip (palms facing each other).", "Keeping your upper arms fixed, inhale as you flex your elbows and lower the dumbbells to the sides of your head in a semicircular motion.", "Exhale as you extend your elbows and push the dumbbells back up to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/06/Decline-Dumbbell-Triceps-Extension-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/decline-dumbbell-triceps-extension/"}, {"id": "behind-the-back-barbell-wrist-curl", "name": "Behind-the-back barbell wrist curl", "name_ko": "리스트 컬", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Set a loaded barbell on a squat rack at glute height.", "Stand with your back to the rack and grasp the barbell using a shoulder-width pronated (overhand) grip.", "Dismount the barbell and take a few steps forward.", "Allow the barbell to roll down a little into your fingers.", "To get the barbell to Step 3, you could also just lift the barbell from the floor (could be tricky for some people) or ask a training partner to hand it to you from behind.", "Keeping your elbows slightly bent, exhale as you slowly raise the barbell by first clenching your fists so that the barbell is raised into the palms of your hands and then flexing your wrists.", "Hold for a count of two.", "Inhale as you slowly lower the barbell to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/04/Barbell-behind-the-back-wrist-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/behind-the-back-barbell-wrist-curl/"}, {"id": "dumbbell-reverse-preacher-curl", "name": "Dumbbell reverse preacher curl", "name_ko": "프리처 컬", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Sit on the preacher bench with a dumbbell in each hand.", "With your elbows flexed, place the backs of your upper arms flat on the arm rest.", "Pronate your wrists (rotate them so that your palms face away from you).", "Keeping your wrists pronated, inhale as you lower the dumbbells until your elbows are almost fully extended.", "Exhale as you curl the dumbbells back up toward your shoulders.", "At the top of the movement, hold for a count of two and squeeze your biceps.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/03/Dumbbell-Preacher-Reverse-Curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-reverse-preacher-curl/"}, {"id": "prone-incline-barbell-curl", "name": "Prone incline barbell curl", "name_ko": "Prone incline barbell curl", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Lie prone (face down) on an inclined bench. You can kneel on the seat or lower the seat to produce a ramp-like flat surface to lean against.", "Get a training partner to hand you a loaded barbell. You can also dismount the barbell from a low rack.", "Hold the barbell using a shoulder-width supinated (underhand) grip, and allow the barbell to hang downward.", "Keeping your upper arms fixed, exhale as you curl the barbell upward until your elbows are fully flexed.", "Hold for a count of two and squeeze your biceps.", "Inhale as you lower the barbell to the starting position in a controlled manner.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/02/prone-incline-barbell-curl-resized-1.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/prone-incline-barbell-curl/"}, {"id": "incline-dumbbell-curl", "name": "Incline dumbbell curl", "name_ko": "Incline dumbbell curl", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Holding a pair of dumbbells, sit on a bench that is inclined at 45 to 60 degrees.", "Allow your arms to hang straight down by your sides, with your palms facing inward (neutral grip).", "Keeping your upper arms still, exhale as you slowly curl one dumbbell up towards your shoulder. As the dumbbell rises, gradually supinate your forearm (rotate it outward) so that your palm faces your shoulder by the top of the movement.", "Hold for a count of two and squeeze your biceps.", "Inhale as you slowly reverse the motion and return the dumbbell to the starting position.", "Repeat the movement with your opposite arm.", "Alternate arms."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/01/Incline-Dumbbell-Curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-dumbbell-curl/"}, {"id": "dumbbell-hammer-preacher-curl", "name": "Dumbbell hammer preacher curl", "name_ko": "프리처 컬", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Holding a pair of dumbbells, sit on the preacher bench.", "Keeping your elbows flexed and your palms facing each other (neutral or hammer grip), place the backs of your upper arms flat on the arm rest.", "Inhale as you lower the dumbbells until your elbows are almost fully extended.", "Exhale as you curl the dumbbells back up toward your shoulders.", "Hold for a count of two at the top of the movement and squeeze your biceps.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/01/Dumbbell-Peacher-Hammer-Curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-hammer-preacher-curl/"}, {"id": "cable-one-arm-reverse-grip-triceps-push-down", "name": "Cable one-arm reverse-grip triceps push-down", "name_ko": "Cable one-arm reverse-grip triceps push-down", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand under a high cable pulley.", "Grasp the stirrup using a reverse (underhand) grip.", "Tuck your elbow into your side.", "Keeping your elbow fixed against your side, exhale as you extend your elbow and push the stirrup downward until your arm is almost fully extended.", "Inhale as you flex your elbow and allow the stirrup to rise to the starting position in a controlled manner.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/01/Cable-Standing-One-Arm-underhand-Triceps-Extension-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-one-arm-reverse-grip-triceps-push-down/"}, {"id": "one-arm-bench-dip", "name": "One-arm bench dip", "name_ko": "딥", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Sit on the side of a bench, with your back straight, knees bent, and feet flat on the floor.", "Place both palms on the edge of the bench.", "Slide your buttocks off the bench.", "Raise your left arm and right leg straight out in front of you. Your bodyweight should be being supported by your right arm and left leg, with your knee bent at a 90-degree angle.", "Inhale as you flex your elbow to lower your body until you feel a mild stretch in your shoulder.", "Exhale as you extend your elbow to push your body back up to the starting position.", "Repeat for the desired number of repetitions.", "Repeat the exercise with your left arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/01/one-arm-bench-dip-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/one-arm-bench-dip/"}, {"id": "decline-skull-crusher", "name": "Decline barbell skull crusher", "name_ko": "Decline barbell skull crusher", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Position a loaded barbell by the head of a declined bench.", "Lie supine (on your back) on the bench, making sure to hook your feet firmly under the foot pads.", "Grasp the barbell using a close pronated (overhand) grip, and carefully lift it onto your chest.", "Press the barbell up so that your arms are vertical.", "Allow your arms to tilt backwards a little. (Note: This is not expressed in the illustration, in which the arms are kept vertical.)", "Keeping your upper arms fixed, inhale as you flex your elbows and lower the barbell toward your face in a smooth semicircular motion.", "Exhale as you extend your elbows until the barbell returns to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/12/Decline-Skull-crusher-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/decline-skull-crusher/"}, {"id": "seated-bent-over-two-arm-dumbbell-kickback", "name": "Seated bent-over two-arm dumbbell kickback", "name_ko": "Seated bent-over two-arm dumbbell kickback", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Holding a pair of dumbbells using a neutral or hammer grip (palms facing your body), sit on a bench.", "Keeping your upper arms fixed to your sides, lean forward until your torso is almost horizontal. Your back should be straight.", "Raise your upper arms a little higher until they become horizontal. Your elbows should be bent at 90 degrees.", "Keeping your upper arms horizontal, exhale as you extend the dumbbells behind you until your forearms are horizontal.", "Hold for a count of two.", "Inhale as you slowly lower the dumbbells to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/12/Dumbbell-Seated-Kickback-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-bent-over-two-arm-dumbbell-kickback/"}, {"id": "cable-concentration-triceps-extension", "name": "Cable concentration triceps extension", "name_ko": "Cable concentration triceps extension", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Grasp the stirrup (handle) of a high pulley using a supinated (underhand) grip.", "Kneel under the pulley on the knee that is on the opposite side of your loaded arm.", "Brace your loaded arm against the inside of your thigh.", "Place your free hand on your hip or thigh for support.", "Exhale as you extend the elbow of your loaded arm until it is straight.", "Hold for a count of two and squeeze your triceps.", "Inhale as you flex your elbow back into the starting position.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/12/Cable-Concentration-Triceps-Extension-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-concentration-triceps-extension/"}, {"id": "overhead-cable-curl", "name": "Overhead cable curl", "name_ko": "Overhead cable curl", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand between two overhead pulleys and grasp a stirrup in each hand.", "Raise your arms so that they are parallel to the floor.", "Supinate your forearms (turn your palms upward).", "Keeping your upper arms still, exhale as you flex your elbows and curl the stirrups toward your ears.", "Hold the contracted position and squeeze your biceps.", "Inhale as you return the stirrups to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/overhead-cable-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/overhead-cable-curl/"}, {"id": "weight-plate-reverse-curl", "name": "Weight plate reverse curl", "name_ko": "리버스 컬", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand holding a weight plate by your groin using a pronated (overhand) grip, with your hands at the 11 o’clock and 1 o’clock positions.", "Keeping your body still and your elbows tucked into your sides, exhale as you curl the plate up toward your neck.", "Hold for a count of two and squeeze your biceps.", "Inhale as you lower the plate to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/weight-plate-reverse-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/weight-plate-reverse-curl/"}, {"id": "lying-one-arm-dumbbell-triceps-extension", "name": "Lying one-arm dumbbell triceps extension", "name_ko": "Lying one-arm dumbbell triceps extension", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in one hand, lie supine (on your back) on a flat bench.", "Raise the dumbbell vertically above your body and hold it using a neutral grip (palm facing the other side).", "Place your free hand just under the elbow of your loaded arm for support.", "Keeping your upper arm still, inhale as you flex your elbow and lower the dumbbell to the side of your head in a semicircular motion.", "Exhale as you extend your elbow and push the dumbbell back up to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/lying-one-arm-dumbbell-triceps-extension-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lying-one-arm-dumbbell-triceps-extension/"}, {"id": "dumbbell-reverse-grip-concentration-curl", "name": "Dumbbell reverse-grip concentration curl", "name_ko": "컨센트레이션 컬", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in your left hand, sit on a bench with your legs apart.", "With your left arm almost fully extended, rest your elbow against the inside of your left thigh.", "Pronate your wrist so that your palm faces backward.", "Rest your right arm on your right thigh to support your back.", "Exhale as you curl the dumbbell up towards your shoulder.", "Hold the contracted position and squeeze your biceps for a count of two.", "Inhale as you slowly lower the dumbbell to the starting position.", "Repeat for the desired number of repetitions.", "Repeat with your right arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/dumbbell-reverse-grip-concentration-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-reverse-grip-concentration-curl/"}, {"id": "dumbbell-hammer-curl", "name": "Dumbbell hammer curl", "name_ko": "해머 컬", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand holding a dumbbell in each hand using a neutral (aka hammer) grip (palms facing in).", "Keeping your elbow by your side, exhale as you curl one dumbbell up towards your shoulder until your biceps is fully contracted.", "Hold for a count of two and squeeze your biceps.", "Inhale as you slowly lower the dumbbell to the starting position.", "Repeat with your opposite arm.", "Keep alternating your arms."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/Dumbbell-Hammer-Curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-hammer-curl/"}, {"id": "bench-dip", "name": "Bench dip", "name_ko": "딥", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Position two benches parallel and stand between them.", "Place your hands on the inside edge of one bench and your heels on the other so that your bottom is suspended between the benches.", "Exhale as you bend your elbows and lower your body until either you feel a slight stretch in your shoulders or your elbows make a 90-degree angle.", "Inhale as you extend your elbows and raise your body to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/bench-dip-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/bench-dip/"}, {"id": "ez-bar-curl", "name": "EZ bar curl", "name_ko": "EZ bar curl", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand holding an EZ-curl bar using a shoulder-width supinated grip (palms facing upward). Your elbows should be almost fully extended, and the bar should be resting against your thighs.", "Keeping your upper arms fixed by your sides, exhale as you curl the EZ-curl bar up toward your shoulders.", "At the top of the movement, hold for a count of two and squeeze your biceps.", "Inhale as you lower the EZ-curl bar to the starting position in a controlled manner.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/EZ-Barbell-Curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/ez-bar-curl/"}, {"id": "cross-body-hammer-curl", "name": "Dumbbell cross-body hammer curl", "name_ko": "해머 컬", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand with a dumbbell in each hand, with each dumbbell resting on the front of a thigh.", "Keeping your upper arm fixed, exhale as you curl the left dumbbell upward, across your body, and toward your left shoulder.", "Hold for a count of two and squeeze your biceps.", "Inhale as you reverse the motion and return the dumbbell to the starting position.", "Repeat with your right arm.", "Keep alternating arms."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Dumbbell-cross-body-hammer-curl.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cross-body-hammer-curl/"}, {"id": "one-arm-dumbbell-preacher-curl", "name": "One-arm dumbbell preacher curl", "name_ko": "프리처 컬", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Sit on the preacher bench with a dumbbell in your hand.", "Supinate your forearm (turn your palm upward), bend your elbow so that the dumbbell faces your shoulder, and rest your upper arm flat on the bench.", "Inhale as you lower the dumbbell until your arm is almost fully extended.", "Exhale as you curl the dumbbell to the starting position.", "Repeat for the desired number of repetitions.", "Repeat with your opposite arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Dumbbell-Preacher-Curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/one-arm-dumbbell-preacher-curl/"}, {"id": "overhead-barbell-triceps-extension", "name": "Overhead barbell triceps extension", "name_ko": "Overhead barbell triceps extension", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Sit on a bench or a chair with back support holding a barbell using a narrow pronated (overhand) grip.", "Press the barbell over your head.", "Keeping your elbows close to your head, exhale as you bend your elbows and lower the barbell behind your head in a semicircular motion.", "Inhale as you reverse the motion and push the barbell back overhead.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Barbell-Seated-Overhead-Triceps-Extension-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/overhead-barbell-triceps-extension/"}, {"id": "barbell-reverse-curl", "name": "Barbell reverse curl", "name_ko": "리버스 컬", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand holding a barbell using a shoulder-width pronated (overhand) grip.", "Keeping your elbows by your sides, exhale as you curl the barbell up until your forearms are nearly vertical.", "Inhale as you lower the barbell back to the starting position in a controlled manner.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Barbell-Reverse-Curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-reverse-curl/"}, {"id": "triceps-push-down", "name": "Triceps rope push-down", "name_ko": "Triceps rope push-down", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand under the cable pulley and grasp each end of the rope attachment with a neutral grip (palms facing each other).", "Pull your elbows down to your sides and lean forward a little at the hips, keeping your back straight.", "Exhale as you extend your elbows and push the rope all the way down. As your arms extend, twist your wrists so that your palms face down at the end of the movement.", "Inhale as you reverse the motion and return the rope to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/05/Triceps-Rope-Pushdown-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/triceps-push-down/"}, {"id": "dumbbell-curl", "name": "Dumbbell curl", "name_ko": "Dumbbell curl", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand holding a pair of dumbbells by your sides using a neutral grip (palms facing in).", "Pull your shoulders back.", "Exhale as you slowly curl one dumbbell up towards your shoulder. As the dumbbell rises, supinate your forearm gradually so that your palm faces your shoulder by the top of the curl.", "Once your elbow is fully flexed, allow your elbow to move forward a little (shoulder flexion), just until your forearm is vertical.", "Hold for a count of two and squeeze your biceps.", "Inhale as you slowly reverse the movement at half the speed and return the dumbbell to the starting position.", "Repeat the same action with the opposite arm, and then alternate repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/05/Dumbbell-Alternate-Biceps-Curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-curl/"}, {"id": "triceps-dumbbell-kickback", "name": "Dumbbell kickback", "name_ko": "Dumbbell kickback", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["With a dumbbell in your right hand, kneel over a bench with your left knee, and support your body with your left arm.", "Position your torso and right upper arm parallel to the floor, with your right elbow bent at a 90-degree angle. The dumbbell should be hanging straight down below your elbow.", "Keeping your right upper arm stationary, exhale as you extend your right arm backward until it is straight.", "Hold for a count of two.", "Inhale as you slowly lower the dumbbell back to the starting position.", "Repeat for the prescribed number of repetitions.", "Repeat the repetitions with your left arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/05/Dumbbell-Kickback-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/triceps-dumbbell-kickback/"}, {"id": "barbell-curl", "name": "Barbell curl", "name_ko": "Barbell curl", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Stand up straight holding a barbell using a shoulder-width supinated grip (palms facing upward). Your arms should be almost fully extended, and the barbell should be resting against your thighs.", "Keeping your body still, exhale as you curl the barbell up towards your shoulders until your elbows are fully flexed.", "Once your elbows are fully flexed, allow your elbows to move forward a little (shoulder flexion), just until your forearms are vertical.", "Hold for a count of two and squeeze your biceps.", "Inhale as you slowly lower the barbell to the starting position.", "Repeat for the recommended number of reps."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/05/barbell-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-curl/"}, {"id": "concentration-curl", "name": "Dumbbell concentration curl", "name_ko": "컨센트레이션 컬", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["biceps"], "secondary_muscles": [], "instructions": ["Sit on a bench with your legs apart, with a dumbbell in front of you.", "Pick up the dumbbell with your right hand and rest your right arm against the inside of your right thigh. Your elbow should be lower than the top of your thigh so that your elbow doesn’t pivot, and your right arm should be almost fully extended, with your palm facing away from your right thigh.", "Rest your left arm on your left thigh to support your back.", "Exhale as you curl the dumbbell up towards your shoulder.", "At the top of the movement, hold the contracted position and squeeze your biceps for a count of two.", "Inhale as you lower the dumbbell to the starting position.", "Repeat for the desired number of repetitions.", "Repeat with your left arm."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/05/Dumbbell-Concentration-Curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/concentration-curl/"}, {"id": "sprinter-lunge", "name": "Sprinter lunge", "name_ko": "런지", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand tall with your hands by your sides.", "Inhale as you take a large step (lunge) forward with one leg, lowering your body until the knee of your back leg almost touches the floor.", "At the same time, lean your torso forward and touch the floor in front of you with both hands.", "Exhale as you drive through your front leg to push your body back to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/05/Sprinter-lunge.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/sprinter-lunge/"}, {"id": "pistol-box-squat", "name": "Pistol box squat", "name_ko": "스쿼트", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand on one leg in front of a box or bench. Hover your non-standing leg in front of you.", "Keeping your non-standing leg hovering in front of you, inhale as you slowly squat on your standing leg.", "Stop and hold for a second once your butt touches the box. Do not sit on the box or shift your weight on to the box.", "Exhale as you stand back up.", "Repeat for the prescribed number of repetitions.", "Repeat on the opposite leg."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/08/Pistol-box-squat.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/pistol-box-squat/"}, {"id": "front-kick-to-rear-lunge", "name": "Front kick to rear lunge", "name_ko": "런지", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand with your hands on your hips or clasped together in front of you.", "Keeping your torso upright, inhale as you step one foot back, lowering your back knee until you are almost kneeling.", "Exhale as you kick your back foot to the front as you stand back up.", "Inhale as you return to the rear lunge.", "Repeat for the desired number of repetitions.", "Repeat on the opposite side."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/06/Front-kick-to-rear-lunge.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/front-kick-to-rear-lunge/"}, {"id": "barbell-rollout-from-bench", "name": "Barbell rollout from bench", "name_ko": "Barbell rollout from bench", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Place a loaded barbell at the end of a bench. The bar should be perpendicular to the bench.", "Kneel on the bench and grip the bar of the barbell with an overhand grip. Your hands should be shoulder-width apart.", "Keeping your elbows slightly bent, inhale as you gently roll out as far as you can maintain a neutral back.", "Exhale as you slowly roll back to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/04/Barbell-rollout-from-bench.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-rollout-from-bench/"}, {"id": "high-one-leg-side-plank", "name": "High one-leg side plank", "name_ko": "플랭크", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Sit on your side, supporting your upper body with your hand directly underneath your shoulder.", "Straighten your legs and stack them. Your hip should be resting on the floor and your feet should be together.", "Place your free hand on your hip.", "Exhale as you lift your hip off the floor while lifting your top leg, so that your legs are spread apart.", "Breathe normally as you maintain this position for the desired duration.", "Repeat on the opposite side."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/03/High-one-leg-side-plank.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/high-one-leg-side-plank/"}, {"id": "high-side-plank", "name": "High side plank", "name_ko": "플랭크", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Sit on your side, supporting your upper body with your hand directly underneath your shoulder.", "Straighten your legs and stack them. Your hip should be resting on the floor, and your feet should be together.", "Place your free hand on your hip.", "Exhale as you raise your hip off the floor.", "Breathe normally as you hold the position for the desired duration.", "Repeat with the opposite hand on the floor."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/03/High-side-plank.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/high-side-plank/"}, {"id": "frog-pump", "name": "Frog pump", "name_ko": "Frog pump", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Sit on the floor with your knees bent and the soles of your feet together, allowing your knees to fall sideways toward the ground. This is called the frog position.", "Without moving your legs, lie down with your lower back flat on the ground and your hips tilted upward.", "If you are able, lift your head and tuck your chin towards your chest. If not, rest your head on the ground.", "As you exhale, contract your glutes to lift your buttocks and hips upward.", "Hold for a count of two. Squeeze your glutes.", "Inhale as you slowly lower your buttocks and hips back to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2023/03/Frog-pump.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/frog-pump/"}, {"id": "crunch-with-leg-raise", "name": "Crunch with leg raise", "name_ko": "크런치", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Lie with your back on the floor, with your hands behind your head and your knees bent.", "Place the soles of your feet on the floor and keep your lower back pressed against the floor.", "Keeping your neck neutral, exhale as you flex your waist and hips, bringing your chest and the front of your thighs (quads) closer together.", "Hold for a count of two.", "Inhale as you slowly reverse the motion to return to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/12/Crunch-with-leg-raise.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/crunch-with-leg-raise/"}, {"id": "dumbbell-side-lunge", "name": "Dumbbell side lunge", "name_ko": "런지", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand tall holding a dumbbell in each hand, with your arms by your sides. Alternatively, hold one dumbbell by your chest with both hands, as illustrated in the figure.", "Keeping your back neutral, inhale as you take a large step (lunge) to one side and lower your body by bending at the hip and knee of the stepping leg.", "Exhale as you drive through your heel to push your body up and step back into the starting position.", "Repeat for the prescribed number of repetitions.", "Repeat with your opposite leg."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/11/Dumbbell-side-lunge.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-side-lunge/"}, {"id": "dumbbell-machine-sissy-squat", "name": "Dumbbell machine sissy squat", "name_ko": "스쿼트", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Place your feet under the lower padded bar of the sissy squat bench. Your calves should be against the upper pads.", "Hold a dumbbell against your chest with both arms.", "Keeping your chest high, inhale as you flex your hips and knees to lower your body until the back of your thighs reach the upper pads.", "Exhale as you stand back up to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/10/Dumbbell-machine-sissy-squat.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-machine-sissy-squat/"}, {"id": "rear-lunge", "name": "Rear lunge", "name_ko": "런지", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand with your hands on your hips or by your sides.", "Keeping your torso upright, inhale as you step one leg back, planting your forefoot behind you. At the same time, flex your front knee and hip until you close to a kneeling position.", "Exhale as you reverse the motion to stand back up to the starting position.", "Repeat with your opposite leg.", "Continue to alternate between legs until you have performed the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/09/Rear-lunge.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/rear-lunge/"}, {"id": "dead-bug-with-no-arm-movement", "name": "Dead bug (with no arm movement)", "name_ko": "Dead bug (with no arm movement)", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Lie on your back. Extend your arms, with your hands reaching for the ceiling.", "Bend your hips and knees at a 90-degree angles.", "Press your lower back against the floor.", "Keeping your lower back flat against the floor, exhale as you straighten and lower one leg, stopping just before touching the floor.", "Hold for a count of two.", "Inhale as you reverse the motion and return your leg to the starting position.", "Repeat the movement with your opposite leg.", "Alternate legs until you have performed the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/07/Dead-bug-with-no-arm-movement.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dead-bug-with-no-arm-movement/"}, {"id": "seated-alternating-knee-tuck", "name": "Seated alternating knee tuck", "name_ko": "Seated alternating knee tuck", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Sit on the floor with your legs extended in front of you and your hands on the floor, beside your hips.", "Lean your torso back around 45 degrees and lift both of your feet off the floor.", "Breathe normally as you flex one knee and tuck it into your chest.", "Hold for one count.", "Flex the opposite knee as you extend the tucked knee.", "Repeat until you have completed the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/06/Seated-alternating-knee-tuck.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-alternating-knee-tuck/"}, {"id": "one-leg-v-up", "name": "One-leg V-up", "name_ko": "One-leg V-up", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["On the floor, lie on your back with your legs straight and your arms stretched upwards on both sides of your head.", "Keeping your arms and legs straight, exhale as you raise your torso and one leg so that your hands meet your toes.", "Inhale as you slowly return to the starting position.", "Repeat step one using the opposite leg.", "Continue alternating between legs until you have performed the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/06/One-leg-v-up.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/one-leg-v-up/"}, {"id": "seated-cross-scissor-kick", "name": "Seated cross scissor kick", "name_ko": "Seated cross scissor kick", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Sit on the floor with your legs extended in front of you and your hands on the floor, beside your hips.", "Lean your torso back about 45 degrees and lift both feet off the floor. Use your hands to support your balance.", "Breathing naturally and keeping your knees almost fully extended, kick your legs up and down while alternately crossing them over each other (so that both feet move toward the opposite side).", "Perform for the desired number of repetitions or for the desired duration."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/05/Seated-cross-scissor-kick.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-cross-scissor-kick/"}, {"id": "roman-chair-sit-up", "name": "Roman chair sit-up", "name_ko": "싯업", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Sit on a Roman chair with your legs secured under the padded bars. Make sure to flex your feet.", "Cross your arms over your chest.", "Keeping your neck neutral, inhale as you lean back and lower your torso until your hips are almost fully extended.", "Exhale as you flex your hips to raise your torso back to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/03/Roman-chair-sit-up.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/roman-chair-sit-up/"}, {"id": "suspended-pike", "name": "Suspended pike", "name_ko": "Suspended pike", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Position your body in a crawling position with the suspension trainer behind you.", "Place both your feet inside the straps.", "Get into a push-up position.", "Adjust your hands so that they are shoulder-width apart or slightly wider.", "Keeping your arms and legs straight, exhale as you flex at the hips to raise your buttocks as high as possible and pull your feet as close as you can toward your hands.", "Inhale as you slowly reverse the motion to return to the starting position.", "Repeat for the desired amount of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/01/Suspended-pike.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/suspended-pike/"}, {"id": "dumbbell-goblet-split-squat", "name": "Dumbbell goblet split squat", "name_ko": "스쿼트", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Kneel on the floor and grasp one end of the dumbbell with both palms so that you are holding the dumbbell vertically.", "Hold the dumbbell against your chest.", "Exhale as you drive through your front foot to raise your body up until both your knees are fully extended.", "Inhale as you return to the starting position by slowly lowering your back knee to the floor.", "Repeat for the prescribed number of repetitions.", "Repeat with the opposite leg in front."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/01/Dumbbell-goblet-split-squat.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-goblet-split-squat/"}, {"id": "dumbbell-front-squat", "name": "Dumbbell front squat", "name_ko": "스쿼트", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Hold the dumbbells in front rack position, with one end of the dumbbell resting on your shoulder and the other end pointing forward.", "Place your feet shoulder-width apart and your elbows facing forward.", "Keep your torso upright and your elbows facing forward, and inhale as you squat down until your thighs are parallel to the floor.", "Exhale as you drive through your heels to stand back up and return to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/01/Dumbbell-front-squat.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-front-squat/"}, {"id": "double-kettlebell-front-squat", "name": "Double kettlebell front squat", "name_ko": "스쿼트", "category": "strength", "equipment": "kettlebell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand holding a kettlebell in each hand in front of your shoulders. Keep your elbows facing forward as much as possible.", "Place your feet shoulder-width apart and pointing slightly outward.", "Keep your elbows facing forward as you inhale and squat as low as you can.", "Exhale as you drive through your heels to stand back up to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2022/01/Kettlebell-front-squat.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/double-kettlebell-front-squat/"}, {"id": "suspended-jackknife", "name": "Suspended jackknife", "name_ko": "Suspended jackknife", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Get in a push-up position with your feet inside the straps. Your torso and legs should be straight and rigid.", "Exhale as you flex your knees, hips and waist and draw your knees into your chest.", "Inhale as you extend your knees, hips and waist to return to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/12/Suspended-jackknife.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/suspended-jackknife/"}, {"id": "one-leg-hip-thrust", "name": "One-leg hip thrust", "name_ko": "힙 스러스트", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Sit on the side of a bench.", "Slide your buttocks off the side of the bench so that your back is against the edge of the bench at the level just below your shoulder blades.", "Extend your arms on the bench and raise one foot off the floor.", "Keeping your neck and back neutral, exhale as you extend the hip of your supporting leg until it is fully extended.", "Hold for a count of two and squeeze your glutes.", "Inhale as you slowly flex the hip of your supporting leg to return to the starting position.", "Repeat for the desired number of repetitions.", "Repeat with your opposite leg as the supporting leg."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/11/One-leg-hip-thrust.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/one-leg-hip-thrust/"}, {"id": "dumbbell-sumo-squat-2", "name": "Dumbbell sumo squat (version 2)", "name_ko": "스쿼트", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Holding a dumbbell in each hand, stand with your feet wide apart and pointing diagonally outward at about 30 to 45 degrees.", "Position the dumbbells in front of your thighs, with your arms fully extended.", "Keeping your torso upright and arms fully extended, inhale as you squat down by pushing your hips back and your knees out. Descend until your knees bend to at least 90 degrees.", "Exhale as you stand back up, driving through your heels.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/10/Dumbbell-sumo-squat.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-sumo-squat-2/"}, {"id": "bulgarian-split-squat", "name": "Bulgarian split squat", "name_ko": "스쿼트", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand with your back facing the side of a bench.", "Place the top of one foot on the bench behind you so that you are standing only on one foot.", "Keeping your torso upright, squat down with your supporting leg until the knee of your back leg almost touches the floor.", "Exhale as you drive through your supporting leg to stand back up.", "Repeat for the desired number of repetitions.", "Repeat the Bulgarian split squat with your opposite leg."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/10/Bulgarian-split-squat.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/bulgarian-split-squat/"}, {"id": "dumbbell-split-squat", "name": "Dumbbell split squat", "name_ko": "스쿼트", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Grasp a pair of dumbbells and hold them by your sides.", "Step one foot back far enough so that when you lower your back knee, you are in a half-kneeling position.", "Keeping your arms to your sides and torso upright, inhale as you lower your back knee almost to the ground by bending both knees and flexing your front hip.", "Exhale as you return to the starting position by straightening both knees and extending your front hip.", "Repeat for the prescribed number of repetitions.", "Repeat with the opposite foot in front."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/10/Dumbbell-split-squat.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-split-squat/"}, {"id": "barbell-glute-bridge", "name": "Barbell glute bridge", "name_ko": "글루트 브릿지", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Lie supine (on your back) under a loaded barbell and position the bar so that it is over your hips.", "Grip the barbell to keep it in place and flex both knees to plant both feet flat on the floor.", "Exhale as you raise the barbell off the floor by fully extending your hips.", "At the top of the movement, squeeze your glutes and hold for a count of two.", "Inhale as you slowly lower the barbell back to the floor.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/08/barbell-glute-bridge.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-glute-bridge/"}, {"id": "captains-chair-straight-leg-raise", "name": "Captain’s chair straight leg raise", "name_ko": "Captain’s chair straight leg raise", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Climb into the captain’s chair with your forearms resting flat on the parallel bars and back pressing against the back support.", "Keeping your knees straight and lower back pressed against the back support, exhale as you flex your hips to raise both legs until they are parallel with the floor.", "Hold for a count of two.", "Inhale as you slowly lower your legs back to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/07/Captains-chair-straight-leg-raise.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/captains-chair-straight-leg-raise/"}, {"id": "barbell-split-squat", "name": "Barbell split squat", "name_ko": "스쿼트", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand with a barbell on the back of your shoulders, grasping it at the sides with both hands.", "Step one foot back as if performing a rear lunge. The distance between your front and back feet (step length) should be such that when you lower your back knee, you are in a half-kneeling position.", "Keeping your torso upright, inhale as you lower your back knee almost to the ground by flexing your front hip and both knees.", "Exhale as you return to the standing position by extending your front hip and both knees.", "Repeat for the prescribed number of repetitions.", "Do not forget to perform the exercise with the other leg in front."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/06/Barbell-split-squat.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-split-squat/"}, {"id": "stairmill-climb", "name": "Stairmill climb", "name_ko": "Stairmill climb", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Holding on to the handrails, safely step up onto the stairmill.", "Click on ‘Start’ or select the workout you prefer to start the stairmill.", "Keeping your back neutral and your core engaged, breathe normally as you step up the ‘stairs’. You may either hold on to the handrails for support or let go.", "After you have finished, click ‘Stop’ to stop the stairmill."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/06/Stairmill-climb.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/stairmill-climb/"}, {"id": "hack-squat", "name": "Hack squat", "name_ko": "핵 스쿼트", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["With your feet shoulder-width apart and your toes slightly pointing outward, stand on the hack squat platform with your back against the rest and the shoulder pads on top of your shoulders.", "Unlatch the hack squat machine unit from the rail.", "Keeping your back and head against the rest, inhale as you slowly lower the unit towards the platform by bending your hips and knees until your thighs are at least parallel with the platform.", "Exhale as you push the unit back up and away from the platform by extending your hips and knees, driving through your heels.", "Repeat for the prescribed number of repetitions.", "After you have finished, latch the unit back on to the rail."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/06/Hack-squat.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/hack-squat/"}, {"id": "hip-thrust", "name": "Hip thrust", "name_ko": "힙 스러스트", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Sit on the floor with your upper back against the long side of a bench.", "Bend your knees so that your feet are planted on the floor in front of you. They should be about shoulder-width apart.", "Keeping your back neutral, exhale as you raise your pelvis by fully extending your hips.", "Hold for a count of two.", "Inhale as you lower your pelvis back down to the floor.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/06/Hip-thrust.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/hip-thrust/"}, {"id": "dumbbell-overhead-squat", "name": "Dumbbell overhead squat", "name_ko": "스쿼트", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["With your feet hip-width apart, stand holding a dumbbell in each hand overhead, directly above each shoulder. Your palms should be facing forward and your elbows almost fully extended.", "Keeping your torso neutral and your arms almost fully extended, inhale as you squat down by flexing at the hips and knees.", "Exhale as you return to the starting position by extending your hips and knees.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/04/Dumbbell-overhead-squat.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-overhead-squat/"}, {"id": "hack-machine-one-leg-calf-raise", "name": "Hack machine one-leg calf raise", "name_ko": "카프 레이즈", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand on the hack machine platform with your back against the rest and the shoulder pads on top of your shoulders.", "Adjust the positions of your feet so that only the balls of your feet are on the platform.", "Raise one foot off the platform.", "Unlatch the hack machine from the rail.", "Keeping your knee almost fully extended, exhale as you push the hack machine up and away from the platform by plantarflexing your ankle (pushing your toes downward).", "Hold for a count of two.", "Inhale as you lower the hack machine back down to the starting position by dorsiflexing your ankle (pulling your toes upward) until you feel a mild stretch in your calf.", "Repeat for the prescribed number of repetitions.", "Latch the hack machine back on to the rail and repeat with the opposite leg."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/04/Hack-machine-one-leg-calf-raise.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/hack-machine-one-leg-calf-raise/"}, {"id": "hack-machine-calf-raise", "name": "Hack machine calf raise", "name_ko": "카프 레이즈", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand on the hack machine platform with your back flat against the rest and the shoulder pads on top of your shoulders.", "Adjust your feet so that only the balls of your feet are on the platform. The heels and arches of your feet should be extending off the platform.", "Unlatch the hack machine from the rail.", "Keeping your knees almost fully extended, exhale as you push the hack machine up and away from the platform by plantarflexing your ankles.", "Hold for a count of two.", "Inhale as you slowly lower the hack machine back down to the starting position by dorsiflexing your ankles until you feel a mild stretch in your calves.", "Repeat for the desired number of repetitions.", "After you have finished, latch the hack machine back onto the rail."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/04/Hack-machine-calf-raise.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/hack-machine-calf-raise/"}, {"id": "lying-scissor-kick", "name": "Lying scissor kick", "name_ko": "Lying scissor kick", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Lie on your back (supine) on the floor.", "Place your hands under your buttocks, with your palms flat on the floor.", "Press your lower back against the floor.", "Raise your feet a few inches off the floor.", "Breathing naturally and keeping your knees almost fully extended, kick your legs up and down as you would if you were swimming. As your right leg rises, your left leg should descend; then, as your left leg rises, your right leg should descend."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/03/V1F-Lying-Scissor-Kick.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lying-scissor-kick/"}, {"id": "barbell-overhead-lunges", "name": "Barbell overhead lunges", "name_ko": "런지", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand holding a barbell directly over your head, with your arms almost fully extended.", "Keeping your torso upright, inhale as you lunge forward with one leg and lower your back knee until it almost touches the floor.", "Exhale as you drive back up with your front leg and step back into the starting position.", "Repeat the lunge with the same leg for the prescribed number of repetitions.", "Repeat the exercise with the opposite leg leading the lunge."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/03/Barbell-overhead-lunge.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-overhead-lunges/"}, {"id": "step-up", "name": "Step-up", "name_ko": "Step-up", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand with a box or bench in front of you.", "Exhale as you step up onto the box with your right foot, keeping your torso upright.", "Follow with your left foot, bringing your feet together on the box.", "Inhale as you step down from the box with your right foot.", "Follow with your left foot, bringing your feet together on the floor.", "Repeat until you meet the desired number of repetitions. Make sure to alternate the leg you step up and down with."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/03/Step-up.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/step-up/"}, {"id": "seated-dumbbell-one-leg-calf-raise", "name": "Seated dumbbell one-leg calf raise", "name_ko": "카프 레이즈", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Sit with the front of your right foot placed on top of a block or step in front of you. Hips and knees should be bent at a ninety-degree angle.", "Dip the heel of your right foot as low as it can go.", "Hold a dumbbell vertically on top of your right knee.", "Exhale as you lift your right heel as high as possible, pushing against the dumbbell’s weight.", "Keep your right heel lifted for 2 counts.", "Slowly lower it as you inhale.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise on your left foot."], "image_url": "https://weighttraining.guide/wp-content/uploads/2021/02/Dumbbell-Seated-One-Leg-Calf-Raise.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-dumbbell-one-leg-calf-raise/"}, {"id": "smith-machine-squat", "name": "Smith machine squat", "name_ko": "스쿼트", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Set the safety pins of the Smith machine to a height that would prevent an injury if you were to be unable to lift the Smith machine bar.", "Set the bar of the Smith machine to just under shoulder height.", "Stand under the bar, with the bar running across the back of your shoulders, and grasp it at both sides. Your feet should be shoulder-width apart and pointing slightly out to the sides.", "Rotate the bar to unlatch it from the rails.", "Keeping your torso upright, inhale as you squat down by simultaneously pushing your hips backward and bending your knees forward. Descend until your thighs are at least parallel with the floor.", "Exhale as you stand and push the bar back up to the starting position, driving through your heels.", "Repeat for the prescribed number of repetitions.", "Once finished, rotate the bar to latch it back on to the rails."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/12/Smith-machine-squat-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/smith-machine-squat/"}, {"id": "trap-bar-deadlift", "name": "Trap bar deadlift", "name_ko": "데드리프트", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand inside a loaded trap bar with your feet shoulder-width apart.", "Squat and grasp the handles of the trap bar.", "Take a deep breath.", "Keeping your torso upright and your arms and back straight, exhale as you lift the trap bar into a standing position.", "At the top of the movement, squeeze your glutes and pull your shoulders back.", "Inhale as you return the trap bar to the floor by first pushing your hips backward and then flexing your knees.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/11/Trap-bar-deadlift-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/trap-bar-deadlift/"}, {"id": "assisted-inverse-leg-curl-on-lat-pull-down-machine", "name": "Assisted inverse leg curl on lat pull-down machine", "name_ko": "레그 컬", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Choose the amount of weight you want to use as assistance from the lat pull-down machine.", "Kneel on the seat of the lat pull-down machine, facing away from the machine, and secure your feet under the rollers.", "Grasp the bar of the lat pull-down machine and pull it down to behind your neck.", "Flex your hips a little so that you lean forward a bit.", "Flex your ankles so that your toes point up towards your shins.", "Keeping your hips flexed a little and your ankles flexed, inhale as you allow your body to slowly and carefully fall forward, making sure to control the descent as much as possible with your hamstrings.", "Exhale as you reverse the movement and pull your body back up to the starting position using your hamstrings.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/11/Assisted-inverse-leg-curl-with-lat-pull-down-machine-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/assisted-inverse-leg-curl-on-lat-pull-down-machine/"}, {"id": "machine-seated-hip-abduction", "name": "Machine seated hip abduction", "name_ko": "Machine seated hip abduction", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Sit in the seated hip abduction machine with your legs inside of the pads.", "Pull the side lever to allow your legs to come together.", "Release the side lever to lock your legs into position.", "Lie back and grasp the handles at your sides.", "Exhale as you push against the pads with your knees until your hips are fully abducted.", "Hold for a count of two.", "Inhale as you reverse the movement and return your legs to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/11/Machine-seated-hip-abduction-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/machine-seated-hip-abduction/"}, {"id": "dumbbell-box-squat", "name": "Dumbbell box squat", "name_ko": "스쿼트", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand in front of a box or bench holding a pair of dumbbells by your sides.", "Spread your feet so that they are positioned a little wider than shoulder width (i.e. wider than with a regular dumbbell squat).", "Point your feet and knees out diagonally in the same direction.", "Keeping your torso upright, inhale as you slowly squat by first pushing your hips backward and then your knees outward.", "Stop and hold for one second when your butt touches the box. Do not sit on the box and rock backwards.", "Exhale as you spring back upward without rocking forward.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/10/Dumbbell-box-squat-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-box-squat/"}, {"id": "hanging-leg-raise", "name": "Hanging leg raise", "name_ko": "Hanging leg raise", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Hang from a bar using a shoulder-width pronated (overhand) grip.", "Straighten your lower back so that there is as little of an arch in your lower back as possible.", "Keeping your body still, lower back straight and legs together, exhale as you slowly raise your knees by flexing your hips.", "Hold for a count of two.", "Inhale as you slowly lower your knees to the starting position by extending your hips.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/05/Hanging-leg-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/hanging-leg-raise/"}, {"id": "prone-hack-machine-calf-raise", "name": "Prone hack machine calf raise", "name_ko": "카프 레이즈", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Note: The hack machine calf raise basically involves performing a calf raise in a hack squat machine. There are quite a few different types of hack squat machine. With some machines, in order to perform a calf raise, you’ll have to stand in the machine, facing out (supine); with other machines, you’ll have to stand in the machine, facing in (prone). This description will only cover the prone hack machine calf raise.", "Stand in the hack squat machine, facing in (prone).", "Extend the arches and heels of your feet off the foot platform.", "Straighten your back and hips.", "Unlatch the lever so that the machine can move freely (although this might not be necessary).", "Keeping your knees slightly flexed, exhale as you extend your ankles to raise the hack squat machine as much as possible.", "Hold for a count of two.", "Inhale as you slowly flex your ankles to lower the machine until you feel a mild stretch in your calves.", "Repeat for the prescribed number of repetitions.", "If you unlatched the lever at the start, when you have finished, make sure to relatch the lever."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/03/Prone-hack-machine-calf-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/prone-hack-machine-calf-raise/"}, {"id": "crunch-with-stability-ball-leg-raise", "name": "Crunch with stability ball leg raise", "name_ko": "크런치", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Lie on your back (supine) either on the floor or on a bench.", "Place a stability ball either between your lower legs (beginner) or between your feet (more advanced).", "Raise the ball and your feet a little off the floor.", "To protect your lower back, press it against the floor.", "Cross your hands behind your head.", "Keeping your lower back pressed against the floor, exhale as you flex both your abdomen and hips until you touch your elbows onto your knees.", "Hold for a count of two.", "Inhale as you slowly reverse the motion and lower your back and legs to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/03/Crunch-with-stability-ball-leg-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/crunch-with-stability-ball-leg-raise/"}, {"id": "barbell-step-up", "name": "Barbell step-up", "name_ko": "Barbell step-up", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand facing a box or bench with a barbell on your shoulders. Ideally, the height of the box/bench would be such that when you put your foot on the box/bench, your knee will make a right angle.", "Leading with your right leg and keeping your torso upright, exhale as you slowly step up onto the box/bench.", "Bring your feet together on the box/bench.", "Leading with your right leg, inhale as you slowly step down off the box/bench.", "Bring your feet together on the floor.", "Repeat the process of stepping up and down off the box/bench, making sure to alternate the leg with which you step up and down."], "image_url": "https://weighttraining.guide/wp-content/uploads/2019/03/Barbell-step-up-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-step-up/"}, {"id": "lunge", "name": "Lunge", "name_ko": "런지", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand straight with your hands either by your sides or placed on your hips.", "Keeping your torso upright, inhale as you take a large step forward with one leg and lower the knee of your back leg until it almost touches the floor.", "Exhale as you drive back up with your front leg and step back into a standing position.", "Repeat the lunge with your opposite leg.", "Keep alternating the leg with which you lunge."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/11/Lunge-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lunge/"}, {"id": "inverse-leg-curl-on-lat-pull-down-machine", "name": "Inverse leg curl on lat pull-down machine", "name_ko": "레그 컬", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Place a box or a bench behind the seat of a cable pull-down machine.", "Kneel on the seat of the cable pull-down machine, facing the bench/box, and tightly secure your feet under the rollers.", "For reasons explained below, flex your hips a little and dorsally flex your ankles (i.e. point your toes up towards your shins).", "Cross your arms over your chest or keep them by your sides.", "Inhale as you allow your body to slowly and carefully fall forward, making sure to control the descent as much as possible with your hamstrings.", "Catch your body with your arms and lower your torso to the box/bench as if performing a push-up on your knees.", "Exhale as you push your body back up just enough until your hamstrings can take over and pull your body back up to a vertical position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/11/Inverse-leg-curl-on-lat-pull-down-machine-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/inverse-leg-curl-on-lat-pull-down-machine/"}, {"id": "frog-crunch-with-leg-raise", "name": "Frog crunch with leg raise", "name_ko": "크런치", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Lie supine (on your back) on the floor with your hands behind your head, your knees bent, and the soles of your feet together.", "Raise your feet a little off the floor.", "To protect your lower back, press it against the floor.", "Keeping your hands behind your head and the soles of your feet together, exhale as you simultaneously flex your abdomen and hips until you touch your elbows onto your thighs.", "Hold for a count of two.", "Inhale as you reverse the movement and lower your upper body and legs back to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/11/Frog-crunch-with-leg-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/frog-crunch-with-leg-raise/"}, {"id": "barbell-front-box-squat", "name": "Barbell front box squat", "name_ko": "스쿼트", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand in front of a box or bench with a barbell on the front of your shoulders and your hands crossed over the barbell to keep it stable.", "Spread your feet so that they are positioned a little wider than shoulder width (i.e. wider than with a regular barbell front squat).", "Point your feet and knees out diagonally in the same direction.", "Keeping your torso upright, inhale as you slowly squat by first pushing your hips backward and then your knees outward.", "Stop and hold for one second when your butt touches the box. Do not sit on the box and rock backwards.", "Exhale as your spring back upward without rocking forward.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/09/Barbell-front-box-squat-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-front-box-squat/"}, {"id": "bodyweight-squat", "name": "Bodyweight squat", "name_ko": "스쿼트", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand with your feet shoulder-width apart. Your knees and feet should be pointing in the same direction.", "Raise your arms out in front of you for balance (or you can leave them by your side and raise them as you descend).", "Keeping your head up and torso upright, inhale as you squat by simultaneously flexing your hips and knees, making sure to descend at least until your thighs are parallel with the floor. (If your arms were by your sides, raise them out in front of you as you descend to help you keep balance.)", "Exhale as you return to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/07/Bodyweight-squat-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/bodyweight-squat/"}, {"id": "inverse-leg-curl", "name": "Inverse leg curl", "name_ko": "레그 컬", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Get on your knees and anchor the back of your heels under a bench or a barbell. Ideally, for reasons explained below, in Comments and tips , your feet should be fully dorsally flexed (i.e. your toes should be pointing up to your shins).", "For reasons explained below, flex your hips a little.", "Cross your arms over your chest (or you can keep them by your sides).", "Inhale as you allow your body to slowly fall forward, controlling the descent as much as you can with your hamstrings.", "At the bottom of the movement, catch your body with your arms and lower your torso to the floor as if performing a knee push-up.", "Exhale as you push your torso back up and off the floor just enough until your hamstrings can take over and pull your body back up to a vertical position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/05/inverse-leg-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/inverse-leg-curl/"}, {"id": "stability-ball-leg-curl", "name": "Stability ball leg curl", "name_ko": "레그 컬", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Lie supine (on your back) on the floor with your lower legs on a stability ball.", "Extend your arms out to your sides for balance and support.", "Raise your hips and lower back off the floor so that your body is straight.", "Keeping your hips and back straight, exhale as you flex your knees and roll the ball towards your back with your heels. Your feet should roll onto the top of the ball and your body should lift further off the floor.", "Inhale as you roll the ball back to the starting position by extending your knees.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/05/Stability-ball-leg-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/stability-ball-leg-curl/"}, {"id": "side-plank-hip-abduction", "name": "Side plank hip abduction", "name_ko": "플랭크", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Lie on the floor, on your left side, supporting your body weight on your left elbow, which should be directly under your shoulder.", "Straighten your body and legs. Your feet should be together, and your hip should be resting on the floor.", "Place your free hand on your hip.", "Exhale as you slowly lift your hip off the floor and raise your right leg so that your legs are spread apart.", "Inhale as you slowly bring your feet back together and lower your hip to the floor.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise on your right side."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/01/Side-plank-hip-abduction-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/side-plank-hip-abduction/"}, {"id": "side-plank-hip-adduction", "name": "Side plank hip adduction", "name_ko": "플랭크", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Lie on the floor, on your left side, supporting your bodyweight on your left elbow. Your elbow should be directly under your shoulder.", "Place the inside of your right foot on a bench and lift your hip off the floor a little by pushing your foot down onto the bench.", "Straighten your body and legs. At this point, your bodyweight should be being supported by your left elbow and right foot, and your left foot should be under the bench.", "Exhale as you slowly raise your hip by both pushing the inside of your right foot down onto the bench and laterally flexing your waist.", "Hold for a count of two.", "Inhale as you slowly lower your hip to the starting position.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise on your right side."], "image_url": "https://weighttraining.guide/wp-content/uploads/2018/01/Side-plank-hip-adduction-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/side-plank-hip-adduction/"}, {"id": "lying-single-straight-leg-hip-extension", "name": "Lying single straight-leg hip extension", "name_ko": "Lying single straight-leg hip extension", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Lie supine (on your back) on the floor with your arms and legs straight and heels resting on a bench.", "Spread your arms out to the sides for stability.", "Raise your left heel off the bench.", "Exhale as you raise your hips off the floor by extending your right hip.", "Inhale as you lower your hips to the starting position by flexing your right hip.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise with your left leg."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/12/Lying-single-straight-leg-hip-extension-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lying-single-straight-leg-hip-extension/"}, {"id": "cable-hip-adduction", "name": "Cable hip adduction", "name_ko": "Cable hip adduction", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand with one side next to a low cable pulley.", "Using an ankle strap, attach the cable to the leg nearest to the pulley.", "Step sideways, away from the pulley, until the cable is pulled taut.", "Grasp something for stability.", "Allow your strapped leg to be pulled out to the side so that you are standing only on your far leg.", "Keeping your body and legs straight, exhale as you pull your strapped leg down and in front of your supporting leg.", "Hold for a count of two.", "Inhale as you reverse the motion and return your strapped leg to the starting position.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise with your opposite leg."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/12/Cable-Hip-Adduction-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-hip-adduction/"}, {"id": "smith-machine-bent-knee-good-morning", "name": "Smith machine bent-knee good morning", "name_ko": "굿모닝", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Lock the Smith machine bar at shoulder height.", "Position the safety pins just below waist height to allow for a full range of motion while preventing the bar from falling.", "Get under the bar so that the bar rests on the back of your shoulders and grasp the bar at each side.", "Standing with your feet hip-width apart, rotate the bar to detach it from the rail.", "Keeping your back straight, inhale as you flex your hips and your knees slightly and lower your torso forward until it is parallel with the floor.", "Exhale as you raise your torso by extending your hips and knees until your hips and knees are fully extended.", "Repeat for the prescribed number of repetitions.", "When you have finished, rotate the bar to latch it back onto the rail."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/Smith-machine-bent-knee-good-morning-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/smith-machine-bent-knee-good-morning/"}, {"id": "jump-squat", "name": "Jump squat", "name_ko": "스쿼트", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand with your feet shoulder-width apart and your arms by your sides.", "Keeping your torso upright, inhale as you squat down until your thighs are at least horizontal, and raise your arms horizontally in front of you.", "Exhale as you jump as high as possible, making sure to throw your arms downward as you rise as if to push the floor downward.", "When you land, flex your hips and knees to absorb the impact, and descend into another squat. Don’t forget to inhale.", "Exhale as you jump as high as possible again.", "Keep repeating the squat, then the jump."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/jump-squat-resized-1.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/jump-squat/"}, {"id": "captains-chair-leg-raise", "name": "Captain’s chair leg raise", "name_ko": "Captain’s chair leg raise", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Climb into the captain’s chair. Your forearms should be resting on the pads, your hands should be grasping the handles, your back should be pressing against the back support, and your legs should be hanging straight down.", "Press your lower back (lumbar spine) against the back support.", "Keeping your feet together, exhale as you raise your knees towards your chest by flexing your hips and knees.", "Hold for a count of two.", "Inhale as you lower your feet to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/captains-chair-leg-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/captains-chair-leg-raise/"}, {"id": "weighted-one-leg-hip-thrust", "name": "Weighted one-leg hip thrust", "name_ko": "힙 스러스트", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Holding a weight plate with both hands, sit on the side of a bench and rest the weight plate on your abdomen.", "Carefully slide your buttocks off the side of the bench and rest your back against the edge of the bench at the level just below your shoulder blades.", "Raise one leg off the floor.", "Keeping your torso rigid and both hands on the plate, exhale as you raise the weight plate by extending the hip of your supporting leg.", "Hold for a count of two and squeeze your glute.", "Inhale as you lower the weight plate to the starting position by flexing the hip of your supporting leg.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise with your opposite leg."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/weighted-one-leg-hip-thrust-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/weighted-one-leg-hip-thrust/"}, {"id": "straight-leg-cable-pull-through", "name": "Straight-leg cable pull-through", "name_ko": "Straight-leg cable pull-through", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Grasp the attachment of a low cable pulley. The attachment can be a rope or a stirrup (handle).", "Straddle the cable so that your back faces the pulley.", "Keeping your legs straight, flex your hips and waist until you feel a mild stretch in your hamstrings.", "Step forward until the rope is pulled taut, and stand with your feet shoulder-width apart.", "Keeping your legs and arms straight, exhale as you stand up and pull the cable attachment through your legs.", "Hold for a count of two and squeeze your glutes.", "Inhale as you reverse the motion and return the cable attachment to the starting position, with your hips and waist flexed.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/Straight-leg-cable-pull-through-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/straight-leg-cable-pull-through/"}, {"id": "twisting-hip-extension", "name": "Twisting hip extension", "name_ko": "Twisting hip extension", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand in the hyperextension bench with your thighs resting on the front pad. The pad must be below your hips so that your hips are free to move.", "Cross your hands over your chest, or position them behind your head.", "Keeping your back and neck neutral, inhale as you lower your torso by flexing your hips.", "Exhale as you raise your torso by extending your hips. As you rise, slowly twist your torso to one side.", "Keep flexing and extending your hips, making sure to alternate the side to which you twist your torso as you rise."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/08/Twisting-hip-extension-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/twisting-hip-extension/"}, {"id": "lying-alternating-leg-raise", "name": "Lying alternating straight leg raise", "name_ko": "Lying alternating straight leg raise", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Lie supine (on your back) on a mat or a bench.", "Place your hands under your buttocks to raise and support your pelvis.", "Raise both legs a little off the floor or bench.", "Keeping your legs straight, raise one leg vertically into the air.", "Lower the same leg to the starting position as you simultaneously raise the opposite leg vertically into the air.", "Keep alternating these leg movements, raising one leg as you lower the opposite one.", "Breathe naturally."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/07/lying-alternating-leg-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lying-alternating-leg-raise/"}, {"id": "standing-cable-hip-extension", "name": "Standing cable hip extension", "name_ko": "Standing cable hip extension", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Clip a low cable to one ankle strap.", "Take a step back with your free leg so that the leg attached to the cable is left in front and the cable is pulled taut.", "Grasp the cable pulley for stability.", "Keeping your torso upright and your working leg straight, exhale as you extend your hip and pull the cable back until your hip is fully extended.", "Hold for a count of two and squeeze your glute.", "Inhale as you return your leg to the starting position.", "Repeat for more repetitions.", "Repeat the exercise with your opposite leg."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/07/Cable-standing-hip-extension-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/standing-cable-hip-extension/"}, {"id": "machine-seated-one-leg-calf-raise", "name": "Machine seated one-leg calf raise", "name_ko": "카프 레이즈", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Sit in the calf raise machine, place your thighs under the lever pads, and adjust the pads to support your thighs.", "Place the forefoot of one of your feet on the platform, with your heel extending off.", "Lift the lever a little and release the safety bar, giving the lever freedom to descend.", "Hold the handles for support.", "Inhale as you allow the lever to descend in a controlled manner until you feel a mild stretch in your calf.", "Hold for a count of one.", "Exhale as you press the lever all the way up by raising your heel.", "Hold for a count of two.", "Repeat for more repetitions.", "Repeat the exercise with your opposite leg."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/07/seated-one-leg-calf-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/machine-seated-one-leg-calf-raise/"}, {"id": "weighted-captains-chair-leg-and-hip-raise", "name": "Weighted captain’s chair leg and hip raise", "name_ko": "Weighted captain’s chair leg and hip raise", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Place a dumbbell on its side inside the captain’s chair.", "Get into the captain’s chair with your forearms on the pads, your hands on the handles, and your back against the back pad.", "Press your lower back against the back pad.", "Pinch the dumbbell between the arches of your feet.", "Keeping the dumbbell pinched between your feet, exhale as you raise your knees towards your chest by flexing your knees, hips, and waist.", "Try to hold the end position for a count of two.", "Inhale as you slowly lower the dumbbell to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/07/weighted-captains-chair-leg-and-hip-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/weighted-captains-chair-leg-and-hip-raise/"}, {"id": "barbell-one-leg-hip-thrust", "name": "Barbell one-leg hip thrust", "name_ko": "힙 스러스트", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Position a loaded barbell parallel to a bench.", "Sit on the floor with your hips under the barbell and your back resting against the side of the bench.", "Grasp the bar at each side.", "Flex both knees and place your feet flat on the floor.", "Keeping your torso rigid, exhale as you raise the barbell by extending the hip of one leg until the hip is fully extended.", "Hold for a count of two and squeeze your glute.", "Inhale as you lower the barbell by flexing your hip. Do not allow the barbell to touch the floor.", "Repeat for more repetitions.", "Repeat the repetitions with your opposite leg."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/06/barbell-one-leg-hip-thrust-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-one-leg-hip-thrust/"}, {"id": "dumbbell-one-leg-split-squat", "name": "Dumbbell one-leg split squat", "name_ko": "스쿼트", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Grasp a pair of dumbbells and hold them by your sides.", "Stand with your back facing the side of a bench, leaving a few feet of space between you and the bench.", "Raise one leg backward and place the top of your foot on top of the bench.", "Keeping your torso upright, inhale as you squat down with your supporting leg until either the knee of your supporting leg makes a 90-degree angle or the knee of your back leg nearly touches the floor.", "Exhale as you push yourself back up to the starting position.", "Repeat for more repetitions.", "Repeat the exercise with your opposite leg."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/06/Dumbbell-one-leg-split-squat-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-one-leg-split-squat/"}, {"id": "cable-hip-abduction", "name": "Cable hip abduction", "name_ko": "Cable hip abduction", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Attach an ankle strap to one ankle and hook it up to a low cable pulley.", "Stand perpendicular to the pulley with your strapped ankle farthest away from the pulley.", "Step away from the pulley so that the cable is pulled taut and your strapped leg is pulled across your unstrapped leg.", "Grasp something for stability and place your free hand on your hip.", "Keeping both legs straight, exhale as you pull your strapped ankle away from the pulley until it is fully abducted.", "Hold for a count of two.", "Inhale as you slowly return your strapped leg to the starting position.", "Repeat for more repetitions.", "Repeat with your opposite ankle."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/06/Cable-hip-abduction-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-hip-abduction/"}, {"id": "standing-dumbbell-one-leg-calf-raise", "name": "Standing dumbbell one-leg calf raise", "name_ko": "카프 레이즈", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Hold a dumbbell by your side, in your left hand.", "With your left foot, stand on a platform, with the arch and heel of your foot suspending off.", "Grasp something with your right hand for stability.", "Exhale as you raise your heel by extending your ankle (plantar flexion).", "Hold for a count of two.", "Inhale as you slowly reverse the motion (dorsiflexion) and lower your heel until you feel a mild stretch in your calf.", "Hold for a count of one.", "Repeat for more repetitions.", "Repeat with your right leg."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/06/standing-one-leg-dumbbell-calf-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/standing-dumbbell-one-leg-calf-raise/"}, {"id": "lying-straight-leg-raise", "name": "Lying straight leg raise", "name_ko": "Lying straight leg raise", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Lie supine (on your back) on a bench or on a mat.", "Place your hands under your buttocks to support your pelvis.", "Press your lower back against the bench.", "Raise your feet a little off the bench or mat.", "Keeping your feet together and your legs straight, exhale as you flex your hips and raise your legs until they are vertical.", "Inhale as you lower your legs to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/06/lying-straight-leg-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lying-straight-leg-raise/"}, {"id": "twisting-hyperextension", "name": "Twisting hyperextension", "name_ko": "하이퍼익스텐션", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand in the hyperextension bench with your legs hooked securely under the foot brace and the front padding resting below your hips to allow your hips room to move.", "Position your hands lightly behind your head or cross them over your chest.", "Inhale as you lower your torso by flexing your hips and your waist.", "Exhale as you raise your torso by extending your hips and your waist. As you rise, slowly twist your torso to one side.", "Repeat the lowering and raising of your torso, making sure to alternate the side to which you twist."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/06/twisting-hyperextension-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/twisting-hyperextension/"}, {"id": "smith-machine-kneeling-rear-kick", "name": "Smith machine kneeling rear kick", "name_ko": "Smith machine kneeling rear kick", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Place a bench under the Smith machine bar. (You can also just use a mat. See the second video.)", "Set the safety pins of the Smith machine at a safe height to prevent the bar from crashing down onto your legs.", "Unlatch the bar from the rail by rotating it and bring it down onto the safety pins.", "Leave the bar unlatched from the rail so that it can freely move up and down.", "Get on your hands and knees on the bench and place the arch of one foot under the center of the bar.", "Exhale as you push the bar upward by fully extending your hip and knee.", "Hold for a count of two and squeeze your gluteus maximus.", "Inhale as you lower the bar to the starting position. Do not allow the bar to make contact with the safety pins.", "Repeat for the prescribed number of repetitions.", "Repeat the repetitions with your opposite leg."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/06/Smith-kneeling-rear-kick-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/smith-machine-kneeling-rear-kick/"}, {"id": "dumbbell-forward-leaning-lunge", "name": "Dumbbell forward-leaning lunge", "name_ko": "런지", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand holding a dumbbell to each side.", "Exhale as you take a large step forward with one leg and lower your body until the knee of your back leg almost touches the floor.", "At the same time, allow your torso to tilt forward 15 to 20 degrees, and allow the dumbbells to hang straight down without bending your back.", "Exhale as you push yourself back up and step back into the starting position.", "Repeat with your opposite leg."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/05/dumbbell-forward-leaning-lunge-wide-resized-fixed.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-forward-leaning-lunge/"}, {"id": "captains-chair-leg-and-hip-raise", "name": "Captain’s chair leg and hip raise", "name_ko": "Captain’s chair leg and hip raise", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Get into the captain’s chair with your forearms on the pads, your hands on the handles, your back against the back pad, and your legs hanging straight down.", "Press your lower back against the back pad.", "Keeping your feet together, exhale as you raise your knees towards your chest by flexing your knees, hips, and your waist.", "Try to hold the end position for a count of two.", "Inhale as you lower your feet to the starting position in a controlled manner.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/05/captains-chair-leg-and-hip-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/captains-chair-leg-and-hip-raise/"}, {"id": "barbell-sumo-squat", "name": "Barbell sumo squat", "name_ko": "스쿼트", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Place a barbell on the back of your shoulders and hold it at each side.", "Stand with your feet wider than shoulder-width apart.", "Point your toes and knees 30 to 45 degrees out to the sides (i.e. sumo or plié stance).", "Keeping your head up, back straight, and body upright, inhale as you squat by simultaneously flexing your hips and knees, and descend at least until your thighs are parallel with the floor.", "Exhale as you return to a standing position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/05/barbell-sumo-squat-resized-new.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-sumo-squat/"}, {"id": "barbell-hip-thrust", "name": "Barbell hip thrust", "name_ko": "힙 스러스트", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Place a loaded barbell next to, and parallel to, a bench.", "Slide your legs under the barbell and sit on the floor with your back against the side of a bench. The barbell should be over your hips.", "Grasp the barbell at each side.", "Bend your knees and place your feet flat on the floor, approximately shoulder-width apart.", "Keeping your torso rigid, exhale as you raise the barbell by extending your hips until they are fully extended.", "Hold for a count of two and squeeze your glutes.", "Inhale as you lower the barbell by flexing your hips. Do not allow the barbell to touch the floor.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/04/barbell-hip-thrust-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-hip-thrust/"}, {"id": "stability-ball-jackknife", "name": "Stability ball jackknife", "name_ko": "Stability ball jackknife", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Get into a push-up position with your shins resting on top of a stability ball. You can do this by kneeling in front of a stability ball, lying with your waist on top of the ball, and then crawling forward on your hands over the ball until your shins are in position.", "Exhale as you flex your knees, hips, and waist and pull your knees all the way up toward your chest. Allow your shins to roll over the ball.", "Inhale as you extend your knees, hips, and waist and return your legs and the ball to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/04/stability-ball-jack-knife-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/stability-ball-jackknife/"}, {"id": "barbell-side-lunge", "name": "Barbell side lunge", "name_ko": "런지", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Place a barbell on the back of your shoulders. You can either dismount the barbell from a high rack or clean it from the floor.", "Keeping your body upright, inhale as you take a large step (lunge) to one side and lower your body by flexing your hip and knee. Keep your back leg straight.", "Exhale as you push yourself back up to the starting position.", "Repeat the lunge with your opposite leg.", "Keep repeating the lunge and alternating the leg with which you lead."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/04/Barbell-Side-lunge-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-side-lunge/"}, {"id": "barbell-straight-back-stiff-leg-deadlift", "name": "Barbell straight back stiff leg deadlift", "name_ko": "데드리프트", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Grasp a barbell using a shoulder-width pronated (overhand) grip or a mixed grip.", "Keeping your back straight, head up, and hips low, lift the barbell into a standing position.", "Flex your knees a little.", "Keeping your back straight and your knees slightly flexed (stiff), inhale as you push your hips backward and slowly lower the barbell down the front of your legs. Descend until you feel a mild stretch in your hamstrings.", "Exhale as you pull the barbell back up to the starting position by pushing your hips forward.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/03/barbell-straight-leg-deadlift-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-straight-back-stiff-leg-deadlift/"}, {"id": "standing-ab-wheel-rollout", "name": "Standing ab wheel rollout", "name_ko": "Standing ab wheel rollout", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand holding an ab wheel using a pronated (overhand) grip.", "Flex your hips and lower the wheel to the floor in front of your feet.", "Lean forward a little so that the ab wheel supports your weight.", "Keeping your elbows slightly flexed, inhale as you slowly roll out as far as you can without allowing your lower back to sag.", "Hold for a count of two.", "Exhale as you slowly roll back in to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/03/standing-wheel-rollout-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/standing-ab-wheel-rollout/"}, {"id": "kneeling-cable-hip-extension", "name": "Kneeling cable hip extension", "name_ko": "Kneeling cable hip extension", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Set up a low cable pulley.", "Strap the cable around your foot. You can also strap it to your ankle if it doesn’t slip up and down your leg.", "Kneel on a bench, with your torso horizontal and the strapped leg extended off the side of the bench.", "Keeping your knee slightly flexed, exhale as you pull the cable backward by slowly extending your hip. Pull until your foot is either level with, or a little higher than, your torso.", "Hold for a count of two and squeeze your glute.", "Inhale as you slowly lower the cable to the starting position by flexing your hip.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise with your opposite leg."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/03/kneeling-cable-hip-extension-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/kneeling-cable-hip-extension/"}, {"id": "bodyweight-sumo-squat", "name": "Bodyweight sumo squat", "name_ko": "스쿼트", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand with your feet wider than shoulder-width apart.", "Point your toes and knees 30 to 45 degrees out to the sides (sumo stance).", "Keeping your head up and torso upright, inhale as you squat by simultaneously flexing your hips and knees, making sure to descend at least until your thighs are parallel with the floor. As you descend, raise your arms straight out in front of you to help you to keep balance.", "Hold for a count of two.", "Exhale as you return to a standing position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/02/Sumo-Squat-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/bodyweight-sumo-squat/"}, {"id": "dumbbell-sumo-squat", "name": "Dumbbell sumo squat", "name_ko": "스쿼트", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Grasp one end of a dumbbell with both hands.", "Stand with your feet wide apart and pointing 30 to 45 degrees out to the sides (sumo stance).", "Allow your arms to rest on the front of your body so that the other end of the dumbbell hangs downward between your legs.", "Keeping your arms fixed and your torso upright, inhale as you lower the dumbbell toward the floor by flexing your hips and knees. Descend at least until your thighs are parallel with the floor.", "Hold for a count of two.", "Exhale as you push yourself back up to a standing position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/02/dumbbell-sumo-squat-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-sumo-squat/"}, {"id": "dumbbell-rear-lunge", "name": "Dumbbell rear lunge", "name_ko": "런지", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Holding a pair of dumbbells by your sides, stand up straight.", "Keeping your torso upright, inhale as you take a large step backward with one leg and plant your forefoot behind you. As you do so, flex the knee and hip of your front leg to allow yourself to descend into a kneeling position. However, do not allow your rear knee to make contact with the floor.", "Exhale as you get back up into the starting position by extending the knee and hip of your front leg and pushing off with your rear leg.", "Repeat the movement with your opposite leg.", "Keep alternating the leg with which your lunge backward."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Dumbbell-Lunge-resized-fixed.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-rear-lunge/"}, {"id": "barbell-bulgarian-split-squat", "name": "Barbell Bulgarian split squat", "name_ko": "스쿼트", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Place a barbell on the back of your shoulders and grasp it firmly at both sides.", "Stand with your back facing the side of a bench.", "Place the top of one foot on the bench behind you so that only one of your feet is making contact with the floor.", "Keeping your torso upright, inhale as you squat down with your supporting leg until the knee of your back leg nearly touches the floor.", "Exhale as you push yourself back up to the starting position.", "Repeat for the desired number of repetitions.", "Repeat the repetitions with your opposite leg."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/02/Barbell-Bulgarian-Split-Squat-resized-fixed.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-bulgarian-split-squat/"}, {"id": "barbell-kneeling-squat", "name": "Barbell kneeling squat", "name_ko": "스쿼트", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Set up a barbell in a power rack or Smith machine at kneeling shoulder height. If using a power rack, ensure that the safety pins are in place at an appropriate height.", "Kneel under the bar, on a soft mat to protect your knees.", "Position the back of your shoulders under the bar, and grasp the bar at both sides.", "Dismount the bar by extending your hips. If using a Smith machine, you will have to rotate the bar to unlatch it from the rail.", "Keeping your head up and your back straight, inhale as you flex your hips and sit back until your buttocks touch your calves.", "Exhale as you extend your hips and return the bar to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/02/barbell-kneeling-squat-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-kneeling-squat/"}, {"id": "barbell-rollout", "name": "Barbell rollout", "name_ko": "Barbell rollout", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Kneel on the floor with a loaded barbell in front of your knees.", "Grasp the barbell using a narrow pronated (overhand) grip.", "Lean over the barbell so that it supports your upper body.", "Keeping your elbows slightly bent, inhale as you gently roll out for as far as you can maintain a straight back.", "Exhale as you reverse the movement and roll back in to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/01/barbell-rollout-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-rollout/"}, {"id": "dumbbell-leg-curl", "name": "Dumbbell leg curl", "name_ko": "레그 컬", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Place a dumbbell on its end next to the lower end of a flat bench.", "Lie prone (on your front) on the bench, with your knees close to the edge.", "Pinch the dumbbell between the arches of your feet.", "Grasp the sides or legs of the bench for stability.", "Keeping your legs and feet squeezed together, exhale as you curl the dumbbell up toward your buttocks. Make sure that the soles of your feet face the ceiling at all times.", "Inhale as you slowly lower the dumbbell back toward the starting position until your knees are almost fully extended.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/01/dumbbell-leg-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-leg-curl/"}, {"id": "weighted-sissy-squat", "name": "Weighted sissy squat", "name_ko": "스쿼트", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Holding a plate across your chest with one arm, stand with your feet shoulder-width apart, flat, and pointing slightly out to the sides.", "With your free hand, grasp something secure at waist height, such as a fixed bar or bench.", "Keeping your back and hips straight, inhale as you flex your knees forward in the direction that your feet are pointing, and allow your body to tilt backward and your heels to rise off the floor.", "Descend until your knees are almost fully flexed, making sure not to fall backward.", "Exhale as you reverse the motion and return to the starting position.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/01/weighted-sissy-squat-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/weighted-sissy-squat/"}, {"id": "smith-chair-squat", "name": "Smith machine chair squat", "name_ko": "스쿼트", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Set the Smith machine bar to just under shoulder height.", "Stand under the bar with the bar across the back of your shoulders, and grasp it at both sides.", "Unlatch the bar by rotating it, and stand erect to lift it off the rack.", "Take a step forward and stand with your feet shoulder-width apart, with your feet pointing slightly out to the sides.", "Keeping your back straight and your torso upright, inhale as you lower the bar by flexing your hips and knees. Descend until your thighs are at least parallel with the floor.", "Exhale as you push the bar back up by extending your hips and knees, driving through your heels.", "Repeat.", "Once finished, latch the bar back on to the rail by rotating it."], "image_url": "https://weighttraining.guide/wp-content/uploads/2017/01/smith-chair-squat-reized-FIXED.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/smith-chair-squat/"}, {"id": "jefferson-squat", "name": "Jefferson squat", "name_ko": "스쿼트", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Place a loaded barbell on the floor.", "Straddle the center of the barbell and stand with your feet shoulder width (or wider) apart. Your feet should be pointing a little out to the sides.", "Squat and grasp the barbell, placing one hand in front of you and the other hand behind you.", "Keeping your chest up and your back straight, stand and lift the barbell between your legs.", "Keeping your chest up and your back straight, inhale as you squat down at least until your knees are bent at a 90-degree angle.", "Exhale as you stand back up to the starting position, driving through your heels.", "Repeat for the prescribed number of repetitions.", "Swap the front and back placements of your hands and repeat the exercise."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/12/jefferson-squat-resized-fixed-2.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/jefferson-squat/"}, {"id": "hanging-straight-leg-raise-2", "name": "Hanging straight leg raise", "name_ko": "Hanging straight leg raise", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Using a shoulder-width pronated (overhand) grip, hang from a secure bar.", "Straighten your lower back by tilting your pelvis backward.", "Keeping your back and knees straight, and your feet together, exhale as you slowly raise your legs by flexing your hips.", "Hold for a count of two.", "Inhale as you slowly lower your legs in a controlled manner by extending your hips.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/12/hanging-straight-leg-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/hanging-straight-leg-raise-2/"}, {"id": "stability-ball-leg-extension-crunch", "name": "Stability ball leg extension crunch", "name_ko": "레그 익스텐션", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Lie supine (on your back) on the floor with your knees bent and a stability ball clasped between your feet.", "Place your hands behind your head.", "Raise the ball off the floor a little by flexing your hips.", "Press your lower back against the floor to keep it supported.", "Exhale as you simultaneously flex your abdomen to raise your upper back off the floor (crunch) and extend your knees to raise the stability ball into the air (leg extension).", "Hold for a count of two.", "Inhale as you simultaneously relax your abdomen and flex your knees to lower your upper back and the stability ball to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/12/stability-ball-leg-extension-crunch-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/stability-ball-leg-extension-crunch/"}, {"id": "kneeling-leg-curl", "name": "Kneeling leg curl", "name_ko": "레그 컬", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Kneel on the knee pad with one knee.", "Place your opposite leg under the lever pad and rest your knee against the front pad.", "Position your forearms on the arm rest.", "Grasp the handles for support.", "Exhale as you flex your knee and raise the lever to the back of your thigh.", "Hold for a count of two and squeeze your hamstrings.", "Inhale as you lower the lever to the starting position by extending your knee.", "Repeat for the prescribed number of repetitions.", "To work your opposite leg, move the knee pad to the other side and repeat the exercise."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/12/Kneeling-Leg-Curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/kneeling-leg-curl/"}, {"id": "cable-squat", "name": "Cable squat", "name_ko": "스쿼트", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand between two low pulleys with your feet shoulder-width apart. The pulleys must be as close to your legs as possible.", "Bend over and grasp a stirrup in each hand.", "Lower your hips, straighten your back, and raise your torso upright. The cables should be pulled taut.", "Keeping your feet flat, arms straight, and chest up, stand and pull the stirrups upward. Exhale as you do so.", "Inhale as you squat back down by pushing your butt backward and bending your knees forward. Descend at least until your thighs are parallel with the floor.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/12/Cable-squat-resized-fixed.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-squat/"}, {"id": "sled-calf-press", "name": "Sled calf press", "name_ko": "Sled calf press", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Sit in the sled/leg press machine with your back pressed against the back support.", "Place your feet flat in the center of the platform.", "Hold the handles for stability.", "Push the platform up until your knees are almost fully extended.", "Position the balls of your feet on the bottom edge of the platform so that the arches and heels of your feet extend off.", "Exhale as you extend your ankles to push the platform up.", "Hold for a count of two and squeeze your calves.", "Inhale as you flex your ankles to lower the platform until you feel a mild stretch in your calves.", "Hold for a second to allow the stored elastic energy in your calves to dissipate.", "Repeat the press."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/12/sled-calf-press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/sled-calf-press/"}, {"id": "dumbbell-squat", "name": "Dumbbell squat", "name_ko": "스쿼트", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand holding a pair of dumbbells by your sides. Your feet should be shoulder-width apart and pointing slightly outward.", "Keeping your torso upright and your shoulders back, inhale as you squat down by pushing your butt backward and bending your knees forward. Descend at least until your thighs are parallel with the floor.", "Exhale as you push yourself back up to a standing position, driving from your heels.", "Repeat for the prescribed number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/12/dumbbell-squat-resized-FIXED.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-squat/"}, {"id": "barbell-hack-squat", "name": "Barbell hack squat", "name_ko": "스쿼트", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand in front of a barbell with your feet shoulder-width apart and pointing slightly out to the sides.", "Bend down and grasp the barbell from behind using a pronated (overhand) grip.", "Keeping your back straight and your chest up, stand up and lift the barbell up the backs of your legs.", "Inhale as you flex your knees and hips and lower the barbell either to the floor or at least until your thighs are horizontal.", "Exhale as you stand back up and lift the barbell up along the backs of your legs, driving through your heels.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/barbell-hack-squat-resized-fixed.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-hack-squat/"}, {"id": "dumbbell-bulgarian-split-squat", "name": "Dumbbell Bulgarian split squat", "name_ko": "스쿼트", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Holding a pair of dumbbells by your sides, stand with your back facing the side of a bench. There should be three or four feet of space between you and the bench.", "Extend one leg backward and place the top of your foot on the bench so that your body is being supported by only one leg.", "Keeping your torso upright, inhale as you squat down with your supporting leg until the knee of your back leg nearly touches the floor.", "Exhale as you push yourself back up to the starting position, driving through your heel.", "Repeat for the prescribed number of repetitions.", "Repeat the exercise with your opposite leg."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/Dumbbell-Bulgarian-Split-Squat-resized-FIXED.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-bulgarian-split-squat/"}, {"id": "dumbbell-step-up", "name": "Dumbbell step-up", "name_ko": "Dumbbell step-up", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Holding a pair of dumbbells by your sides, stand facing a raised platform, such as a bench.", "Exhale as you slowly step up onto the bench, leading with your right leg.", "Bring your feet together on the bench.", "Inhale as you slowly step down off the bench, leading with your right leg.", "Bring your feet together on the floor.", "Repeat, alternating the leg with which you step up and down off the bench."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/dumbbell-step-up-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-step-up/"}, {"id": "bicycle-crunch", "name": "Bicycle crunch", "name_ko": "크런치", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Lie supine (on your back) with your legs straight.", "Place your hands behind your head.", "Raise your feet and upper back a little off the floor.", "Press your lower back to the ground.", "Slowly start raising your knees, one at a time, toward your chest in a cycling motion.", "Touch your left elbow to your right knee, and your right elbow to your left knee.", "Keep repeating.", "Breathe naturally."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/bicycle-crunch-resized-1.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/bicycle-crunch/"}, {"id": "zercher-squat", "name": "Zercher squat", "name_ko": "스쿼트", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Place a barbell on a waist-high rack and load it.", "Keeping your elbows tucked in to your sides, scoop the barbell up with the crooks of your elbows, pull it into your body, and cross your wrists over the bar to hold it in place.", "Carefully step backward from the rack and stand with a wide stance, with your knees and feet pointing out diagonally in the same direction.", "Keeping your back straight and body upright, inhale as you squat down until the bar touches your thighs.", "Exhale as you stand back up into the starting position, driving through your heels.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/Zercher-squat-new.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/zercher-squat/"}, {"id": "v-up", "name": "V-up", "name_ko": "V-up", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Lie supine (on your back) on the floor with your legs straight and your arms held straight by the sides of your head.", "Keeping your arms and legs straight, exhale as you raise your legs and torso and try to touch your toes.", "Try to hold the contracted position.", "Inhale as you lie back into the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/v-up-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/v-up/"}, {"id": "seated-knee-raise", "name": "Seated leg raise", "name_ko": "Seated leg raise", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Sit on the edge of a bench with your legs extended in front of you.", "Grasp the edge of the bench for support.", "Lean backward and raise your legs a little off the floor, keeping them straight and together.", "Exhale as you lean forward and raise your knees toward your chest.", "Inhale as you lean backward and return your legs to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/seated-knee-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-knee-raise/"}, {"id": "single-leg-hip-thrust", "name": "Single leg glute bridge", "name_ko": "글루트 브릿지", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Lie supine (on your back) on the floor, with your legs straight.", "Flex your right knee and place your right foot flat on the floor.", "Place your arms by your sides for support.", "Keeping your left leg straight and level with your torso, exhale as you raise your body off the floor by extending your right hip.", "Hold for a count of two.", "Inhale as you slowly lower your body to the starting position.", "Repeat for the prescribed number of repetitions.", "Repeat with your opposite leg."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/single-leg-hip-thrust-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/single-leg-hip-thrust/"}, {"id": "high-reverse-plank", "name": "High reverse plank", "name_ko": "플랭크", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Sit on the floor with your legs together and extended in front of you.", "Place your hands on the floor behind you.", "Raise your hips off the floor until your body is straight.", "Hold this position for the prescribed amount of time.", "Breathe naturally.", "When finished, lower your hips back to the ground."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/11/high-reverse-plank-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/high-reverse-plank/"}, {"id": "lying-alternating-knee-raise", "name": "Lying alternating knee raise", "name_ko": "Lying alternating knee raise", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Lie supine (on your back).", "Place your hands either behind your head, by your sides, or under your buttocks to raise and support your pelvis.", "Slightly raise both legs off the floor.", "Press your lower back flat against the floor so that it is supported.", "Raise one knee toward your chest.", "Lower the same leg to the starting position.", "As that leg is being lowered, raise your other knee toward your chest.", "Lower the same leg to the starting position.", "Keep alternating these leg movements, raising one knee as the opposite leg is being lowered.", "Breathe naturally."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/lying-alternating-leg-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lying-alternating-knee-raise/"}, {"id": "cable-pull-through", "name": "Cable pull-through", "name_ko": "Cable pull-through", "category": "strength", "equipment": "cable", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Grasp the rope attachment of a low pulley, one end in each hand, with the rubber ends making contact with your thumbs.", "Straddle the rope so that your back faces the pulley and the cable runs between your legs.", "Step forward until the rope is pulled taut, and stand with your feet shoulder-width apart.", "Bend your knees slightly, and flex your hips and waist until you feel a slight stretch in your hamstrings.", "Keeping your arms straight, exhale as you stand up straight and pull the rope up through your legs.", "Hold for a count of two and squeeze your glutes.", "Inhale as you reverse the motion and lower the rope to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Cable-Pull-Through-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/cable-pull-through/"}, {"id": "hanging-leg-hip-raise", "name": "Hanging leg and hip raise", "name_ko": "Hanging leg and hip raise", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Hang from a high bar with your hands shoulder-with apart, your arms fully extended, and your legs straight.", "Straighten your lower back by tilting your pelvis backward.", "Exhale as you slowly raise your knees as high as possible by flexing your hips and your abdomen.", "Hold for a count of two.", "Inhale as you slowly lower your legs to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Hanging-leg-hip-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/hanging-leg-hip-raise/"}, {"id": "lying-side-hip-raise", "name": "Lying side hip raise", "name_ko": "Lying side hip raise", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Lie on your side on the floor or on a mat, supporting your upper body on your elbow and forearm. Your forearm should be positioned perpendicular to your body, your elbow should be directly underneath your shoulder, and your feet should be stacked on top of one another.", "Place your free hand on your hip.", "Exhale as you raise your hip off the floor as high as possible by laterally flexing your spine and pushing down with your feet.", "Inhale as you lower your hip to the floor.", "Repeat.", "Repeat the exercise on your opposite side."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/lying-side-hip-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lying-side-hip-raise/"}, {"id": "lying-leg-hip-raise", "name": "Lying leg and hip raise", "name_ko": "Lying leg and hip raise", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Lie supine (on your back) on a bench with your legs straight.", "Grasp the sides of the bench by your head for stability.", "Press your lower back against the bench so that it is supported.", "Exhale as you slowly flex your knees and hips and bring your knees toward your chest.", "Once your hips are fully flexed, curl your hips up off the bench by flexing your abdomen.", "Try to hold the contracted position for a second.", "Inhale as you slowly reverse the motions and return your legs to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/lying-leg-hip-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lying-leg-hip-raise/"}, {"id": "dumbbell-lunge", "name": "Dumbbell lunge", "name_ko": "런지", "category": "strength", "equipment": "dumbbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand with feet together, holding a dumbbell in each hand, with your arms by your sides.", "Inhale as you take a large step forward with one leg, landing on your heel first and then lowering your forefoot.", "At the same time, keeping your torso upright, lower your body until the knee of your supporting leg almost touches the floor.", "Exhale as you drive back up with your heel and step back into the starting position.", "Repeat with your opposite leg.", "Keep alternating the leg with which you lunge."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Dumbbell-Lunge-resized-fixed.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/dumbbell-lunge/"}, {"id": "barbell-lunge", "name": "Barbell lunge", "name_ko": "런지", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand holding a barbell on the back of your shoulders.", "Exhale as you take a large step (lunge) forward with one leg, landing on your heel first and then lowering your forefoot.", "At the same time, keeping your torso upright, lower your body until the knee of your supporting leg almost touches the floor.", "Inhale as you drive back up with your heel and step back into the starting position.", "Repeat with your other leg."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Barbell-Lunge-resized-fixed.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-lunge/"}, {"id": "barbell-front-squat", "name": "Barbell front squat", "name_ko": "스쿼트", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Load a barbell on a rack at upper-chest height.", "Step under the barbell so that it rests on the front of your shoulders and place your fingers under the barbell, with your elbows pointing forward (if you do not have the flexibility to place your fingers under the barbell, you can cross your arms and place your hands on top of the barbell).", "Dismount the barbell and step backward carefully. Your feet should be shoulder-width apart and pointing slightly outward.", "Inhale as you squat down by simultaneously pushing your butt backward and bending your knees forward. Keep your torso upright, and descend at least until your knees are bent at a 90-degree angle.", "Exhale as you push your body back up to the starting position, driving through your heels and keeping your torso upright.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/barbell-front-squat-new-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-front-squat/"}, {"id": "seated-leg-curl", "name": "Seated leg curl", "name_ko": "레그 컬", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Sit in the leg curl machine.", "Place the backs of your lower legs on top of the padded lever.", "Lower the thigh support so that it rests just above your knees (missing from illustration; see video).", "Hold the handles for support.", "Exhale as you flex your knees and curl the lever all the way to the back of your thighs.", "Hold for a count of two and squeeze your hamstrings.", "Inhale as you return the lever to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/seated-leg-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-leg-curl/"}, {"id": "machine-standing-calf-raise", "name": "Machine standing calf raise", "name_ko": "카프 레이즈", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Stand in the calf raise machine with the padded levers resting on your shoulders.", "Position the balls of your feet on the foot platform, with the arches and heels of your feet extending off.", "Hold the lever handles for support.", "Exhale as you push the levers up as far as possible by raising your heels.", "Hold for a count of two.", "Inhale as you slowly lower the levers until you feel a slight stretch in your calves.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Lever-Standing-Calf-Raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/machine-standing-calf-raise/"}, {"id": "lying-leg-curl", "name": "Lying leg curl", "name_ko": "레그 컬", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Lie prone (face down) on the leg curl bench and position your legs under the lever pads. Your knees should be just below the edge of the bench and the lever pads should be resting just above your heels.", "Hold the handles for stability.", "Exhale as you flex your knees and curl the lever until it touches the back of your thighs.", "Hold for a count of two.", "Inhale as you lower the lever to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/lying-leg-curl-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/lying-leg-curl/"}, {"id": "seated-calf-raise", "name": "Machine seated calf raise", "name_ko": "카프 레이즈", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Sit in the calf raise machine and place your forefeet on the foot platforms, with your heels extending off.", "Place your thighs under the lever pads and adjust the pads to snugly support your thighs.", "Lift the lever a little and release the safety bar, giving the lever freedom to descend.", "Hold the handles for support.", "Inhale as you allow the lever to descend in a controlled manner until you feel a stretch in your calves.", "Hold for a count of one.", "Exhale as you press the lever all the way up by raising your heels.", "Hold for a count of two.", "Repeat.", "When you have finished, secure the lever with the safety bar."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/Lever-Seated-Calf-Raise-plate-loaded-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/seated-calf-raise/"}, {"id": "barbell-squat", "name": "Barbell squat", "name_ko": "바벨 스쿼트", "category": "strength", "equipment": "barbell", "difficulty": "intermediate", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Load a barbell on a rack at upper-chest height.", "Step under the barbell so that it rests on the back of your shoulders, and grasp the bar at each side.", "Dismount the barbell and step backward carefully. Your feet should be shoulder-width apart and pointing slightly outwards.", "Inhale as you squat down by simultaneously pushing your butt backward and bending your knees forward. Keep your torso upright, and descend at least until your knees are bent at a 90-degree angle.", "Exhale as you push your body back up to the starting position, driving through your heels and keeping your torso upright.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/barbell-squat-resized-FIXED-2.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/barbell-squat/"}, {"id": "wheel-rollout", "name": "Wheel rollout", "name_ko": "Wheel rollout", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Kneel on the floor holding both handles of the wheel using a pronated (overhand) grip.", "Place the wheel in front of your knees and lean over it so that it supports your upper body.", "Straighten your lower back. You must maintain a straight lower back when you roll out. Your lower back must not sag.", "Inhale as you gently roll out for as far as you can hold a straight lower back.", "Exhale as you reverse the motion and roll back to the starting position."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/10/wheel-rollout-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/wheel-rollout/"}, {"id": "hanging-straight-leg-hip-raise", "name": "Hanging straight leg and hip raise", "name_ko": "Hanging straight leg and hip raise", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Hang from a high bar with your hands shoulder-with apart, your arms fully extended, and your legs hanging straight down.", "Straighten your lower back by tilting your pelvis backward.", "Keeping your knees straight, slowly raise your legs as high as possible by flexing your hips and your abdomen. Don’t forget to exhale.", "Hold for a count of two.", "Inhale as you slowly lower your legs to the starting position.", "Repeat for the desired number of repetitions."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/06/hanging-straight-leg-hip-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/hanging-straight-leg-hip-raise/"}, {"id": "leg-extension", "name": "Leg extension", "name_ko": "레그 익스텐션", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Choose your weight and sit on the leg extension machine.", "Make the necessary adjustments so that the backs of your thighs are fully supported by the seat and your back is fully supported by the back rest.", "Hook your feet under the foot pads of the lever with the pads resting just above your ankles.", "Grasp the side handles for support.", "Exhale as you lift the lever forwards and upwards by straightening your legs until they are fully extended.", "Hold for a count of two.", "Inhale as you return the lever to the starting position by bending your knees.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/05/lever-leg-extension-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/leg-extension/"}, {"id": "incline-straight-leg-hip-raise", "name": "Incline straight leg and hip raise", "name_ko": "Incline straight leg and hip raise", "category": "strength", "equipment": "none", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Lie supine (on your back) on an inclined bench with your legs together.", "Place your hands beside your head and grip the bench for support.", "Press your lower back against the bench so that it is supported.", "Keeping your legs slightly bent, exhale as you slowly raise your legs and curl your hips off the bench by flexing your abdomen.", "Try to hold the contracted position, with your legs in the air, for a count of two.", "Inhale as you slowly lower your hips and legs to the starting position.", "Repeat."], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/05/incline-straight-leg-hip-raise-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-straight-leg-hip-raise/"}, {"id": "incline-leg-press", "name": "Incline leg press", "name_ko": "레그 프레스", "category": "strength", "equipment": "machine", "difficulty": "beginner", "primary_muscles": ["quads"], "secondary_muscles": [], "instructions": ["Sit in the leg press machine. Make sure your back is pressed firmly against the back support.", "Place your feet hip-width apart on the platform.", "Release the safety bars, grasp the side handles for support, and extend your legs without locking your knees. Your torso and legs should make a 90-degree angle.", "Inhale as you bend your legs and lower the platform until your knees are almost fully flexed.", "Driving with your heels, press the platform back up to the starting position as you exhale.", "Repeat.", "When you have finished, lock the safety bars properly. Otherwise, the platform may slide down onto your legs!"], "image_url": "https://weighttraining.guide/wp-content/uploads/2016/05/Sled-45-degree-Leg-Press-resized.png", "gif_url": null, "source_url": "https://weighttraining.guide/exercises/incline-leg-press/"}] as unknown as Exercise[]
